      <motion.span
        aria-hidden
        className="absolute inset-[-60%]"
        style={{
          background:
            "conic-gradient(from 0deg, transparent 0%, #10b981 12%, #f59e0b 20%, transparent 38%)",
        }}
        animate={{ opacity: active ? 1 : 0, rotate: shouldReduceMotion ? 0 : 360 }}
        transition={{
          opacity: { duration: 0.25, ease: "easeOut" },
          rotate: { duration: active ? 2 : 5.5, repeat: Infinity, ease: "linear" },
        }}
      />
      <span className="relative z-10 inline-flex items-center justify-center rounded-full bg-white px-5 py-2.5 text-sm font-medium text-slate-900 transition-colors duration-300 dark:bg-black dark:text-white">
        {children}
      </span>
    </button>
  );
}

"use client";

import { useEffect, useRef, useState, type ReactNode } from "react";
import { AnimatePresence, motion, useReducedMotion } from "framer-motion";

interface NotificationItem {
  id: number;
  title: string;
  time: string;
  read?: boolean;
}

export function NotificationButton({
  icon,
  label,
  notifications,
}: {
  icon: ReactNode;
  label: string;
  notifications: NotificationItem[];
}) {
  const [items, setItems] = useState(() => notifications.map((n) => ({ ...n, read: n.read ?? false })));
  const [open, setOpen] = useState(false);
  const [active, setActive] = useState(false);
  const rootRef = useRef<HTMLDivElement>(null);
  const shouldReduceMotion = useReducedMotion();
  const unreadCount = items.filter((n) => !n.read).length;

  useEffect(() => {
    if (!open) return;
    const onClick = (e: MouseEvent) => {
      if (rootRef.current && !rootRef.current.contains(e.target as Node)) setOpen(false);
    };
    document.addEventListener("mousedown", onClick);
    return () => document.removeEventListener("mousedown", onClick);
  }, [open]);

  const markRead = (id: number) => {
    setItems((list) => list.map((n) => (n.id === id ? { ...n, read: true } : n)));
  };

  const markAllRead = () => {
    setItems((list) => list.map((n) => ({ ...n, read: true })));
  };

  return (
    <div ref={rootRef} className="flex flex-col items-center">
      <motion.button
        type="button"
        aria-haspopup="menu"
        aria-expanded={open}
        aria-label={unreadCount > 0 ? `${label}, ${unreadCount} unread` : label}
        onClick={() => setOpen((v) => !v)}
        onMouseEnter={() => setActive(true)}
        onMouseLeave={() => setActive(false)}
        onFocus={() => setActive(true)}
        onBlur={() => setActive(false)}
        whileTap={shouldReduceMotion ? { scale: 0.94 } : { scale: 0.9, rotate: [0, -10, 8, -4, 0] }}
        transition={{ type: "spring", stiffness: 500, damping: 30 }}
        className="relative inline-flex h-10 w-10 items-center justify-center rounded-full focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-4 focus-visible:outline-emerald-600"
      >
        <span className="absolute inset-0 overflow-hidden rounded-full p-[1.5px]">
          <motion.span
            aria-hidden
            className="absolute inset-[-60%]"
            style={{
              background:
                "conic-gradient(from 0deg, transparent 0%, #10b981 12%, #f59e0b 20%, transparent 38%)",
            }}
            animate={shouldReduceMotion ? undefined : { rotate: 360 }}
            transition={{ duration: active || open ? 2 : 5.5, repeat: Infinity, ease: "linear" }}
          />
          <span className="relative z-10 inline-flex h-full w-full items-center justify-center rounded-full bg-white text-slate-600 transition-colors duration-300 dark:bg-black dark:text-slate-300">
            {icon}
          </span>
        </span>
        <AnimatePresence>
          {unreadCount > 0 && (
            <motion.span
              key={unreadCount}
              aria-hidden
              initial={shouldReduceMotion ? { opacity: 0 } : { opacity: 0, scale: 0.5 }}
              animate={{ opacity: 1, scale: 1 }}
              exit={shouldReduceMotion ? { opacity: 0 } : { opacity: 0, scale: 0.5 }}
              transition={{ type: "spring", stiffness: 500, damping: 25 }}
              className="absolute -top-1 -right-1 z-20 flex h-4 min-w-4 items-center justify-center rounded-full bg-amber-700 px-1 text-[10px] font-semibold leading-none text-white"
            >
              {unreadCount > 99 ? "99+" : unreadCount}
            </motion.span>
          )}
        </AnimatePresence>
      </motion.button>

      <AnimatePresence>
        {open && (
          <motion.div
            role="menu"
            aria-label={label}
            initial={{ opacity: 0, height: 0 }}
            animate={{ opacity: 1, height: "auto" }}
            exit={{ opacity: 0, height: 0 }}
            transition={
              shouldReduceMotion
                ? { duration: 0 }
                : { height: { duration: 0.25, ease: [0.22, 1, 0.36, 1] }, opacity: { duration: 0.15 } }
            }
            className="mt-2 w-72 max-w-full overflow-hidden rounded-xl border border-slate-200 bg-white shadow-lg dark:border-slate-700 dark:bg-neutral-950"
          >
            <div className="flex items-center justify-between border-b border-slate-100 px-3.5 py-2.5 dark:border-slate-800">
              <span className="text-sm font-semibold text-slate-900 dark:text-white">{label}</span>
              {unreadCount > 0 && (
                <button
                  type="button"
                  onClick={markAllRead}
                  className="text-xs font-medium text-emerald-700 hover:text-emerald-800 dark:text-emerald-400 dark:hover:text-emerald-300"
                >
                  Mark all read
                </button>
              )}
            </div>
            <ul className="max-h-64 overflow-y-auto py-1">
              {items.map((n) => (
                <li key={n.id}>
                  <button
                    type="button"
                    role="menuitem"
                    onClick={() => markRead(n.id)}
                    className="flex w-full items-start gap-2.5 px-3.5 py-2.5 text-left transition-colors hover:bg-slate-50 dark:hover:bg-slate-800/60"
                  >
                    <span
                      aria-hidden
                      className={`mt-1.5 h-1.5 w-1.5 shrink-0 rounded-full ${n.read ? "bg-transparent" : "bg-amber-500"}`}
                    />
                    <span className="flex-1">
                      <span
                        className={`block text-sm ${n.read ? "text-slate-500 dark:text-slate-400" : "font-medium text-slate-900 dark:text-white"}`}
                      >
                        {n.title}
                      </span>
                      <span className="mt-0.5 block text-xs text-slate-400 dark:text-slate-500">{n.time}</span>
                    </span>
                  </button>
                </li>
              ))}
            </ul>
          </motion.div>
        )}
      </AnimatePresence>
    </div>
  );
}

"use client";

import { useEffect, useRef, useState } from "react";
import { AnimatePresence, motion, useReducedMotion } from "framer-motion";
import { ArrowCounterClockwiseIcon as PhReset, ClockCounterClockwiseIcon as PhHistory } from "@phosphor-icons/react";

interface Snapshot {
  id: number;
  headline: string;
  bio: string;
}

const DEFAULT_HEADLINE = "Product designer, ex-Figma";
const DEFAULT_BIO = "I like clean interfaces and stubborn bugs.";
const COMMIT_DELAY = 900;
const FLASH_MS = 550;

function ResetIcon() {
  return <PhReset size={13} aria-hidden />;
}
function HistoryIcon() {
  return <PhHistory size={13} aria-hidden />;
}

function PendingRing({ progress }: { progress: number }) {
  const size = 10;
  const strokeWidth = 2;
  const radius = (size - strokeWidth) / 2;
  const circumference = 2 * Math.PI * radius;
  return (
    <svg width={size} height={size} viewBox={`0 0 ${size} ${size}`} className="-rotate-90" aria-hidden>
      <circle cx={size / 2} cy={size / 2} r={radius} fill="none" stroke="currentColor" strokeOpacity={0.25} strokeWidth={strokeWidth} className="text-slate-400 dark:text-slate-600" />
      <circle
        cx={size / 2}
        cy={size / 2}
        r={radius}
        fill="none"
        stroke="currentColor"
        strokeWidth={strokeWidth}
        strokeLinecap="round"
        strokeDasharray={circumference}
        strokeDashoffset={circumference * (1 - progress)}
        className="text-emerald-500"
      />
    </svg>
  );
}

function initialHistory(): Snapshot[] {
  return [{ id: 0, headline: DEFAULT_HEADLINE, bio: DEFAULT_BIO }];
}

interface HistoryRailProps {
  className?: string;
}

export function HistoryRail({ className }: HistoryRailProps) {
  const [history, setHistory] = useState<Snapshot[]>(initialHistory);
  const [pointer, setPointer] = useState(0);
  const [headline, setHeadline] = useState(DEFAULT_HEADLINE);
  const [bio, setBio] = useState(DEFAULT_BIO);
  const [flash, setFlash] = useState(false);
  const [hoverId, setHoverId] = useState<number | null>(null);
  const [pendingProgress, setPendingProgress] = useState(0);
  const [celebrateId, setCelebrateId] = useState<number | null>(null);
  const debounceRef = useRef<ReturnType<typeof setTimeout> | null>(null);
  const flashTimeoutRef = useRef<ReturnType<typeof setTimeout> | null>(null);
  const celebrateTimeoutRef = useRef<ReturnType<typeof setTimeout> | null>(null);
  const shouldReduceMotion = useReducedMotion();

  const committed = history[pointer];
  const isPending = !committed || committed.headline !== headline || committed.bio !== bio;

  const celebrate = (id: number) => {
    setCelebrateId(id);
    if (celebrateTimeoutRef.current) clearTimeout(celebrateTimeoutRef.current);
    celebrateTimeoutRef.current = setTimeout(() => setCelebrateId(null), 650);
  };

  const commitSnapshot = () => {
    const current = history[pointer];
    if (current && current.headline === headline && current.bio === bio) return;
    const truncated = history.slice(0, pointer + 1);
    const created = { id: Date.now(), headline, bio };
    const next = [...truncated, created];
    setHistory(next);
    setPointer(next.length - 1);
    celebrate(created.id);
  };

  useEffect(() => {
    if (debounceRef.current) clearTimeout(debounceRef.current);
    debounceRef.current = setTimeout(commitSnapshot, COMMIT_DELAY);
    return () => {
      if (debounceRef.current) clearTimeout(debounceRef.current);
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [headline, bio]);

  useEffect(() => {
    if (!isPending) {
      setPendingProgress(0);
      return;
    }
    const start = performance.now();
    let raf: number;
    const tick = () => {
      const elapsed = performance.now() - start;
      setPendingProgress(Math.min(1, elapsed / COMMIT_DELAY));
      if (elapsed < COMMIT_DELAY) raf = requestAnimationFrame(tick);
    };
    raf = requestAnimationFrame(tick);
    return () => cancelAnimationFrame(raf);
  }, [isPending, headline, bio]);

  useEffect(() => {
    return () => {
      if (debounceRef.current) clearTimeout(debounceRef.current);
      if (flashTimeoutRef.current) clearTimeout(flashTimeoutRef.current);
      if (celebrateTimeoutRef.current) clearTimeout(celebrateTimeoutRef.current);
    };
  }, []);

  const jumpTo = (index: number) => {
    if (index === pointer) return;
    if (debounceRef.current) clearTimeout(debounceRef.current);
    commitSnapshot();
    const snap = history[index];
    if (!snap) return;
    setPointer(index);
    setHeadline(snap.headline);
    setBio(snap.bio);
    setFlash(true);
    celebrate(snap.id);
    if (flashTimeoutRef.current) clearTimeout(flashTimeoutRef.current);
    flashTimeoutRef.current = setTimeout(() => setFlash(false), FLASH_MS);
  };

  const reset = () => {
    if (debounceRef.current) clearTimeout(debounceRef.current);
    if (flashTimeoutRef.current) clearTimeout(flashTimeoutRef.current);
    if (celebrateTimeoutRef.current) clearTimeout(celebrateTimeoutRef.current);
    setHistory(initialHistory());
    setPointer(0);
    setHeadline(DEFAULT_HEADLINE);
    setBio(DEFAULT_BIO);
    setFlash(false);
    setCelebrateId(null);
  };

  return (
    <div className={className}>
      <div className="w-full rounded-2xl border border-slate-200/70 bg-white/95 p-5 shadow-sm backdrop-blur-xl dark:border-white/10 dark:bg-neutral-950/80">
        <div className="flex items-center justify-between gap-3">
          <div className="flex items-center gap-1.5 text-slate-500 dark:text-slate-400">
            <HistoryIcon />
            <span className="text-xs font-semibold uppercase tracking-wide">Edit history</span>
          </div>
          <motion.button
            type="button"
            onClick={reset}
            aria-label="Reset history"
            whileTap={shouldReduceMotion ? undefined : { scale: 0.9 }}
            className="flex h-7 w-7 shrink-0 items-center justify-center rounded-lg text-slate-400 transition-colors hover:bg-black/5 hover:text-slate-600 focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-slate-400 dark:hover:bg-white/10 dark:hover:text-slate-300"
          >
            <ResetIcon />
          </motion.button>
        </div>
        <p className="mt-1 text-xs text-slate-400 dark:text-slate-500">
          Checkpoint {pointer + 1} of {history.length}
          {isPending ? ", recording your latest edit" : ""}.
        </p>

        <div className="relative mt-3 flex h-8 items-center">
          <div className="absolute inset-x-0 top-1/2 h-px -translate-y-1/2 bg-slate-200 dark:bg-white/10" />
          <div className="relative flex items-center gap-2.5">
            <AnimatePresence initial={false}>
              {history.map((snap, i) => {
                const isCurrent = i === pointer;
                const isFuture = i > pointer;
                return (
                  <motion.button
                    key={snap.id}
                    type="button"
                    onClick={() => jumpTo(i)}
                    onMouseEnter={() => setHoverId(snap.id)}
                    onMouseLeave={() => setHoverId((h) => (h === snap.id ? null : h))}
                    onFocus={() => setHoverId(snap.id)}
                    onBlur={() => setHoverId((h) => (h === snap.id ? null : h))}
                    aria-label={`Checkpoint ${i + 1}${isCurrent ? ", current" : ""}`}
                    aria-current={isCurrent}
                    initial={shouldReduceMotion ? { opacity: 0 } : { opacity: 0, scale: 0.4 }}
                    animate={{ opacity: 1, scale: 1 }}
                    exit={shouldReduceMotion ? { opacity: 0 } : { opacity: 0, scale: 0.4 }}
                    whileTap={shouldReduceMotion ? undefined : { scale: 0.8 }}
                    transition={{ type: "spring", stiffness: 500, damping: 26 }}
                    className="relative flex shrink-0 items-center justify-center focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-emerald-600"
                    style={{ width: isCurrent ? 16 : 10, height: isCurrent ? 16 : 10 }}
                  >
                    {celebrateId === snap.id && !shouldReduceMotion && (
                      <motion.span
                        aria-hidden
                        className="absolute rounded-full border-2 border-emerald-400/60"
                        style={{ inset: -3 }}
                        initial={{ scale: 0.7, opacity: 0.9 }}
                        animate={{ scale: 1.9, opacity: 0 }}
                        transition={{ duration: 0.6, ease: [0.16, 1, 0.3, 1] }}
                      />
                    )}
                    <span
                      className={`h-full w-full rounded-full border-2 transition-colors ${
                        isCurrent
                          ? "border-emerald-600 bg-emerald-600"
                          : isFuture
                            ? "border-dashed border-amber-400/70 bg-transparent"
                            : "border-slate-300 bg-slate-300 dark:border-slate-600 dark:bg-slate-600"
                      }`}
                    />
                    <AnimatePresence>
                      {hoverId === snap.id && !isCurrent && (
                        <motion.span
                          role="tooltip"
                          initial={shouldReduceMotion ? { opacity: 0 } : { opacity: 0, y: 4, scale: 0.9 }}
                          animate={{ opacity: 1, y: 0, scale: 1 }}
                          exit={shouldReduceMotion ? { opacity: 0 } : { opacity: 0, y: 4, scale: 0.9 }}
                          transition={{ type: "spring", stiffness: 500, damping: 30 }}
                          className="pointer-events-none absolute -top-9 left-1/2 z-10 flex max-w-[160px] -translate-x-1/2 items-center gap-1 whitespace-nowrap rounded-md bg-slate-900 px-2 py-1 text-xs font-medium text-white dark:bg-slate-100 dark:text-slate-900"
                        >
                          {snap.headline || "Empty headline"}
                          <span aria-hidden className="absolute left-1/2 top-full -mt-1 h-2 w-2 -translate-x-1/2 rotate-45 bg-slate-900 dark:bg-slate-100" />
                        </motion.span>
                      )}
                    </AnimatePresence>
                  </motion.button>
                );
              })}
            </AnimatePresence>
            <AnimatePresence>
              {isPending && (
                <motion.span
                  initial={shouldReduceMotion ? { opacity: 0 } : { opacity: 0, scale: 0.4 }}
                  animate={{ opacity: 1, scale: 1 }}
                  exit={shouldReduceMotion ? { opacity: 0 } : { opacity: 0, scale: 0.4 }}
                  transition={{ type: "spring", stiffness: 500, damping: 26 }}
                  className="flex shrink-0 items-center gap-1.5"
                >
                  <PendingRing progress={pendingProgress} />
                  <span className="whitespace-nowrap text-[11px] text-emerald-600 dark:text-emerald-400">Recording&hellip;</span>
                </motion.span>
              )}
            </AnimatePresence>
          </div>
        </div>

        <div
          className={`mt-3 flex flex-col gap-3 rounded-xl transition-shadow duration-300 ${
            flash ? "shadow-[0_0_0_3px_rgba(5,150,105,0.35)]" : "shadow-[0_0_0_3px_rgba(5,150,105,0)]"
          }`}
        >
          <label className="flex flex-col gap-1">
            <span className="text-xs font-medium text-slate-500 dark:text-slate-400">Headline</span>
            <input
              type="text"
              value={headline}
              onChange={(e) => setHeadline(e.target.value)}
              className="rounded-lg border border-slate-200/70 bg-white/60 px-3 py-2 text-sm text-slate-800 focus:outline-none focus-visible:border-emerald-500 dark:border-white/10 dark:bg-white/5 dark:text-slate-100"
            />
          </label>
          <label className="flex flex-col gap-1">
            <span className="text-xs font-medium text-slate-500 dark:text-slate-400">Bio</span>
            <textarea
              value={bio}
              onChange={(e) => setBio(e.target.value)}
              rows={2}
              className="resize-none rounded-lg border border-slate-200/70 bg-white/60 px-3 py-2 text-sm text-slate-800 focus:outline-none focus-visible:border-emerald-500 dark:border-white/10 dark:bg-white/5 dark:text-slate-100"
            />
          </label>
        </div>
      </div>
      <p className="text-center text-xs text-slate-400 dark:text-slate-500">
        Type in either field, pause, then jump between checkpoints. Nothing ever asks you to confirm losing anything.
      </p>
    </div>
  );
}

"use client";

import { useEffect, useRef, useState, type ReactNode } from "react";
import { motion, useReducedMotion } from "framer-motion";

export function MovingBorderButton({ children, onClick }: { children: ReactNode; onClick?: () => void }) {
  const ref = useRef<HTMLButtonElement>(null);
  const [size, setSize] = useState({ width: 160, height: 48 });
  const shouldReduceMotion = useReducedMotion();

  useEffect(() => {
    const el = ref.current;
    if (!el) return;
    const observer = new ResizeObserver(() => {
      const rect = el.getBoundingClientRect();
      setSize({ width: rect.width, height: rect.height });
    });
    observer.observe(el);
    return () => observer.disconnect();
  }, []);

  return (
    <button
      ref={ref}
      type="button"
      onClick={onClick}
      className="relative overflow-hidden rounded-lg bg-white px-6 py-3 text-sm font-medium text-slate-900 shadow-sm focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-emerald-500 dark:bg-slate-950 dark:text-white dark:shadow-none"
    >
      <svg
        className="pointer-events-none absolute inset-0 h-full w-full"
        viewBox={`0 0 ${size.width} ${size.height}`}
        aria-hidden
      >
        <defs>
          <linearGradient id="moving-border-gradient" x1="0" y1="0" x2="1" y2="1">
            <stop offset="0%" stopColor="#34d399" />
            <stop offset="100%" stopColor="#f59e0b" />
          </linearGradient>
        </defs>
        <rect
          x="1"
          y="1"
          width={Math.max(size.width - 2, 0)}
          height={Math.max(size.height - 2, 0)}
          rx="9"
          ry="9"
          fill="none"
          stroke="rgba(15,23,42,0.1)"
          strokeWidth="2"
          className="dark:hidden"
        />
        <rect
          x="1"
          y="1"
          width={Math.max(size.width - 2, 0)}
          height={Math.max(size.height - 2, 0)}
          rx="9"
          ry="9"
          fill="none"
          stroke="rgba(255,255,255,0.08)"
          strokeWidth="2"
          className="hidden dark:block"
        />
        <motion.rect
          x="1"
          y="1"
          width={Math.max(size.width - 2, 0)}
          height={Math.max(size.height - 2, 0)}
          rx="9"
          ry="9"
          fill="none"
          stroke="url(#moving-border-gradient)"
          strokeWidth="2"
          strokeLinecap="round"
          pathLength={100}
          strokeDasharray="18 82"
          animate={shouldReduceMotion ? undefined : { strokeDashoffset: [0, -100] }}
          transition={{ duration: 2.4, repeat: Infinity, ease: "linear" }}
        />
      </svg>
      <span className="relative z-10">{children}</span>
    </button>
  );
}

