"use client";

import { useEffect, useRef } from "react";
import { motion, useInView, useMotionValue, useReducedMotion, useSpring, useTransform } from "framer-motion";

function Counter({
  to,
  decimals = 1,
  prefix = "",
  suffix = "",
}: {
  to: number;
  decimals?: number;
  prefix?: string;
  suffix?: string;
}) {
  const ref = useRef(null);
  const isInView = useInView(ref, { once: true, margin: "-10% 0px" });
  const shouldReduceMotion = useReducedMotion();
  const motionValue = useMotionValue(shouldReduceMotion ? to : 0);
  const spring = useSpring(motionValue, { stiffness: 80, damping: 20 });
  const display = useTransform(spring, (v) => `${prefix}${v.toFixed(decimals)}${suffix}`);

  useEffect(() => {
    if (isInView && !shouldReduceMotion) motionValue.set(to);
  }, [isInView, to, motionValue, shouldReduceMotion]);

  return <motion.span ref={ref}>{display}</motion.span>;
}

export function StatCard({
  label,
  value,
  valueSuffix = "k",
  valueDecimals = 1,
  delta,
  deltaSuffix = "%",
  sparklinePoints,
}: {
  label: string;
  value: number;
  valueSuffix?: string;
  valueDecimals?: number;
  delta?: number;
  deltaSuffix?: string;
  sparklinePoints?: string;
}) {
  const shouldReduceMotion = useReducedMotion();
  const deltaUp = delta !== undefined && delta >= 0;

  return (
    <motion.div
      whileHover={shouldReduceMotion ? undefined : { y: -3 }}
      transition={{ type: "spring", stiffness: 400, damping: 28 }}
      className="flex flex-col gap-3 rounded-2xl border border-slate-200 bg-white p-6 transition-shadow duration-300 hover:shadow-lg dark:border-slate-700 dark:bg-neutral-950"
    >
      <span className="text-sm text-slate-500 dark:text-slate-400">{label}</span>
      <div className="flex items-baseline gap-2">
        <span className="text-3xl font-semibold text-slate-900 dark:text-white">
          <Counter to={value} decimals={valueDecimals} suffix={valueSuffix} />
        </span>
        {delta !== undefined && (
          <span
            className={
              deltaUp
                ? "text-sm font-medium text-emerald-700 dark:text-emerald-400"
                : "text-sm font-medium text-rose-600 dark:text-rose-400"
            }
          >
            <Counter to={Math.abs(delta)} decimals={valueDecimals} prefix={deltaUp ? "+" : "-"} suffix={deltaSuffix} />
          </span>
        )}
      </div>
      {sparklinePoints && (
        <svg viewBox="0 0 100 24" className="h-6 w-full text-emerald-500" fill="none" preserveAspectRatio="none">
          <motion.polyline
            points={sparklinePoints}
            stroke="currentColor"
            strokeWidth="2"
            strokeLinecap="round"
            strokeLinejoin="round"
            initial={shouldReduceMotion ? { pathLength: 1, opacity: 1 } : { pathLength: 0, opacity: 0 }}
            whileInView={{ pathLength: 1, opacity: 1 }}
            viewport={{ once: true, margin: "-10% 0px" }}
            transition={
              shouldReduceMotion ? { duration: 0 } : { duration: 1, ease: [0.22, 1, 0.36, 1], delay: 0.2 }
            }
          />
        </svg>
      )}
    </motion.div>
  );
}

type BadgeTone = "neutral" | "success" | "warning" | "live";

const tones: Record<BadgeTone, string> = {
  neutral: "bg-slate-100 text-slate-700 dark:bg-neutral-900 dark:text-slate-300",
  success: "bg-emerald-100 text-emerald-700 dark:bg-emerald-500/15 dark:text-emerald-400",
  warning: "bg-amber-100 text-amber-700 dark:bg-amber-500/15 dark:text-amber-400",
  live: "bg-amber-100 text-amber-700 dark:bg-amber-500/15 dark:text-amber-400",
};

export function Badge({ tone = "neutral", children }: { tone?: BadgeTone; children: React.ReactNode }) {
  return (
    <span
      className={`inline-flex items-center gap-1.5 rounded-full px-2.5 py-1 text-xs font-medium transition-transform duration-200 ease-out hover:scale-105 ${tones[tone]}`}
    >
      {tone === "live" && (
        <span className="relative flex h-1.5 w-1.5">
          <span className="absolute inline-flex h-full w-full animate-ping rounded-full bg-amber-500 opacity-75 motion-reduce:hidden" />
          <span className="relative inline-flex h-1.5 w-1.5 rounded-full bg-amber-500" />
        </span>
      )}
      {children}
    </span>
  );
}

"use client";

import { useEffect, useRef } from "react";
import { motion, useInView, useMotionValue, useReducedMotion, useSpring, useTransform } from "framer-motion";
import { CheckIcon as PhCheck } from "@phosphor-icons/react";

function Price({ to }: { to: number }) {
  const ref = useRef(null);
  const isInView = useInView(ref, { once: true, margin: "-10% 0px" });
  const shouldReduceMotion = useReducedMotion();
  const motionValue = useMotionValue(shouldReduceMotion ? to : 0);
  const spring = useSpring(motionValue, { stiffness: 90, damping: 20 });
  const display = useTransform(spring, (v) => Math.round(v));

  useEffect(() => {
    if (isInView && !shouldReduceMotion) motionValue.set(to);
  }, [isInView, to, motionValue, shouldReduceMotion]);

  return <motion.span ref={ref}>{display}</motion.span>;
}

export function PricingCard({
  name,
  price,
  features,
  popular = false,
}: {
  name: string;
  price: number;
  features: string[];
  popular?: boolean;
}) {
  const shouldReduceMotion = useReducedMotion();

  return (
    <motion.div
      whileHover={shouldReduceMotion ? undefined : { y: -4 }}
      transition={{ type: "spring", stiffness: 380, damping: 28 }}
      className={`group relative w-full max-w-[280px] overflow-hidden rounded-2xl border p-6 dark:bg-neutral-950 ${
        popular
          ? "border-emerald-400/60 bg-white shadow-[0_20px_40px_-24px_rgba(5,150,105,0.4)] dark:border-emerald-400/40"
          : "border-slate-200 bg-white dark:border-slate-700"
      }`}
    >
      {popular && (
        <span
          aria-hidden
          className="pointer-events-none absolute inset-0 -translate-x-full bg-gradient-to-r from-transparent via-emerald-400/10 to-transparent transition-transform duration-[1400ms] ease-out group-hover:translate-x-full motion-reduce:hidden"
        />
      )}
      {popular && (
        <span className="inline-flex items-center rounded-full bg-emerald-700 px-2.5 py-0.5 text-[11px] font-semibold text-white">
          Most popular
        </span>
      )}
      <h3 className={`text-base font-semibold text-slate-900 dark:text-white ${popular ? "mt-4" : ""}`}>{name}</h3>
      <div className="mt-1 flex items-baseline gap-1">
        <span className="text-4xl font-semibold tabular-nums text-slate-900 dark:text-white">
          $<Price to={price} />
        </span>
        <span className="text-sm text-slate-400 dark:text-slate-500">/ month</span>
      </div>

      <ul className="mt-5 flex flex-col gap-2.5">
        {features.map((feature, i) => (
          <motion.li
            key={feature}
            initial={shouldReduceMotion ? { opacity: 1 } : { opacity: 0, x: -6 }}
            whileInView={{ opacity: 1, x: 0 }}
            viewport={{ once: true, margin: "-10% 0px" }}
            transition={{ delay: shouldReduceMotion ? 0 : 0.15 + i * 0.07, duration: 0.3, ease: [0.22, 1, 0.36, 1] }}
