      <motion.button
        whileHover={shouldReduceMotion ? undefined : { y: -2 }}
        whileTap={{ scale: 0.96, y: 0 }}
        transition={{ type: "spring", stiffness: 500, damping: 30 }}
        className={`mt-6 w-full rounded-lg px-4 py-2.5 text-sm font-medium transition-[box-shadow,background-color] duration-300 focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 ${
          popular
            ? "bg-emerald-700 text-white shadow-[0_1px_2px_rgba(5,150,105,0.3)] hover:bg-emerald-600 hover:shadow-[0_12px_24px_-8px_rgba(5,150,105,0.65)] focus-visible:outline-emerald-700"
            : "border border-slate-300 text-slate-700 hover:border-slate-400 focus-visible:outline-slate-400 dark:border-slate-600 dark:text-slate-200"
        }`}
      >
        Choose {name}
      </motion.button>
    </motion.div>
  );
}

"use client";

import { useState } from "react";
import { AnimatePresence, motion, useReducedMotion } from "framer-motion";

export interface AvatarPerson {
  initials: string;
  color: string;
  name: string;
  role: string;
  avatarUrl?: string;
  status?: "online" | "away" | "offline";
}

const SIZE = {
  sm: { box: "h-8 w-8", text: "text-[10px]", dot: "h-2 w-2" },
  md: { box: "h-12 w-12", text: "text-sm", dot: "h-2.5 w-2.5" },
  lg: { box: "h-16 w-16", text: "text-base", dot: "h-3.5 w-3.5" },
} as const;

const STATUS_COLOR = {
  online: "bg-emerald-500",
  away: "bg-amber-500",
  offline: "bg-slate-400 dark:bg-slate-600",
} as const;

export function Avatar({
  person,
  size = "md",
  showTooltip = true,
}: {
  person: AvatarPerson;
  size?: "sm" | "md" | "lg";
  showTooltip?: boolean;
}) {
  const shouldReduceMotion = useReducedMotion();
  const [hovered, setHovered] = useState(false);
  const dims = SIZE[size];

  return (
    <div className="relative inline-flex">
      <motion.div
        onMouseEnter={() => setHovered(true)}
        onMouseLeave={() => setHovered(false)}
        onFocus={() => setHovered(true)}
        onBlur={() => setHovered(false)}
        tabIndex={0}
        whileHover={shouldReduceMotion ? undefined : { scale: 1.06 }}
        transition={{ type: "spring", stiffness: 400, damping: 22 }}
        className={`flex ${dims.box} items-center justify-center overflow-hidden rounded-full border-2 border-white font-semibold text-white shadow-sm outline-none focus-visible:ring-2 focus-visible:ring-emerald-600 focus-visible:ring-offset-2 dark:border-slate-900 ${dims.text} ${person.color}`}
      >
        {person.avatarUrl ? (
          <img src={person.avatarUrl} alt={person.name} className="h-full w-full object-cover" />
        ) : (
          person.initials
        )}
      </motion.div>
      {person.status && (
        <span
          aria-hidden
          className={`absolute bottom-0 right-0 flex ${dims.dot} items-center justify-center rounded-full border-2 border-white dark:border-slate-900`}
        >
          {person.status === "online" && !shouldReduceMotion && (
            <motion.span
              className="absolute inset-0 rounded-full bg-emerald-500"
              animate={{ scale: [1, 1.9], opacity: [0.7, 0] }}
              transition={{ duration: 1.6, repeat: Infinity, ease: "easeOut" }}
            />
          )}
          <span className={`relative h-full w-full rounded-full ${STATUS_COLOR[person.status]}`} />
        </span>
      )}
      <div className="pointer-events-none absolute -top-2 left-1/2 z-20 -translate-x-1/2 -translate-y-full">
        <AnimatePresence>
          {showTooltip && hovered && (
            <motion.div
              role="tooltip"
              initial={shouldReduceMotion ? { opacity: 0 } : { opacity: 0, y: 6, scale: 0.85 }}
              animate={{ opacity: 1, y: 0, scale: 1 }}
              exit={shouldReduceMotion ? { opacity: 0 } : { opacity: 0, y: 6, scale: 0.85 }}
              transition={{ type: "spring", stiffness: 500, damping: 28 }}
              style={{ transformOrigin: "bottom center" }}
            >
              <div className="whitespace-nowrap rounded-lg bg-slate-900 px-3 py-1.5 text-center shadow-lg dark:bg-slate-100">
                <p className="text-xs font-semibold text-white dark:text-slate-900">{person.name}</p>
                <p className="text-[11px] text-slate-300 dark:text-slate-500">{person.role}</p>
              </div>
              <span
                aria-hidden
                className="absolute left-1/2 top-full h-2 w-2 -translate-x-1/2 -translate-y-1/2 rotate-45 bg-slate-900 dark:bg-slate-100"
              />
            </motion.div>
          )}
        </AnimatePresence>
      </div>
    </div>
  );
}

"use client";

import { useState } from "react";
import { AnimatePresence, motion, useReducedMotion } from "framer-motion";

export interface Avatar {
  initials: string;
  color: string;
  name: string;
  role: string;
  avatarUrl?: string;
}

export function AvatarGroup({
  people,
  maxVisible = 4,
}: {
  people: Avatar[];
  maxVisible?: number;
}) {
  const shouldReduceMotion = useReducedMotion();
  const [hovered, setHovered] = useState<number | "overflow" | null>(null);
  const visiblePeople = people.slice(0, maxVisible);
  const hiddenPeople = people.slice(maxVisible);

  return (
    <div className="group flex items-center">
      {visiblePeople.map((person, i) => (
        <motion.div
          key={person.initials}
          whileHover={shouldReduceMotion ? undefined : { y: -4, zIndex: 10 }}
          className="relative"
          style={{ marginLeft: i === 0 ? 0 : -10, zIndex: visiblePeople.length - i }}
        >
          <motion.div
            onMouseEnter={() => setHovered(i)}
            onMouseLeave={() => setHovered(null)}
            onFocus={() => setHovered(i)}
            onBlur={() => setHovered(null)}
            tabIndex={0}
            whileHover={
              shouldReduceMotion ? undefined : { scale: 1.08, x: (i - (visiblePeople.length - 1) / 2) * 6 }
            }
            transition={{ type: "spring", stiffness: 400, damping: 22 }}
            className={`flex h-10 w-10 items-center justify-center overflow-hidden rounded-full border-2 border-white text-xs font-semibold text-white shadow-sm outline-none focus-visible:ring-2 focus-visible:ring-emerald-600 focus-visible:ring-offset-2 dark:border-slate-900 ${person.color}`}
          >
            {person.avatarUrl ? (
              <img src={person.avatarUrl} alt={person.name} className="h-full w-full object-cover" />
            ) : (
              person.initials
            )}
          </motion.div>
          <div className="pointer-events-none absolute -top-2 left-1/2 z-20 -translate-x-1/2 -translate-y-full">
            <AnimatePresence>
              {hovered === i && (
                <motion.div
                  role="tooltip"
                  initial={shouldReduceMotion ? { opacity: 0 } : { opacity: 0, y: 6, scale: 0.85 }}
                  animate={{ opacity: 1, y: 0, scale: 1 }}
                  exit={shouldReduceMotion ? { opacity: 0 } : { opacity: 0, y: 6, scale: 0.85 }}
                  transition={{ type: "spring", stiffness: 500, damping: 28 }}
                  style={{ transformOrigin: "bottom center" }}
                >
                  <div className="whitespace-nowrap rounded-lg bg-slate-900 px-3 py-1.5 text-center shadow-lg dark:bg-slate-100">
                    <p className="text-xs font-semibold text-white dark:text-slate-900">{person.name}</p>
                    <p className="text-[11px] text-slate-300 dark:text-slate-500">{person.role}</p>
                  </div>
                  <span
                    aria-hidden
                    className="absolute left-1/2 top-full h-2 w-2 -translate-x-1/2 -translate-y-1/2 rotate-45 bg-slate-900 dark:bg-slate-100"
                  />
                </motion.div>
              )}
            </AnimatePresence>
          </div>
        </motion.div>
      ))}
      {hiddenPeople.length > 0 && (
        <motion.div
          onMouseEnter={() => setHovered("overflow")}
          onMouseLeave={() => setHovered(null)}
          onFocus={() => setHovered("overflow")}
          onBlur={() => setHovered(null)}
          tabIndex={0}
          whileHover={shouldReduceMotion ? undefined : { scale: 1.08 }}
          transition={{ type: "spring", stiffness: 400, damping: 22 }}
          style={{ marginLeft: -10 }}
          className="relative flex h-10 w-10 items-center justify-center rounded-full border-2 border-white bg-slate-100 text-xs font-semibold text-slate-600 shadow-sm outline-none focus-visible:ring-2 focus-visible:ring-emerald-600 focus-visible:ring-offset-2 dark:border-slate-900 dark:bg-neutral-900 dark:text-slate-300"
        >
          +{hiddenPeople.length}
          <div className="pointer-events-none absolute -top-2 left-1/2 z-20 -translate-x-1/2 -translate-y-full">
            <AnimatePresence>
              {hovered === "overflow" && (
                <motion.div
                  role="tooltip"
                  initial={shouldReduceMotion ? { opacity: 0 } : { opacity: 0, y: 6, scale: 0.85 }}
                  animate={{ opacity: 1, y: 0, scale: 1 }}
                  exit={shouldReduceMotion ? { opacity: 0 } : { opacity: 0, y: 6, scale: 0.85 }}
                  transition={{ type: "spring", stiffness: 500, damping: 28 }}
                  style={{ transformOrigin: "bottom center" }}
                >
                  <div className="space-y-1.5 rounded-lg bg-slate-900 px-3 py-2 text-left shadow-lg dark:bg-slate-100">
                    {hiddenPeople.map((person) => (
                      <div key={person.initials} className="flex items-center gap-2">
                        <span
                          className={`flex h-5 w-5 shrink-0 items-center justify-center overflow-hidden rounded-full text-[9px] font-semibold text-white ${person.color}`}
                        >
                          {person.avatarUrl ? (
                            <img src={person.avatarUrl} alt={person.name} className="h-full w-full object-cover" />
                          ) : (
                            person.initials
                          )}
                        </span>
                        <span className="whitespace-nowrap text-xs font-medium text-white dark:text-slate-900">
                          {person.name}
                        </span>
                      </div>
                    ))}
                  </div>
                  <span
                    aria-hidden
                    className="absolute left-1/2 top-full h-2 w-2 -translate-x-1/2 -translate-y-1/2 rotate-45 bg-slate-900 dark:bg-slate-100"
                  />
                </motion.div>
              )}
            </AnimatePresence>
          </div>
        </motion.div>
      )}
    </div>
  );
}

"use client";

import { motion, useReducedMotion } from "framer-motion";

const GRID_Y = [8, 26, 44, 62, 80, 98, 116, 134, 152, 170, 188, 206];

const GLOW_SPOTS = [
  { left: "16%", top: "10%", size: 130, duration: 16, drift: 14, className: "bg-amber-200/35" },
  { left: "66%", top: "48%", size: 100, duration: 20, drift: 10, className: "bg-emerald-100/25" },
  { left: "36%", top: "78%", size: 90, duration: 18, drift: 12, className: "bg-amber-100/20" },
];

function GlowSpot({
  left,
  top,
  size,
  duration,
  drift,
  className,
  shouldReduceMotion,
}: {
  left: string;
  top: string;
  size: number;
  duration: number;
  drift: number;
  className: string;
  shouldReduceMotion: boolean;
}) {
  return (
    <motion.div
      aria-hidden
      className={`absolute rounded-full blur-2xl ${className}`}
      style={{ left, top, width: size, height: size }}
      animate={
        shouldReduceMotion
          ? undefined
          : { x: [0, drift, -drift * 0.6, 0], y: [0, -drift * 0.7, drift * 0.4, 0] }
      }
      transition={{ duration, repeat: Infinity, ease: "easeInOut" }}
    />
  );
}

