const EASE = [0.22, 1, 0.36, 1] as const;

const TEXT_W = 256;
const TEXT_H = 208;
const IMAGE_W = 176;
const IMAGE_H_TOP = 140;

interface Credit {
  name: string;
  href: string;
}

export interface RevealCardItem {
  id: string;
  eyebrow: string;
