export type RevealCardVariant = "right" | "left" | "top";

function ArrowIcon() {
  return <PhArrowUpRight size={12} weight="bold" aria-hidden />;
}

function RevealImage({
  item,
  variant,
  hovered,
  shouldReduceMotion,
}: {
  item: RevealCardItem;
  variant: RevealCardVariant;
  hovered: boolean;
  shouldReduceMotion: boolean | null;
}) {
  const sizeAnimate = variant === "top" ? { height: hovered ? IMAGE_H_TOP : 0 } : { width: hovered ? IMAGE_W : 0 };

  return (
    <motion.div
      aria-hidden
      className={`relative shrink-0 overflow-hidden ${variant === "top" ? "w-full" : "h-full"}`}
      animate={sizeAnimate}
      transition={{
        duration: shouldReduceMotion ? 0 : 0.5,
        delay: hovered && !shouldReduceMotion ? 0.06 : 0,
        ease: EASE,
      }}
    >
      <motion.img
        src={item.image.src}
        alt=""
        className="absolute inset-0 h-full w-full object-cover"
        animate={{ scale: hovered ? 1 : 1.1 }}
        transition={{ duration: shouldReduceMotion ? 0 : 0.7, ease: EASE }}
      />
    </motion.div>
  );
}

export function RevealCard({
  item,
  variant = "right",
  shouldReduceMotion,
}: {
  item: RevealCardItem;
  variant?: RevealCardVariant;
  shouldReduceMotion: boolean | null;
}) {
  const [hovered, setHovered] = useState(false);
  const imageFirst = variant === "left" || variant === "top";
  const isTop = variant === "top";

  const widthAnimate = isTop ? { width: TEXT_W } : { width: hovered ? TEXT_W + IMAGE_W : TEXT_W };
  const heightAnimate = isTop ? { height: hovered ? TEXT_H + IMAGE_H_TOP : TEXT_H } : { height: TEXT_H };

  return (
    <motion.button
      type="button"
      onMouseEnter={() => setHovered(true)}
      onMouseLeave={() => setHovered(false)}
      onFocus={() => setHovered(true)}
      onBlur={() => setHovered(false)}
      aria-label={`${item.title}, ${item.ctaLabel}`}
      animate={{ ...widthAnimate, ...heightAnimate }}
      transition={{ duration: shouldReduceMotion ? 0 : 0.5, ease: EASE }}
      className={`group relative flex items-stretch overflow-hidden rounded-2xl border border-slate-200/70 bg-white text-left transition-colors hover:border-slate-300 focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-emerald-600 dark:border-white/10 dark:bg-neutral-950 dark:hover:border-white/20 ${
        isTop ? "flex-col" : "flex-row"
      }`}
    >
      {imageFirst && <RevealImage item={item} variant={variant} hovered={hovered} shouldReduceMotion={shouldReduceMotion} />}

      <motion.div
        className="relative shrink-0"
        style={{ width: TEXT_W, height: TEXT_H }}
        animate={{ x: hovered ? -4 : 0 }}
        transition={{ duration: shouldReduceMotion ? 0 : 0.5, ease: EASE }}
      >
        <div className="flex h-full flex-col px-6 py-6">
          <span className="text-[11px] font-medium uppercase tracking-wide text-slate-400 dark:text-slate-500">
            {item.eyebrow}
          </span>
          <h3 className="mt-1 truncate text-xl font-semibold text-slate-900 dark:text-white">{item.title}</h3>
          <p className="mt-2 text-sm leading-relaxed text-slate-500 dark:text-slate-400">{item.description}</p>
        </div>

        <motion.span
          aria-hidden
          className="absolute bottom-6 left-6 inline-flex items-center gap-1.5 rounded-lg bg-slate-900 px-3 py-1.5 text-xs font-medium text-white dark:bg-white dark:text-slate-900"
          initial={false}
          animate={hovered ? { opacity: 1, y: 0 } : { opacity: 0, y: 10 }}
          transition={{
            duration: shouldReduceMotion ? 0 : 0.35,
            delay: hovered && !shouldReduceMotion ? 0.18 : 0,
            ease: EASE,
          }}
        >
          {item.ctaLabel}
          <ArrowIcon />
        </motion.span>
      </motion.div>

      {!imageFirst && <RevealImage item={item} variant={variant} hovered={hovered} shouldReduceMotion={shouldReduceMotion} />}
    </motion.button>
  );
}

