            <p className="mt-3 text-lg leading-relaxed text-slate-700 dark:text-slate-200">{review.quote}</p>
            <div className="mt-4 flex flex-col items-center">
              {review.avatarUrl && (
                <img
                  src={review.avatarUrl}
                  alt={review.name}
                  className="mb-2 h-9 w-9 rounded-full border border-slate-200 object-cover dark:border-white/10"
                />
              )}
              <p className="text-sm font-medium text-slate-900 dark:text-white">{review.name}</p>
              <p className="text-xs text-slate-500 dark:text-slate-400">{review.role}</p>
            </div>
          </motion.div>
        </AnimatePresence>
      </div>
      <div className="mt-6 flex items-center justify-center gap-4">
        <button
          type="button"
          onClick={() => go(index - 1)}
          aria-label="Previous testimonial"
          className="flex h-9 w-9 items-center justify-center rounded-full border border-slate-200 bg-white text-slate-500 transition-colors hover:text-slate-900 dark:border-white/10 dark:bg-neutral-900 dark:text-slate-400 dark:hover:text-white"
