              aria-label={`Go to testimonial ${i + 1}`}
              className={
                i === index
                  ? "h-1.5 w-5 rounded-full bg-emerald-600 transition-all"
                  : "h-1.5 w-1.5 rounded-full bg-slate-300 transition-all dark:bg-white/20"
              }
            />
