"use client";

import { useEffect, useMemo, useRef, useState } from "react";
import { AnimatePresence, motion, useReducedMotion } from "framer-motion";
import { MagnifyingGlassIcon as PhMagnifyingGlass } from "@phosphor-icons/react";

export interface CommandItem {
  id: string;
  label: string;
  group: string;
  keywords?: string;
}

export function CommandPalette({
  open,
  onOpenChange,
  items,
  onSelect,
  placeholder = "Search...",
}: {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  items: CommandItem[];
  onSelect: (item: CommandItem) => void;
  placeholder?: string;
}) {
  const [query, setQuery] = useState("");
  const [highlighted, setHighlighted] = useState(0);
  const inputRef = useRef<HTMLInputElement>(null);
  const shouldReduceMotion = useReducedMotion();

  const filtered = useMemo(() => {
    const q = query.trim().toLowerCase();
    if (!q) return items;
    return items.filter(
      (item) =>
        item.label.toLowerCase().includes(q) ||
        item.group.toLowerCase().includes(q) ||
        item.keywords?.toLowerCase().includes(q)
    );
  }, [items, query]);

  const groups = useMemo(() => {
    const map = new Map<string, CommandItem[]>();
    filtered.forEach((item) => {
      if (!map.has(item.group)) map.set(item.group, []);
      map.get(item.group)?.push(item);
    });
    return Array.from(map.entries());
  }, [filtered]);

  const [prevOpen, setPrevOpen] = useState(open);
  if (open !== prevOpen) {
    setPrevOpen(open);
    if (open) {
      setQuery("");
      setHighlighted(0);
    }
  }

  useEffect(() => {
    if (open) requestAnimationFrame(() => inputRef.current?.focus());
  }, [open]);

  const handleQueryChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    setQuery(e.target.value);
    setHighlighted(0);
  };

  // also listen globally for cmd/ctrl+K to toggle open from anywhere on the page
  useEffect(() => {
    const handler = (e: KeyboardEvent) => {
      if ((e.metaKey || e.ctrlKey) && e.key.toLowerCase() === "k") {
        e.preventDefault();
        onOpenChange(!open);
      }
    };
    window.addEventListener("keydown", handler);
    return () => window.removeEventListener("keydown", handler);
  }, [open, onOpenChange]);

  const handleKeyDown = (e: React.KeyboardEvent<HTMLInputElement>) => {
    if (e.key === "ArrowDown") {
      e.preventDefault();
      setHighlighted((h) => Math.min(h + 1, filtered.length - 1));
    } else if (e.key === "ArrowUp") {
      e.preventDefault();
      setHighlighted((h) => Math.max(h - 1, 0));
    } else if (e.key === "Enter") {
      e.preventDefault();
      const item = filtered[highlighted];
      if (item) {
        onSelect(item);
        onOpenChange(false);
      }
    } else if (e.key === "Escape") {
      e.preventDefault();
      onOpenChange(false);
    }
  };

  const activeItem = filtered[highlighted];

  return (
    <AnimatePresence>
      {open && (
        <>
          <motion.div
            key="backdrop"
            aria-hidden
            className="fixed inset-0 z-50 bg-slate-950/40 backdrop-blur-sm"
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            exit={{ opacity: 0 }}
            transition={{ duration: shouldReduceMotion ? 0.1 : 0.2 }}
            onClick={() => onOpenChange(false)}
          />
          <motion.div
            key="dialog"
            role="dialog"
            aria-modal="true"
            aria-label="Command palette"
            className="fixed left-1/2 top-24 z-50 w-[calc(100%-2rem)] max-w-lg"
            initial={shouldReduceMotion ? { opacity: 0, x: "-50%" } : { opacity: 0, scale: 0.96, y: -8, x: "-50%" }}
            animate={{ opacity: 1, scale: 1, y: 0, x: "-50%" }}
            exit={shouldReduceMotion ? { opacity: 0, x: "-50%" } : { opacity: 0, scale: 0.98, y: -6, x: "-50%" }}
            transition={{ duration: 0.2, ease: [0.16, 1, 0.3, 1] }}
          >
            <div className="overflow-hidden rounded-2xl border border-slate-200 bg-white shadow-2xl dark:border-slate-700 dark:bg-neutral-950">
              <div className="flex items-center gap-2.5 border-b border-slate-200 px-4 dark:border-slate-700">
                <PhMagnifyingGlass size={16} aria-hidden className="shrink-0 text-slate-400 dark:text-slate-500" />
                <input
                  ref={inputRef}
                  role="combobox"
                  aria-expanded="true"
                  aria-controls="cmdk-listbox"
                  aria-activedescendant={activeItem ? `cmdk-option-${activeItem.id}` : undefined}
                  aria-autocomplete="list"
                  value={query}
                  onChange={handleQueryChange}
                  onKeyDown={handleKeyDown}
                  placeholder={placeholder}
                  className="w-full bg-transparent py-3.5 text-sm text-slate-900 outline-none placeholder:text-slate-400 dark:text-white"
                />
                <kbd className="hidden shrink-0 rounded border border-slate-200 px-1.5 py-0.5 text-[10px] font-medium text-slate-400 sm:inline-block dark:border-slate-700 dark:text-slate-500">
                  esc
                </kbd>
              </div>

              <div id="cmdk-listbox" role="listbox" className="max-h-80 overflow-y-auto p-2">
                {groups.length === 0 && (
                  <p className="px-3 py-6 text-center text-sm text-slate-400 dark:text-slate-500">
                    No results for "{query}"
                  </p>
                )}
                {groups.map(([group, groupItems]) => (
                  <div key={group} className="mb-1 last:mb-0">
                    <p className="px-3 pb-1 pt-2 text-[10px] font-semibold uppercase tracking-wide text-slate-400 dark:text-slate-500">
                      {group}
                    </p>
                    {groupItems.map((item) => {
                      const index = filtered.indexOf(item);
                      const isHighlighted = index === highlighted;
                      return (
                        <div
                          key={item.id}
                          id={`cmdk-option-${item.id}`}
                          role="option"
                          aria-selected={isHighlighted}
                          onMouseEnter={() => setHighlighted(index)}
                          onClick={() => {
                            onSelect(item);
                            onOpenChange(false);
                          }}
                          className="relative cursor-pointer rounded-lg px-3 py-2 text-sm"
                        >
                          {isHighlighted && (
                            <motion.span
                              layoutId="cmdk-highlight"
                              className="absolute inset-0 rounded-lg bg-emerald-50 dark:bg-emerald-500/10"
                              transition={shouldReduceMotion ? { duration: 0 } : { type: "spring", stiffness: 600, damping: 40 }}
                            />
                          )}
                          <span className={`relative ${isHighlighted ? "text-emerald-700 dark:text-emerald-400" : "text-slate-700 dark:text-slate-300"}`}>
                            {item.label}
                          </span>
                        </div>
                      );
                    })}
                  </div>
                ))}
              </div>

              <div className="flex items-center gap-3 border-t border-slate-200 px-4 py-2 dark:border-slate-700">
                <span className="inline-flex items-center gap-1 text-[11px] text-slate-400 dark:text-slate-500">
                  <kbd className="rounded border border-slate-200 px-1 py-px dark:border-slate-700">↑↓</kbd>
                  navigate
                </span>
                <span className="inline-flex items-center gap-1 text-[11px] text-slate-400 dark:text-slate-500">
                  <kbd className="rounded border border-slate-200 px-1 py-px dark:border-slate-700">↵</kbd>
                  select
                </span>
                <span className="inline-flex items-center gap-1 text-[11px] text-slate-400 dark:text-slate-500">
                  <kbd className="rounded border border-slate-200 px-1 py-px dark:border-slate-700">esc</kbd>
                  close
                </span>
              </div>
            </div>
          </motion.div>
        </>
      )}
    </AnimatePresence>
  );
}

"use client";

import { useState } from "react";
import { motion, useReducedMotion } from "framer-motion";
import { CaretLeftIcon as PhCaretLeft } from "@phosphor-icons/react";

function ChevronIcon({ flip }: { flip?: boolean }) {
  return <PhCaretLeft size={16} weight="bold" aria-hidden className={flip ? "rotate-180" : ""} />;
}

export function Pagination({ totalPages }: { totalPages: number }) {
  const [page, setPage] = useState(1);
  const shouldReduceMotion = useReducedMotion();

  return (
    <nav aria-label="Pagination" className="flex items-center gap-1">
      <button
        type="button"
        aria-label="Previous page"
        disabled={page === 1}
        onClick={() => setPage((p) => Math.max(1, p - 1))}
        className="inline-flex h-8 w-8 items-center justify-center rounded-lg text-slate-500 transition-colors hover:bg-slate-100 disabled:opacity-30 disabled:hover:bg-transparent focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-emerald-600 dark:text-slate-400 dark:hover:bg-slate-800"
      >
        <ChevronIcon flip />
      </button>
      {Array.from({ length: totalPages }, (_, i) => i + 1).map((n) => (
        <button
          key={n}
          type="button"
          aria-label={`Page ${n}`}
          aria-current={page === n ? "page" : undefined}
          onClick={() => setPage(n)}
          className={`relative inline-flex h-8 w-8 items-center justify-center rounded-lg text-sm font-medium transition-colors focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-emerald-600 ${
            page === n ? "text-white" : "text-slate-600 hover:bg-slate-100 dark:text-slate-300 dark:hover:bg-slate-800"
          }`}
        >
          {page === n && (
            <motion.span
              layoutId="pagination-active"
              className="absolute inset-0 rounded-lg bg-emerald-700"
              transition={shouldReduceMotion ? { duration: 0 } : { type: "spring", stiffness: 500, damping: 35 }}
            />
          )}
          <span className="relative">{n}</span>
        </button>
      ))}
      <button
        type="button"
        aria-label="Next page"
        disabled={page === totalPages}
        onClick={() => setPage((p) => Math.min(totalPages, p + 1))}
        className="inline-flex h-8 w-8 items-center justify-center rounded-lg text-slate-500 transition-colors hover:bg-slate-100 disabled:opacity-30 disabled:hover:bg-transparent focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-emerald-600 dark:text-slate-400 dark:hover:bg-slate-800"
      >
        <ChevronIcon />
      </button>
    </nav>
  );
}

"use client";

import { useState } from "react";
import { motion, useReducedMotion } from "framer-motion";

export function Stepper({ steps, initial = 0 }: { steps: string[]; initial?: number }) {
  const [current, setCurrent] = useState(initial);
  const shouldReduceMotion = useReducedMotion();

  return (
    <div className="w-full max-w-md">
      <ol className="flex items-center">
        {steps.map((step, i) => {
          const isComplete = i < current;
          const isActive = i === current;
          return (
            <li key={step} className="flex flex-1 items-center last:flex-none">
              <button
                type="button"
                onClick={() => setCurrent(i)}
                aria-current={isActive ? "step" : undefined}
                className="flex flex-col items-center gap-2 focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-4 focus-visible:outline-emerald-600 rounded-full"
              >
                <motion.span
                  animate={isActive && !shouldReduceMotion ? { scale: [1, 1.15, 1] } : { scale: 1 }}
                  transition={{ duration: 0.5, ease: [0.16, 1, 0.3, 1] }}
                  className={`relative flex h-8 w-8 shrink-0 items-center justify-center rounded-full border-2 text-xs font-semibold transition-colors duration-300 ${
                    isComplete
                      ? "border-emerald-700 bg-emerald-700 text-white"
                      : isActive
                        ? "border-emerald-700 text-emerald-700 dark:text-emerald-400"
                        : "border-slate-300 text-slate-400 dark:border-slate-600 dark:text-slate-500"
                  }`}
                >
                  {isComplete ? (
                    <svg viewBox="0 0 16 16" width="14" height="14" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round" aria-hidden>
                      <motion.path
                        d="M3 8.5l3 3 7-7.5"
                        initial={{ pathLength: 0 }}
                        animate={{ pathLength: 1 }}
                        transition={shouldReduceMotion ? { duration: 0 } : { duration: 0.3, ease: [0.22, 1, 0.36, 1] }}
                      />
                    </svg>
                  ) : (
                    i + 1
                  )}
                </motion.span>
                <span
                  className={`text-xs font-medium ${
                    isActive ? "text-slate-900 dark:text-white" : "text-slate-400 dark:text-slate-500"
                  }`}
                >
                  {step}
                </span>
              </button>
              {i < steps.length - 1 && (
                <div className="mx-2 mb-5 h-0.5 flex-1 overflow-hidden rounded-full bg-slate-200 dark:bg-slate-700">
                  <motion.div
                    className="h-full bg-emerald-700"
                    initial={false}
                    animate={{ scaleX: isComplete ? 1 : 0 }}
                    style={{ transformOrigin: "left" }}
                    transition={shouldReduceMotion ? { duration: 0 } : { duration: 0.4, ease: [0.22, 1, 0.36, 1] }}
                  />
                </div>
              )}
            </li>
          );
        })}
      </ol>
    </div>
  );
}

