import { useRef } from "react";
import { motion, useInView, useReducedMotion } from "framer-motion";

export function RevealOnScroll({ children }: { children: React.ReactNode }) {
  const ref = useRef<HTMLDivElement>(null);
  const isInView = useInView(ref, { margin: "-10% 0px" });
  const shouldReduceMotion = useReducedMotion();
  const show = shouldReduceMotion || isInView;

  return (
    <motion.div
      ref={ref}
      initial={false}
      animate={
        show
          ? { opacity: 1, y: 0, filter: "blur(0px)" }
          : { opacity: 0, y: 24, filter: "blur(6px)" }
      }
      transition={{ duration: 0.7, ease: [0.22, 1, 0.36, 1] }}
      className="rounded-xl border border-slate-200 bg-white px-6 py-4 text-sm text-slate-600 dark:border-slate-700 dark:bg-neutral-950 dark:text-slate-300"
    >
      {children}
    </motion.div>
  );
}

"use client";

import { useRef, useState } from "react";
import { motion, useMotionValue, useMotionTemplate, useSpring, useTransform, useReducedMotion } from "framer-motion";
import { cn } from "@/lib/utils";

export interface LogoWallItem {
  name: string;
  image?: { src: string; credit?: { name: string; href: string } };
}

function PhotoCell({ cell }: { cell: LogoWallItem & { image: NonNullable<LogoWallItem["image"]> } }) {
  const shouldReduceMotion = useReducedMotion();
  const ref = useRef<HTMLDivElement>(null);
  const [hovered, setHovered] = useState(false);
  const mouseX = useMotionValue(50);
  const mouseY = useMotionValue(50);
  const radius = useSpring(0, { stiffness: 220, damping: 26 });
  const outerRadius = useTransform(radius, (r) => r * 1.4);

  const handleMove = (e: React.MouseEvent<HTMLDivElement>) => {
    const rect = ref.current?.getBoundingClientRect();
    if (!rect) return;
    mouseX.set(((e.clientX - rect.left) / rect.width) * 100);
    mouseY.set(((e.clientY - rect.top) / rect.height) * 100);
  };

  const mask = useMotionTemplate`radial-gradient(circle at ${mouseX}% ${mouseY}%, black 0%, black ${radius}%, transparent ${outerRadius}%)`;

  return (
    <div
      ref={ref}
      onMouseEnter={() => {
        setHovered(true);
        if (!shouldReduceMotion) radius.set(38);
      }}
      onMouseMove={handleMove}
      onMouseLeave={() => {
        setHovered(false);
        radius.set(0);
      }}
      className="group relative aspect-square overflow-hidden border-b border-r border-slate-200 bg-slate-900 dark:border-slate-800"
    >
      {/* eslint-disable-next-line @next/next/no-img-element */}
      <img
        src={cell.image.src}
        alt=""
        className="absolute inset-0 h-full w-full scale-110 object-cover opacity-70 blur-lg transition-[filter,opacity] duration-500 ease-out"
        style={hovered ? { filter: "blur(4px)", opacity: 0.85 } : undefined}
        loading="lazy"
      />
      <motion.div
        aria-hidden
        className="pointer-events-none absolute inset-0"
        style={{ WebkitMaskImage: mask, maskImage: mask }}
      >
        {/* eslint-disable-next-line @next/next/no-img-element */}
        <img src={cell.image.src} alt="" className="h-full w-full object-cover" />
      </motion.div>
      <div className="pointer-events-none absolute inset-0 bg-gradient-to-t from-black/45 via-black/5 to-transparent" />
      <span className="relative z-10 flex h-full w-full items-center justify-center px-3 text-center text-[13px] font-semibold tracking-tight text-white [text-shadow:0_1px_6px_rgba(0,0,0,0.5)]">
        {cell.name}
      </span>
      {hovered && cell.image.credit && (
        <a
          href={cell.image.credit.href}
          target="_blank"
          rel="noopener noreferrer"
          onClick={(e) => e.stopPropagation()}
          className="absolute bottom-1 right-1.5 z-20 text-[9px] font-medium text-white/70 transition-colors hover:text-white"
        >
          Photo: {cell.image.credit.name}
        </a>
      )}
    </div>
  );
}

function PlainCell({ cell }: { cell: LogoWallItem }) {
  const shouldReduceMotion = useReducedMotion();
  const ref = useRef<HTMLDivElement>(null);
  const [origin, setOrigin] = useState({ x: 50, y: 50 });
  const [hovered, setHovered] = useState(false);

  const handleEnter = (e: React.MouseEvent<HTMLDivElement>) => {
    const rect = ref.current?.getBoundingClientRect();
    if (rect) {
      setOrigin({
        x: ((e.clientX - rect.left) / rect.width) * 100,
        y: ((e.clientY - rect.top) / rect.height) * 100,
      });
    }
    setHovered(true);
  };

  return (
    <div
      ref={ref}
      onMouseEnter={handleEnter}
      onMouseLeave={() => setHovered(false)}
      className="relative flex aspect-square items-center justify-center overflow-hidden border-b border-r border-slate-200 bg-slate-50 dark:border-slate-800 dark:bg-neutral-900"
    >
      <span className="relative z-0 px-3 text-center text-[13px] font-semibold tracking-tight text-slate-500 dark:text-slate-400">
        {cell.name}
      </span>
      <div
        aria-hidden
        className={cn(
          "pointer-events-none absolute inset-0 z-10 flex items-center justify-center bg-slate-900 ease-out dark:bg-white",
          shouldReduceMotion ? "transition-opacity duration-150" : "transition-[clip-path] duration-500"
        )}
        style={
          shouldReduceMotion
            ? { opacity: hovered ? 1 : 0 }
            : { clipPath: `circle(${hovered ? 150 : 0}% at ${origin.x}% ${origin.y}%)` }
        }
      >
        <span className="px-3 text-center text-[13px] font-semibold tracking-tight text-white dark:text-slate-900">{cell.name}</span>
      </div>
    </div>
  );
}

export function LogoWall({ items }: { items: LogoWallItem[] }) {
  return (
    <div className="w-full overflow-hidden rounded-lg border-l border-t border-slate-200 dark:border-slate-800">
      <div className="grid grid-cols-3 sm:grid-cols-4 md:grid-cols-7">
        {items.map((cell) =>
          cell.image ? (
            <PhotoCell key={cell.name} cell={cell as LogoWallItem & { image: NonNullable<LogoWallItem["image"]> }} />
          ) : (
            <PlainCell key={cell.name} cell={cell} />
          )
        )}
      </div>
    </div>
  );
}

export function Marquee({ items }: { items: string[] }) {
  const loop = [...items, ...items];

  return (
    <div
      className="group relative w-full overflow-hidden"
      style={{
        maskImage: "linear-gradient(to right, transparent, black 10%, black 90%, transparent)",
        WebkitMaskImage: "linear-gradient(to right, transparent, black 10%, black 90%, transparent)",
      }}
    >
      <style>{`@keyframes marquee-scroll { to { transform: translateX(-50%); } }`}</style>
      <div className="flex w-max animate-[marquee-scroll_16s_linear_infinite] gap-8 group-hover:[animation-play-state:paused] motion-reduce:animate-none">
        {loop.map((item, i) => (
          <span key={i} className="whitespace-nowrap text-sm font-medium text-slate-500 dark:text-slate-400">
            {item}
          </span>
        ))}
      </div>
    </div>
  );
}

"use client";

import { useRef, type ReactNode, type RefObject } from "react";
import { motion, useReducedMotion, useScroll, useTransform, type MotionValue } from "framer-motion";

export type ParallaxEdge = "enter" | "exit" | "through";

function edgeOffset(edge: ParallaxEdge): ["start end" | "end end", "start start" | "end start"] {
  if (edge === "enter") return ["start end", "start start"];
  if (edge === "exit") return ["end end", "end start"];
  return ["start end", "end start"];
}

export function useParallax<T extends HTMLElement = HTMLDivElement>(
  offset: [number, number] = [-40, 40],
  edge: ParallaxEdge = "through"
): { ref: RefObject<T | null>; y: MotionValue<number> } {
  const ref = useRef<T>(null);
  const shouldReduceMotion = useReducedMotion();
  const { scrollYProgress } = useScroll({
    target: ref as RefObject<HTMLElement>,
    offset: edgeOffset(edge),
  });
  const y = useTransform(scrollYProgress, [0, 1], shouldReduceMotion ? [0, 0] : offset);
  return { ref, y };
}

export function ParallaxLayer({
  children,
  offset = [-40, 40],
  edge = "through",
  className,
}: {
  children: ReactNode;
  offset?: [number, number];
  edge?: ParallaxEdge;
  className?: string;
}) {
  const { ref, y } = useParallax<HTMLDivElement>(offset, edge);
  return (
    <motion.div ref={ref} style={{ y }} className={className}>
      {children}
    </motion.div>
  );
}

