"use client";

import { forwardRef, useImperativeHandle, useRef, useState, type ReactNode, type RefObject } from "react";
import {
  AnimatePresence,
  animate,
  motion,
  useMotionValueEvent,
  useReducedMotion,
  useScroll,
  useTransform,
  type MotionValue,
} from "framer-motion";

export interface CardStackItem {
  id: string;
  content: ReactNode;
}

export interface CardStackScrollHandle {
  scrollToId: (id: string) => void;
  scrollToIndex: (index: number) => void;
}

const EASE_SMOOTH = [0.22, 1, 0.36, 1];

function setScrollPosition(el: HTMLElement | null, value: number) {
  if (el) el.scrollTop = value;
  else window.scrollTo(0, value);
}

function StackCard({
  index,
  total,
  progress,
  shouldReduceMotion,
  stickyTop,
  fanOffset,
  pulsing,
  children,
}: {
  index: number;
  total: number;
  progress: MotionValue<number>;
  shouldReduceMotion: boolean;
  stickyTop: number;
  fanOffset: number;
  pulsing: boolean;
  children: ReactNode;
}) {
  // Matches Skiper 16's own StickyCard_001: range starts later for each
  // later card (so earlier cards are already most of the way through their
  // shrink by the time the next one arrives), and every card keeps shrinking
  // all the way to the end of the shared scroll range, not just its own
  // segment - that's what makes an already-departed card still read as a
  // thin sliver behind the current one instead of disappearing outright.
  const rangeStart = index / Math.max(1, total - 1);
  const targetScale = Math.max(0.5, 1 - (total - index - 1) * 0.1);
  const scale = useTransform(progress, [rangeStart, 1], shouldReduceMotion ? [1, 1] : [1, targetScale]);

  return (
    <div className="sticky flex justify-center" style={{ top: stickyTop + index * fanOffset }}>
      {/* flex justify-center here (not just on the sticky wrapper) matters:
          scale transforms around this element's own center, which is the
          row's center since it's full width. If a narrower, width-capped
          card inside it were left-anchored instead of centered, shrinking
          would visibly drag it sideways toward the row's center. Centering
          it here keeps its own center pinned to the scale origin. */}
      <motion.div style={{ scale }} className="relative flex w-full justify-center">
        {children}
        <AnimatePresence>
          {pulsing && !shouldReduceMotion && (
            <motion.span
              aria-hidden
              className="pointer-events-none absolute -inset-2 rounded-[inherit] ring-2 ring-indigo-400/60"
              initial={{ opacity: 0.9, scale: 0.98 }}
              animate={{ opacity: 0, scale: 1.03 }}
              exit={{ opacity: 0 }}
              transition={{ duration: 0.7, ease: EASE_SMOOTH }}
            />
          )}
        </AnimatePresence>
      </motion.div>
    </div>
  );
}

// A vertical stack of cards, each pinned via position: sticky inside its own
// scroll segment, following the same mechanic as Skiper 16's StickyCard_001
// (skiper-ui.com/v1/skiper16): a single shared scroll progress drives every
// card's scale ([i / (total - 1), 1] -> [1, targetScale], targetScale =
// max(0.5, 1 - (total - i - 1) * 0.1)), and `fanOffset` staggers each card's
// sticky top by index so a shrinking card's edge visibly peeks out from
// behind the next one instead of just vanishing underneath it. Pass
// `scrollContainer` when embedding inside a bounded, independently-scrolling
// box; otherwise it tracks the window.
//
// Jumping to a card (via the exposed ref handle) animates that container's
// own scrollTop directly with a custom easing, rather than calling the
// native scrollIntoView on the card: scrollIntoView walks every scrollable
// ancestor it needs, including the page itself, which visibly scrolls the
// outer page out from under a boxed demo. Scrolling exactly one element
// keeps the motion contained to whichever box the stack actually lives in.
export const CardStackScroll = forwardRef<
  CardStackScrollHandle,
  {
    items: CardStackItem[];
    onActiveChange?: (id: string, index: number) => void;
    cardHeight?: number;
    stickyTop?: number;
    fanOffset?: number;
    scrollContainer?: RefObject<HTMLElement | null>;
    className?: string;
  }
>(function CardStackScroll(
  { items, onActiveChange, cardHeight = 420, stickyTop = 32, fanOffset = 0, scrollContainer, className },
  forwardedRef
) {
  const containerRef = useRef<HTMLDivElement>(null);
  const shouldReduceMotion = useReducedMotion();
  const [pulseId, setPulseId] = useState<string | null>(null);
  const { scrollYProgress } = useScroll({
    container: scrollContainer ?? undefined,
    target: containerRef as RefObject<HTMLElement>,
    offset: ["start start", "end end"],
    // If scrollContainer is a ref owned by a parent rather than this
    // component, Framer's default layout effect can read it before that
    // parent's ref has committed. A plain effect (runs after every ref in
    // the tree is attached) avoids that race.
    layoutEffect: false,
  });

  useMotionValueEvent(scrollYProgress, "change", (v) => {
    const idx = Math.min(items.length - 1, Math.max(0, Math.floor(v * items.length)));
    onActiveChange?.(items[idx].id, idx);
  });

  function scrollToIndex(index: number) {
    const item = items[index];
    const target = containerRef.current?.children[index] as HTMLElement | undefined;
    if (!item || !target) return;

    const scrollEl = scrollContainer?.current ?? null;
    const startY = scrollEl ? scrollEl.scrollTop : window.scrollY;
    const refTop = scrollEl ? scrollEl.getBoundingClientRect().top : 0;
    const destY = startY + (target.getBoundingClientRect().top - refTop) - (stickyTop + index * fanOffset);

    if (shouldReduceMotion) {
      setScrollPosition(scrollEl, destY);
    } else {
      animate(startY, destY, {
        duration: 0.9,
        ease: EASE_SMOOTH,
        onUpdate: (v) => setScrollPosition(scrollEl, v),
      });
    }

    setPulseId(item.id);
    window.setTimeout(() => setPulseId((p) => (p === item.id ? null : p)), 750);
  }

  useImperativeHandle(forwardedRef, () => ({
    scrollToId: (id: string) => {
      const index = items.findIndex((entry) => entry.id === id);
      if (index !== -1) scrollToIndex(index);
    },
    scrollToIndex,
  }));

  return (
    <div ref={containerRef} className={className ? `relative ${className}` : "relative"}>
      {items.map((item, i) => (
        <div key={item.id} id={item.id} style={{ height: cardHeight }}>
          <StackCard
            index={i}
            total={items.length}
            progress={scrollYProgress}
            shouldReduceMotion={!!shouldReduceMotion}
            stickyTop={stickyTop}
            fanOffset={fanOffset}
            pulsing={pulseId === item.id}
          >
            {item.content}
          </StackCard>
        </div>
      ))}
    </div>
  );
});

