"use client";

import { useRef } from "react";
import { motion, useMotionValue, useMotionTemplate, useReducedMotion, useSpring, useTransform } from "framer-motion";

export function SpotlightCard({ children }: { children: React.ReactNode }) {
  const ref = useRef<HTMLDivElement>(null);
  const shouldReduceMotion = useReducedMotion();
  const mouseX = useMotionValue(190);
  const mouseY = useMotionValue(90);

  const rotateX = useSpring(
    useTransform(mouseY, [0, 180], shouldReduceMotion ? [0, 0] : [6, -6]),
    { stiffness: 300, damping: 30 }
  );
  const rotateY = useSpring(
    useTransform(mouseX, [0, 380], shouldReduceMotion ? [0, 0] : [-6, 6]),
    { stiffness: 300, damping: 30 }
  );

  const handleMouseMove = (e: React.MouseEvent<HTMLDivElement>) => {
    const rect = ref.current?.getBoundingClientRect();
    if (!rect) return;
    mouseX.set(e.clientX - rect.left);
    mouseY.set(e.clientY - rect.top);
  };

  const background = useMotionTemplate`radial-gradient(200px circle at ${mouseX}px ${mouseY}px, rgba(217,119,6,0.15), transparent 80%)`;
  const borderGlow = useMotionTemplate`radial-gradient(160px circle at ${mouseX}px ${mouseY}px, rgba(245,158,11,0.8), transparent 70%)`;

  return (
    <div style={{ perspective: 800 }}>
      <motion.div
        ref={ref}
        onMouseMove={handleMouseMove}
        style={{ rotateX, rotateY, transformStyle: "preserve-3d" }}
        className="group relative rounded-2xl bg-slate-200 p-px transition-shadow duration-300 hover:shadow-xl dark:bg-slate-700"
      >
        <motion.div
          aria-hidden
          className="pointer-events-none absolute -inset-px rounded-2xl opacity-0 transition-opacity duration-300 group-hover:opacity-100"
          style={{ background: borderGlow }}
        />
        <div className="relative overflow-hidden rounded-[15px] bg-white p-6 dark:bg-neutral-950">
          <motion.div
            aria-hidden
            className="pointer-events-none absolute inset-0 opacity-0 transition-opacity duration-300 group-hover:opacity-100"
            style={{ background }}
          />
          <div className="relative">{children}</div>
        </div>
      </motion.div>
    </div>
  );
}

"use client";

import { useRef, type ReactNode } from "react";
import { motion, useMotionValue, useReducedMotion, useSpring } from "framer-motion";

const RADIUS = 90;
const STRENGTH = 0.4;

export function MagneticButton({ children }: { children: ReactNode }) {
  const ref = useRef<HTMLButtonElement>(null);
  const shouldReduceMotion = useReducedMotion();
  const x = useMotionValue(0);
  const y = useMotionValue(0);
  const springX = useSpring(x, { stiffness: 200, damping: 15, mass: 0.3 });
  const springY = useSpring(y, { stiffness: 200, damping: 15, mass: 0.3 });
  const textX = useSpring(x, { stiffness: 200, damping: 18, mass: 0.2 });
  const textY = useSpring(y, { stiffness: 200, damping: 18, mass: 0.2 });

  const handleMouseMove = (e: React.MouseEvent<HTMLButtonElement>) => {
    if (shouldReduceMotion) return;
    const rect = ref.current?.getBoundingClientRect();
    if (!rect) return;
    const centerX = rect.left + rect.width / 2;
    const centerY = rect.top + rect.height / 2;
    const distX = e.clientX - centerX;
    const distY = e.clientY - centerY;
    const distance = Math.hypot(distX, distY);
    if (distance < RADIUS) {
      x.set(distX * STRENGTH);
      y.set(distY * STRENGTH);
    } else {
      x.set(0);
      y.set(0);
    }
  };

  const handleMouseLeave = () => {
    x.set(0);
    y.set(0);
  };

  return (
    <motion.button
      ref={ref}
      onMouseMove={handleMouseMove}
      onMouseLeave={handleMouseLeave}
      style={{ x: springX, y: springY }}
      whileTap={{ scale: 0.94 }}
      className="rounded-full bg-emerald-700 px-6 py-3 text-sm font-medium text-white shadow-[0_8px_24px_-8px_rgba(4,120,87,0.6)] focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-emerald-700 dark:bg-emerald-500 dark:shadow-[0_8px_24px_-8px_rgba(16,185,129,0.55)] dark:focus-visible:outline-emerald-400"
    >
      <motion.span style={{ x: textX, y: textY }} className="inline-block">
        {children}
      </motion.span>
    </motion.button>
  );
}

"use client";

import { useRef, useState, type ReactNode } from "react";
import { AnimatePresence, motion, useReducedMotion } from "framer-motion";

type Side = "top" | "bottom";

export function Tooltip({ label, children }: { label: string; children: ReactNode }) {
  const [open, setOpen] = useState(false);
  const [side, setSide] = useState<Side>("top");
  const anchorRef = useRef<HTMLSpanElement>(null);
  const shouldReduceMotion = useReducedMotion();

  const showTooltip = () => {
    const rect = anchorRef.current?.getBoundingClientRect();
    if (rect) setSide(rect.top < 60 ? "bottom" : "top");
    setOpen(true);
  };

  return (
    <span
      ref={anchorRef}
      className="relative inline-flex"
      onMouseEnter={showTooltip}
      onMouseLeave={() => setOpen(false)}
      onFocus={showTooltip}
      onBlur={() => setOpen(false)}
    >
      {children}
      <AnimatePresence>
        {open && (
          <motion.span
            role="tooltip"
            initial={shouldReduceMotion ? { opacity: 0 } : { opacity: 0, scale: 0.9, y: side === "top" ? 4 : -4 }}
            animate={{ opacity: 1, scale: 1, y: 0 }}
            exit={shouldReduceMotion ? { opacity: 0 } : { opacity: 0, scale: 0.92, y: side === "top" ? 4 : -4 }}
            transition={{ type: "spring", stiffness: 500, damping: 32 }}
            style={{ transformOrigin: side === "top" ? "bottom" : "top" }}
            className={`pointer-events-none absolute left-1/2 -translate-x-1/2 whitespace-nowrap rounded-md bg-slate-900 px-2.5 py-1.5 text-xs font-medium text-white dark:bg-slate-100 dark:text-slate-900 ${
              side === "top" ? "-top-2 -translate-y-full" : "-bottom-2 translate-y-full"
            }`}
          >
            {label}
            <span
              aria-hidden
              className={`absolute left-1/2 h-2 w-2 -translate-x-1/2 rotate-45 bg-slate-900 dark:bg-slate-100 ${
                side === "top" ? "top-full -mt-1" : "bottom-full -mb-1"
              }`}
            />
          </motion.span>
        )}
      </AnimatePresence>
    </span>
  );
}

export function InfiniteMovingCards({
  items,
  direction = "left",
}: {
  items: { quote: string; name: string; avatarUrl?: string }[];
  direction?: "left" | "right";
}) {
  const loop = [...items, ...items];

  return (
    <div
      className="group relative w-full overflow-hidden"
      style={{
        maskImage: "linear-gradient(to right, transparent, black 10%, black 90%, transparent)",
        WebkitMaskImage: "linear-gradient(to right, transparent, black 10%, black 90%, transparent)",
      }}
    >
      <style>{`@keyframes infinite-cards-scroll { to { transform: translateX(-50%); } }`}</style>
      <div
        className="flex w-max animate-[infinite-cards-scroll_28s_linear_infinite] gap-4 group-hover:[animation-play-state:paused] motion-reduce:animate-none"
        style={{ animationDirection: direction === "right" ? "reverse" : "normal" }}
      >
        {loop.map((item, i) => (
          <div
            key={i}
            className="w-64 shrink-0 rounded-xl border border-slate-200 bg-white p-4 dark:border-slate-700 dark:bg-neutral-950"
          >
            <p className="text-sm text-slate-600 dark:text-slate-300">&ldquo;{item.quote}&rdquo;</p>
            <div className="mt-2 flex items-center gap-2">
              {item.avatarUrl && (
                <img src={item.avatarUrl} alt={item.name} className="h-6 w-6 rounded-full border border-slate-200 object-cover dark:border-slate-700" />
              )}
              <p className="text-xs font-medium text-slate-400 dark:text-slate-500">{item.name}</p>
            </div>
          </div>
        ))}
      </div>
    </div>
  );
}

"use client";

import { motion, useReducedMotion } from "framer-motion";

export function TextGenerateEffect({ text }: { text: string }) {
  const words = text.split(" ");
  const shouldReduceMotion = useReducedMotion();

  return (
    <p className="leading-relaxed">
      {words.map((word, i) => (
        <motion.span
          key={i}
          className="mr-[0.3em] inline-block"
          initial={shouldReduceMotion ? { opacity: 1, filter: "blur(0px)" } : { opacity: 0, filter: "blur(6px)" }}
          whileInView={{ opacity: 1, filter: "blur(0px)" }}
          viewport={{ once: true, margin: "-10% 0px" }}
          transition={{ duration: 0.4, delay: shouldReduceMotion ? 0 : i * 0.08, ease: [0.22, 1, 0.36, 1] }}
        >
          {word}
        </motion.span>
      ))}
    </p>
  );
}

