  id: string;
  name: string;
  role: string;
  tone: Tone;
}

interface SchedEvent {
  id: string;
  resourceId: string;
  date: string; // YYYY-MM-DD (local)
  start: number; // minutes from midnight
  end: number;
  title: string;
}

const DAY_START = 8 * 60; //  8:00
const DAY_END = 19 * 60; // 19:00
const SLOT = 15; // snap interval, minutes
const MIN_DUR = 30; // minimum event length, minutes
const PX_PER_MIN = 0.82; // vertical scale
const GUTTER_W = 52; // time-gutter width, px
const HEADER_H = 52; // column-header height, px

