          transition={shouldReduceMotion ? { duration: 0.2 } : { duration: 1.6, repeat: Infinity, ease: "easeInOut" }}
        />

        {/* one-shot alert ring, timed with the icon shake */}
        {!shouldReduceMotion && (
          <motion.span
            aria-hidden
            className="absolute rounded-full border-2 border-rose-400/60"
            style={{
              width: MEDALLION,
              height: MEDALLION,
              top: "50%",
              left: "50%",
              marginLeft: -HALF,
              marginTop: -HALF,
            }}
            initial={{ scale: 0.7, opacity: 0.9 }}
            animate={{ scale: 1.6, opacity: 0 }}
            transition={{ duration: 0.55, ease: [0.16, 1, 0.3, 1], delay: 0.05 }}
          />
        )}

        <div
          className="relative flex items-center justify-center rounded-full border border-rose-300 bg-rose-50 text-rose-500 dark:border-rose-500/40 dark:bg-rose-500/10 dark:text-rose-400"
          style={{ width: MEDALLION, height: MEDALLION }}
        >
          <motion.span
            className="inline-flex"
            aria-hidden
            initial={{ opacity: 0 }}
            animate={shouldReduceMotion ? { opacity: 1 } : { opacity: 1, x: [0, -4, 4, -3, 3, 0] }}
            transition={{ duration: 0.5, ease: "easeOut" }}
          >
            <PhWarningCircle size={30} />
          </motion.span>
        </div>
      </div>

      <div className="flex flex-col gap-1.5">
        <h3 className="text-base font-semibold text-slate-900 dark:text-white">{title}</h3>
        <p className="text-sm leading-relaxed text-slate-500 dark:text-slate-400">{description}</p>
      </div>

      {action && (
        <motion.button
          onClick={action.onClick}
          whileHover={shouldReduceMotion ? undefined : { y: -2 }}
          whileTap={{ scale: 0.96, y: 0 }}
          transition={{ type: "spring", stiffness: 500, damping: 30 }}
          className="group relative mt-1 inline-flex items-center justify-center overflow-hidden rounded-lg bg-rose-600 px-4 py-2 text-sm font-medium text-white shadow-[0_1px_2px_rgba(225,29,72,0.3)] transition-[box-shadow,background-color] duration-300 hover:bg-rose-500 hover:shadow-[0_10px_20px_-8px_rgba(225,29,72,0.6)] focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-rose-500"
        >
          <span
            aria-hidden
            className="pointer-events-none absolute inset-0 -translate-x-full bg-gradient-to-r from-transparent via-white/30 to-transparent transition-transform duration-700 ease-out group-hover:translate-x-full motion-reduce:hidden"
          />
          <span className="relative">{action.label}</span>
        </motion.button>
      )}
    </div>
  );
}

"use client";

import { useState } from "react";
import { AnimatePresence, motion, useReducedMotion } from "framer-motion";
import {
  ShieldWarningIcon as PhShield,
  MegaphoneSimpleIcon as PhMegaphone,
  AtIcon as PhAt,
  CheckIcon as PhCheck,
  ArrowClockwiseIcon as PhReset,
} from "@phosphor-icons/react";

interface Channel {
  id: string;
  label: string;
  detail: string;
  icon: typeof PhShield;
}

const CHANNELS: Channel[] = [
  { id: "security", label: "Security alert", detail: "New sign-in from an unrecognized device.", icon: PhShield },
  { id: "product", label: "Product update", detail: "Dark mode is now available in Settings.", icon: PhMegaphone },
  { id: "mention", label: "You were mentioned", detail: "@Alex mentioned you in #design-review.", icon: PhAt },
];

const MAX_STREAK = 3;

function ResetIcon() {
  return <PhReset size={13} aria-hidden />;
}
function CheckIcon() {
  return <PhCheck size={12} aria-hidden />;
}

function intensityOf(streak: number) {
  return Math.min(1, streak / MAX_STREAK);
}

function AttentionIcon({
  Icon,
  intensity,
  pulseDuration,
  celebrate,
  shouldReduceMotion,
}: {
  Icon: typeof PhShield;
  intensity: number;
  pulseDuration: number;
  celebrate: boolean;
  shouldReduceMotion: boolean | null;
}) {
  return (
    <span className="relative flex h-8 w-8 shrink-0 items-center justify-center">
      <motion.span
        aria-hidden
        className={`absolute inset-0 rounded-full ${intensity > 0.5 ? "bg-rose-500/25" : "bg-amber-500/20"}`}
        animate={shouldReduceMotion || intensity === 0 ? { opacity: 0, scale: 1 } : { opacity: [0.6, 0, 0.6], scale: [1, 1.5, 1] }}
        transition={{ duration: pulseDuration || 2.2, repeat: Infinity, ease: "easeInOut" }}
      />
      {celebrate && !shouldReduceMotion && (
        <motion.span
          aria-hidden
          className="absolute inset-0 rounded-full border-2 border-emerald-400/60"
          initial={{ scale: 0.8, opacity: 0.9 }}
          animate={{ scale: 1.8, opacity: 0 }}
          transition={{ duration: 0.6, ease: [0.16, 1, 0.3, 1] }}
        />
      )}
      <motion.span
        animate={celebrate && !shouldReduceMotion ? { scale: [1, 1.15, 1] } : { scale: 1 }}
        transition={{ duration: 0.4, ease: [0.22, 1, 0.36, 1] }}
        className={`relative flex h-8 w-8 shrink-0 items-center justify-center rounded-full transition-colors duration-300 ${
          intensity > 0.5
            ? "bg-rose-500/15 text-rose-600 dark:text-rose-400"
            : intensity > 0
              ? "bg-amber-500/15 text-amber-600 dark:text-amber-400"
              : "bg-slate-100 text-slate-500 dark:bg-white/10 dark:text-slate-400"
        }`}
      >
        <Icon size={15} aria-hidden />
      </motion.span>
    </span>
  );
}

function ChannelBody({
  channel,
  streak,
  intensity,
  acknowledged,
  onOpen,
  onSnooze,
  shouldReduceMotion,
}: {
  channel: Channel;
  streak: number;
  intensity: number;
  acknowledged: boolean;
  onOpen: () => void;
  onSnooze: () => void;
  shouldReduceMotion: boolean | null;
}) {
  return (
    <div className="min-w-0 flex-1">
      <p className="text-sm font-medium text-slate-800 dark:text-slate-100">{channel.label}</p>
      <p className="mt-0.5 text-xs text-slate-500 dark:text-slate-400">{channel.detail}</p>
      <p
        className={`mt-1 text-[11px] font-medium ${
          intensity > 0.5 ? "text-rose-600 dark:text-rose-400" : intensity > 0 ? "text-amber-600 dark:text-amber-400" : "text-slate-400 dark:text-slate-500"
        }`}
      >
        {streak === 0 ? "Just opened, back to calm." : `Ignored ${streak} time${streak === 1 ? "" : "s"} in a row.`}
      </p>

      <div className="mt-2 flex items-center gap-2">
        <motion.button
          type="button"
          onClick={onOpen}
          whileHover={shouldReduceMotion ? undefined : { y: -1 }}
          whileTap={shouldReduceMotion ? undefined : { scale: 0.96 }}
          className="inline-flex items-center gap-1 rounded-lg bg-slate-900 px-2.5 py-1 text-xs font-medium text-white transition-colors hover:bg-slate-700 focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-emerald-600 dark:bg-white dark:text-slate-900 dark:hover:bg-slate-200"
        >
          <AnimatePresence mode="wait" initial={false}>
            {acknowledged ? (
              <motion.span key="done" initial={{ opacity: 0, scale: 0.6 }} animate={{ opacity: 1, scale: 1 }} exit={{ opacity: 0, scale: 0.6 }} className="flex items-center gap-1">
                <CheckIcon />
                Opened
              </motion.span>
            ) : (
              <motion.span key="open" initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }}>
                Open
              </motion.span>
            )}
          </AnimatePresence>
        </motion.button>
        <motion.button
          type="button"
          onClick={onSnooze}
          whileHover={shouldReduceMotion ? undefined : { y: -1 }}
          whileTap={shouldReduceMotion ? undefined : { scale: 0.96 }}
          className="rounded-lg px-2.5 py-1 text-xs font-medium text-slate-500 transition-colors hover:bg-black/5 dark:text-slate-400 dark:hover:bg-white/10"
        >
          Not now
        </motion.button>
      </div>
    </div>
  );
}

interface AttentionGradientProps {
  className?: string;
}

export function AttentionGradient({ className }: AttentionGradientProps) {
  const [streaks, setStreaks] = useState<Record<string, number>>(() => Object.fromEntries(CHANNELS.map((c) => [c.id, 0])));
  const [acknowledged, setAcknowledged] = useState<string | null>(null);
  const [celebrateId, setCelebrateId] = useState<string | null>(null);
  const shouldReduceMotion = useReducedMotion();

  const open = (id: string) => {
    setStreaks((prev) => ({ ...prev, [id]: 0 }));
    setAcknowledged(id);
    setCelebrateId(id);
    setTimeout(() => setAcknowledged((a) => (a === id ? null : a)), 700);
    setTimeout(() => setCelebrateId((c) => (c === id ? null : c)), 650);
  };

  const snooze = (id: string) => {
    setStreaks((prev) => ({ ...prev, [id]: Math.min(MAX_STREAK, prev[id] + 1) }));
  };

  const reset = () => {
    setStreaks(Object.fromEntries(CHANNELS.map((c) => [c.id, 0])));
    setAcknowledged(null);
    setCelebrateId(null);
  };

  return (
    <div className={className}>
      <div className="w-full rounded-2xl border border-slate-200/70 bg-white/95 p-5 shadow-sm backdrop-blur-xl dark:border-white/10 dark:bg-neutral-950/80">
        <div className="flex items-center justify-between gap-3">
          <h3 className="text-sm font-semibold text-slate-900 dark:text-white">Notifications</h3>
          <motion.button
            type="button"
            onClick={reset}
            aria-label="Reset all channels"
            whileTap={shouldReduceMotion ? undefined : { scale: 0.9 }}
            className="flex h-7 w-7 shrink-0 items-center justify-center rounded-lg text-slate-400 transition-colors hover:bg-black/5 hover:text-slate-600 focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-slate-400 dark:hover:bg-white/10 dark:hover:text-slate-300"
          >
            <ResetIcon />
          </motion.button>
        </div>

        <div className="mt-3 space-y-2.5">
          {CHANNELS.map((channel) => {
            const streak = streaks[channel.id];
            const intensity = intensityOf(streak);
            const Icon = channel.icon;
            const pulseDuration = shouldReduceMotion ? 0 : 2.2 - intensity * 1.5;
            return (
              <div key={channel.id} className="relative overflow-hidden rounded-xl border border-slate-200/70 dark:border-white/10">
                <span className="absolute inset-0 bg-slate-50 dark:bg-white/[0.03]" aria-hidden />
                <motion.span
                  className="absolute inset-0 bg-amber-500/10 dark:bg-amber-500/[0.08]"
                  aria-hidden
                  animate={{ opacity: Math.min(1, intensity * 2) }}
                  transition={{ duration: 0.4, ease: [0.22, 1, 0.36, 1] }}
                />
                <motion.span
                  className="absolute inset-0 bg-rose-500/10 dark:bg-rose-500/[0.08]"
                  aria-hidden
                  animate={{ opacity: Math.max(0, intensity * 2 - 1) }}
                  transition={{ duration: 0.4, ease: [0.22, 1, 0.36, 1] }}
                />

                {streak > 0 ? (
                  <motion.div
                    key={streak}
                    initial={{ x: 0 }}
                    animate={shouldReduceMotion ? { x: 0 } : { x: [0, -3, 3, -2, 2, 0] }}
                    transition={{ duration: 0.4, ease: [0.36, 0.07, 0.19, 0.97] }}
                    className="relative flex items-start gap-3 p-3"
                  >
                    <AttentionIcon Icon={Icon} intensity={intensity} pulseDuration={pulseDuration} celebrate={celebrateId === channel.id} shouldReduceMotion={shouldReduceMotion} />
                    <ChannelBody
                      channel={channel}
                      streak={streak}
                      intensity={intensity}
                      acknowledged={acknowledged === channel.id}
                      onOpen={() => open(channel.id)}
                      onSnooze={() => snooze(channel.id)}
                      shouldReduceMotion={shouldReduceMotion}
                    />
                  </motion.div>
                ) : (
                  <div className="relative flex items-start gap-3 p-3">
                    <AttentionIcon Icon={Icon} intensity={intensity} pulseDuration={pulseDuration} celebrate={celebrateId === channel.id} shouldReduceMotion={shouldReduceMotion} />
                    <ChannelBody
                      channel={channel}
                      streak={streak}
                      intensity={intensity}
                      acknowledged={acknowledged === channel.id}
                      onOpen={() => open(channel.id)}
                      onSnooze={() => snooze(channel.id)}
                      shouldReduceMotion={shouldReduceMotion}
                    />
                  </div>
                )}
              </div>
            );
          })}
        </div>
      </div>
      <p className="text-center text-xs text-slate-400 dark:text-slate-500">
        Urgency isn&apos;t a fixed badge, it&apos;s computed from what you actually do: ignore a channel a few times and it genuinely escalates, open it once and it snaps right back to calm.
      </p>
    </div>
  );
}

"use client";

import { useState } from "react";
import { AnimatePresence, motion, useReducedMotion } from "framer-motion";
import {
  DatabaseIcon as PhDatabase,
  MagicWandIcon as PhWand,
  CheckIcon as PhCheck,
  WarningCircleIcon as PhWarning,
  ArrowClockwiseIcon as PhReset,
} from "@phosphor-icons/react";

interface FieldDef {
  id: string;
  label: string;
  expected: string;
  initial: string;
}

const FIELDS: FieldDef[] = [
  { id: "host", label: "Host", expected: "db.acme.com", initial: "db.acme.com" },
  { id: "port", label: "Port", expected: "5432", initial: "5433" },
  { id: "apiKey", label: "API key", expected: "sk-live-9f8a2b31", initial: "live-9f8a2b31" },
];

interface DiffResult {
  prefix: string;
  gotMid: string;
  expectedMid: string;
  suffix: string;
}

function diffStrings(expected: string, actual: string): DiffResult | null {
  if (expected === actual) return null;
  const maxPrefix = Math.min(expected.length, actual.length);
  let prefixLen = 0;
  while (prefixLen < maxPrefix && expected[prefixLen] === actual[prefixLen]) prefixLen++;
  const maxSuffix = Math.min(expected.length, actual.length) - prefixLen;
  let suffixLen = 0;
  while (suffixLen < maxSuffix && expected[expected.length - 1 - suffixLen] === actual[actual.length - 1 - suffixLen]) suffixLen++;
  return {
    prefix: expected.slice(0, prefixLen),
    gotMid: actual.slice(prefixLen, actual.length - suffixLen),
    expectedMid: expected.slice(prefixLen, expected.length - suffixLen),
    suffix: suffixLen > 0 ? expected.slice(expected.length - suffixLen) : "",
  };
}

function ResetIcon() {
  return <PhReset size={13} aria-hidden />;
}
function CheckIcon() {
  return <PhCheck size={12} aria-hidden />;
}
function WarningIcon() {
  return <PhWarning size={13} aria-hidden />;
}
function WandIcon() {
  return <PhWand size={12} aria-hidden />;
}
function DatabaseIcon() {
  return <PhDatabase size={14} weight="fill" aria-hidden />;
}

function initialValues(): Record<string, string> {
  return Object.fromEntries(FIELDS.map((f) => [f.id, f.initial]));
}

type CheckStatus = "idle" | "checking" | "checked";

interface RecoveryDiffProps {
  className?: string;
}

export function RecoveryDiff({ className }: RecoveryDiffProps) {
  const [values, setValues] = useState<Record<string, string>>(initialValues);
  const [status, setStatus] = useState<CheckStatus>("idle");
  const [errors, setErrors] = useState<Record<string, DiffResult>>({});
  const [checkRun, setCheckRun] = useState(0);
  const [flashId, setFlashId] = useState<string | null>(null);
  const shouldReduceMotion = useReducedMotion();

  const runCheck = () => {
    setStatus("checking");
    setTimeout(
      () => {
        const nextErrors: Record<string, DiffResult> = {};
        FIELDS.forEach((field) => {
          const diff = diffStrings(field.expected, values[field.id]);
          if (diff) nextErrors[field.id] = diff;
        });
        setErrors(nextErrors);
        setStatus("checked");
        setCheckRun((n) => n + 1);
      },
      shouldReduceMotion ? 80 : 500
    );
  };

  const applyFix = (field: FieldDef) => {
    setValues((prev) => ({ ...prev, [field.id]: field.expected }));
    setErrors((prev) => {
      const next = { ...prev };
      delete next[field.id];
      return next;
    });
    setFlashId(field.id);
    setTimeout(() => setFlashId((f) => (f === field.id ? null : f)), 700);
  };

  const updateValue = (id: string, value: string) => {
    setValues((prev) => ({ ...prev, [id]: value }));
    if (status === "checked") setStatus("idle");
  };

  const reset = () => {
    setValues(initialValues());
    setErrors({});
    setStatus("idle");
    setFlashId(null);
  };

  const brokenCount = Object.keys(errors).length;
  const allGood = status === "checked" && brokenCount === 0;

  return (
    <div className={className}>
      <div className="w-full rounded-2xl border border-slate-200/70 bg-white/95 p-5 shadow-sm backdrop-blur-xl dark:border-white/10 dark:bg-neutral-950/80">
        <div className="flex items-center justify-between gap-3">
          <h3 className="flex items-center gap-1.5 text-sm font-semibold text-slate-900 dark:text-white">
            <DatabaseIcon />
            Connect database
          </h3>
          <motion.button
            type="button"
            onClick={reset}
            aria-label="Reset to broken example"
            whileTap={shouldReduceMotion ? undefined : { scale: 0.9 }}
            className="flex h-7 w-7 shrink-0 items-center justify-center rounded-lg text-slate-400 transition-colors hover:bg-black/5 hover:text-slate-600 focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-slate-400 dark:hover:bg-white/10 dark:hover:text-slate-300"
          >
            <ResetIcon />
          </motion.button>
        </div>

        <div className="mt-3 space-y-3">
          {FIELDS.map((field) => {
            const error = errors[field.id];
            const flashing = flashId === field.id;
            return (
              <div key={field.id}>
                <label className="flex flex-col gap-1">
                  <span className="text-xs font-medium text-slate-500 dark:text-slate-400">{field.label}</span>
                  <motion.div
                    key={error ? `${field.id}-shake-${checkRun}` : `${field.id}-still`}
                    initial={{ x: 0 }}
                    animate={error && !shouldReduceMotion ? { x: [0, -4, 4, -3, 3, -1, 1, 0] } : { x: 0 }}
                    transition={{ duration: 0.45, ease: [0.36, 0.07, 0.19, 0.97] }}
                  >
                    <motion.input
                      type="text"
                      value={values[field.id]}
                      onChange={(e) => updateValue(field.id, e.target.value)}
                      spellCheck={false}
                      animate={
                        flashing && !shouldReduceMotion
                          ? { boxShadow: ["0 0 0 3px rgba(5,150,105,0.4)", "0 0 0 3px rgba(5,150,105,0)"] }
                          : { boxShadow: "0 0 0 3px rgba(5,150,105,0)" }
                      }
                      transition={{ duration: 0.7, ease: [0.22, 1, 0.36, 1] }}
                      className={`w-full rounded-lg border bg-white/60 px-3 py-2 font-mono text-sm text-slate-800 focus:outline-none dark:bg-white/5 dark:text-slate-100 ${
                        error
                          ? "border-rose-300 focus-visible:border-rose-500 dark:border-rose-500/40"
                          : "border-slate-200/70 focus-visible:border-emerald-500 dark:border-white/10"
                      }`}
                    />
                  </motion.div>
                </label>
                <AnimatePresence>
                  {error && (
                    <motion.div
                      initial={shouldReduceMotion ? { opacity: 0 } : { opacity: 0, height: 0 }}
                      animate={{ opacity: 1, height: "auto" }}
                      exit={shouldReduceMotion ? { opacity: 0 } : { opacity: 0, height: 0 }}
                      transition={{ duration: 0.25, ease: [0.22, 1, 0.36, 1] }}
                      className="overflow-hidden"
                    >
                      <div className="mt-1.5 rounded-lg border border-rose-200 bg-rose-50/70 p-2.5 dark:border-rose-500/25 dark:bg-rose-500/10">
                        <p className="flex items-center gap-1.5 text-xs font-medium text-rose-700 dark:text-rose-300">
                          <WarningIcon />
                          Doesn&apos;t match what&apos;s expected
                        </p>
                        <p className="mt-1 break-all font-mono text-xs text-slate-600 dark:text-slate-300">
                          {error.prefix}
                          <span className="rounded bg-rose-200/70 px-0.5 text-rose-700 line-through dark:bg-rose-500/25 dark:text-rose-300">
                            {error.gotMid}
                          </span>
                          <span className="rounded bg-emerald-200/70 px-0.5 text-emerald-700 dark:bg-emerald-500/25 dark:text-emerald-300">
                            {error.expectedMid}
                          </span>
                          {error.suffix}
                        </p>
                        <motion.button
                          type="button"
                          onClick={() => applyFix(field)}
                          whileHover={shouldReduceMotion ? undefined : { y: -1 }}
                          whileTap={shouldReduceMotion ? undefined : { scale: 0.96 }}
                          className="mt-2 inline-flex items-center gap-1.5 rounded-lg bg-emerald-600 px-2.5 py-1 text-xs font-medium text-white shadow-sm transition-colors hover:bg-emerald-500 focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-emerald-600"
                        >
                          <motion.span
                            aria-hidden
                            animate={shouldReduceMotion ? { rotate: 0 } : { rotate: [0, -15, 15, 0] }}
                            transition={{ duration: 0.5, repeat: Infinity, repeatDelay: 1.2, ease: "easeInOut" }}
                          >
                            <WandIcon />
                          </motion.span>
                          Use &ldquo;{field.expected}&rdquo;
                        </motion.button>
                      </div>
                    </motion.div>
                  )}
                </AnimatePresence>
              </div>
            );
          })}
        </div>

        <motion.button
          type="button"
          onClick={runCheck}
          disabled={status === "checking"}
          whileHover={shouldReduceMotion ? undefined : { y: -1 }}
          whileTap={shouldReduceMotion ? undefined : { scale: 0.98 }}
          className="mt-4 inline-flex w-full items-center justify-center gap-2 rounded-lg bg-slate-900 px-4 py-2 text-sm font-medium text-white shadow-sm transition-colors hover:bg-slate-700 focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-emerald-600 disabled:opacity-60 dark:bg-white dark:text-slate-900 dark:hover:bg-slate-200"
        >
          {status === "checking" ? (
            <motion.span
              aria-hidden
              className="h-3.5 w-3.5 rounded-full border-2 border-white/30 border-t-white dark:border-slate-900/30 dark:border-t-slate-900"
              animate={shouldReduceMotion ? { rotate: 0 } : { rotate: 360 }}
              transition={shouldReduceMotion ? { duration: 0 } : { duration: 0.7, repeat: Infinity, ease: "linear" }}
            />
          ) : (
            <DatabaseIcon />
          )}
          {status === "checking" ? "Checking..." : "Connect"}
        </motion.button>

        <AnimatePresence>
          {allGood && (
            <motion.p
              initial={shouldReduceMotion ? { opacity: 0 } : { opacity: 0, y: -4 }}
              animate={{ opacity: 1, y: 0 }}
              exit={shouldReduceMotion ? { opacity: 0 } : { opacity: 0, y: -4 }}
              transition={{ duration: 0.25, ease: [0.22, 1, 0.36, 1] }}
              className="mt-2.5 flex items-center gap-1.5 text-xs font-medium text-emerald-600 dark:text-emerald-400"
            >
              <span className="relative flex h-4 w-4 items-center justify-center rounded-full bg-emerald-600 text-white">
                {!shouldReduceMotion && (
                  <motion.span
                    aria-hidden
                    className="absolute inset-0 rounded-full border-2 border-emerald-400/60"
                    initial={{ scale: 0.7, opacity: 0.9 }}
                    animate={{ scale: 2, opacity: 0 }}
                    transition={{ duration: 0.6, ease: [0.16, 1, 0.3, 1] }}
                  />
                )}
                <CheckIcon />
              </span>
              Connected, all {FIELDS.length} fields verified.
            </motion.p>
          )}
        </AnimatePresence>
      </div>
      <p className="text-center text-xs text-slate-400 dark:text-slate-500">
        Each failure shows exactly what differs and a one-click fix for that specific problem, not a generic retry.
      </p>
    </div>
  );
}

"use client";

import { useState } from "react";
import { motion, useReducedMotion } from "framer-motion";
import {
  PlugsConnectedIcon as PhPlug,
  LockSimpleIcon as PhLock,
  CalendarIcon as PhCalendar,
  CheckIcon as PhCheck,
} from "@phosphor-icons/react";

interface ScopeDef {
  id: string;
  label: string;
  detail: string;
}

const SCOPES: ScopeDef[] = [
  { id: "read-events", label: "Read your events", detail: "See event titles, times, and attendees." },
  { id: "write-events", label: "Create and edit events", detail: "Add, move, or cancel events on your behalf." },
  { id: "read-contacts", label: "Read your contacts", detail: "Look up names to suggest attendees." },
];

function PlugIcon() {
  return <PhPlug size={15} weight="fill" aria-hidden />;
}
function LockIcon() {
  return <PhLock size={11} aria-hidden />;
}
function CalendarIcon() {
  return <PhCalendar size={13} aria-hidden />;
}
function CheckIcon() {
  return <PhCheck size={11} aria-hidden />;
}

interface ScopePreviewProps {
  className?: string;
}

export function ScopePreview({ className }: ScopePreviewProps) {
  const [enabled, setEnabled] = useState<Record<string, boolean>>({
    "read-events": true,
    "write-events": false,
    "read-contacts": false,
  });
  const [hovered, setHovered] = useState<string | null>(null);
  const shouldReduceMotion = useReducedMotion();

  const toggle = (id: string) => {
    setEnabled((prev) => ({ ...prev, [id]: !prev[id] }));
  };

  const hasReadEvents = enabled["read-events"];
  const hasWriteEvents = enabled["write-events"];
  const hasReadContacts = enabled["read-contacts"];
  const canAdd = hasReadEvents && hasWriteEvents;

  const powers = (ids: string[]) => hovered !== null && ids.includes(hovered);

  return (
    <div className={className}>
      <div className="w-full rounded-2xl border border-slate-200/70 bg-white/95 p-5 shadow-sm backdrop-blur-xl dark:border-white/10 dark:bg-neutral-950/80">
        <h3 className="flex items-center gap-1.5 text-sm font-semibold text-slate-900 dark:text-white">
          <PlugIcon />
          Connect Calendar
        </h3>

        <div className="mt-3 space-y-1">
          {SCOPES.map((scope) => {
            const on = enabled[scope.id];
            return (
              <div
                key={scope.id}
                onMouseEnter={() => setHovered(scope.id)}
                onMouseLeave={() => setHovered((h) => (h === scope.id ? null : h))}
                className={`flex items-start gap-2.5 rounded-lg p-2 transition-colors ${
                  on ? "bg-emerald-50/70 dark:bg-emerald-500/10" : ""
                }`}
              >
                <motion.button
                  type="button"
                  role="switch"
                  aria-checked={on}
                  aria-label={scope.label}
                  onClick={() => toggle(scope.id)}
                  onFocus={() => setHovered(scope.id)}
                  onBlur={() => setHovered((h) => (h === scope.id ? null : h))}
                  whileTap={shouldReduceMotion ? undefined : { scale: 0.93 }}
                  className={`relative mt-0.5 h-5 w-9 shrink-0 rounded-full transition-colors duration-300 focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-emerald-600 ${
                    on ? "bg-emerald-600" : "bg-slate-300 dark:bg-slate-600"
                  }`}
                >
                  <motion.span
                    animate={{ x: on ? 17 : 2 }}
                    transition={shouldReduceMotion ? { duration: 0 } : { type: "spring", stiffness: 700, damping: 32 }}
                    className="absolute top-0.5 block h-4 w-4 rounded-full bg-white shadow-sm"
                  />
                </motion.button>
                <span className="min-w-0 flex-1">
                  <span className="block text-xs font-medium text-slate-800 dark:text-slate-100">{scope.label}</span>
                  <span className="block text-[11px] text-slate-500 dark:text-slate-400">{scope.detail}</span>
                </span>
              </div>
            );
