        <div className="mt-4 rounded-xl border border-slate-200/70 bg-slate-50/70 p-3.5 dark:border-white/10 dark:bg-white/[0.03]">
          <p className="text-[11px] font-medium uppercase tracking-wide text-slate-400 dark:text-slate-500">
            Preview: what this could do
          </p>

          <p className="mt-2 text-xs text-slate-600 dark:text-slate-300">
            Team Sync request from{" "}
            <motion.span
              animate={powers(["read-contacts"]) && !shouldReduceMotion ? { scale: 1.04 } : { scale: 1 }}
              className={`inline-block rounded px-0.5 font-medium transition-colors ${
                powers(["read-contacts"])
                  ? "bg-emerald-200/60 text-emerald-800 dark:bg-emerald-500/20 dark:text-emerald-300"
                  : "text-slate-700 dark:text-slate-200"
              }`}
            >
              {hasReadContacts ? "Alex Chen" : "alex@co.com"}
            </motion.span>
            , Friday 2:00 PM.
          </p>

          <div
            className={`mt-2 flex items-center gap-1.5 rounded-lg px-2 py-1.5 text-xs transition-all ${
              powers(["read-events"]) ? "ring-1 ring-emerald-400/60" : ""
            } ${
              hasReadEvents
                ? "bg-emerald-50/80 text-emerald-700 dark:bg-emerald-500/10 dark:text-emerald-300"
                : "bg-white/60 text-slate-400 dark:bg-white/[0.03] dark:text-slate-500"
            }`}
          >
            {hasReadEvents ? <CheckIcon /> : <LockIcon />}
            {hasReadEvents ? "Checked, your calendar is free then." : "Could check your calendar for conflicts."}
          </div>

          <div
            className={`mt-2 flex items-center justify-between gap-2 rounded-lg bg-white/60 px-2 py-1.5 transition-all dark:bg-white/[0.03] ${
              powers(["read-events", "write-events"]) ? "ring-1 ring-emerald-400/60" : ""
            }`}
          >
            <span className="flex items-center gap-1.5 text-xs text-slate-500 dark:text-slate-400">
              <CalendarIcon />
              {canAdd ? "Ready to add to your calendar." : "Requires read + create access."}
            </span>
            <span
              className={`inline-flex shrink-0 items-center gap-1 rounded-md px-2 py-1 text-[11px] font-medium transition-colors ${
                canAdd ? "bg-emerald-600 text-white" : "bg-slate-200 text-slate-400 dark:bg-white/10 dark:text-slate-500"
              }`}
            >
              {canAdd ? <CheckIcon /> : <LockIcon />}
              Add to calendar
            </span>
          </div>
        </div>
      </div>
      <p className="text-center text-xs text-slate-400 dark:text-slate-500">
        Toggle a scope and the preview recomputes live, hover one to see exactly which parts of the example it powers, alone or combined with another.
      </p>
    </div>
  );
}

"use client";

import { useState } from "react";
import { AnimatePresence, motion, useReducedMotion } from "framer-motion";
import { ShieldCheckIcon as PhShield, ArrowCounterClockwiseIcon as PhReset } from "@phosphor-icons/react";

interface GrantDef {
  id: string;
  label: string;
  detail: string;
  grantedLabel: string;
}

const GRANTS: GrantDef[] = [
  { id: "calendar-read", label: "Read your events", detail: "Sees event titles, times, and attendees.", grantedLabel: "Granted 12 days ago" },
  { id: "calendar-write", label: "Create and edit events", detail: "Adds, moves, or cancels events for you.", grantedLabel: "Granted 12 days ago" },
  { id: "contacts-read", label: "Read your contacts", detail: "Looks up names to suggest attendees.", grantedLabel: "Granted 5 days ago" },
  { id: "location", label: "Read your location", detail: "Suggests nearby meeting spots.", grantedLabel: "Granted 2 days ago" },
];

interface FeatureDef {
  id: string;
  label: string;
  requires: string[];
}

const FEATURES: FeatureDef[] = [
  { id: "smart-scheduling", label: "Smart scheduling", requires: ["calendar-read", "calendar-write"] },
  { id: "attendee-suggestions", label: "Attendee name suggestions", requires: ["calendar-read", "contacts-read"] },
  { id: "nearby-spots", label: "Nearby meeting spot suggestions", requires: ["calendar-write", "location"] },
];

function ShieldIcon() {
  return <PhShield size={15} aria-hidden />;
}
function ResetIcon() {
  return <PhReset size={13} aria-hidden />;
}

function labelFor(id: string) {
  return GRANTS.find((g) => g.id === id)?.label ?? id;
}

function initialActive(): Record<string, boolean> {
  return Object.fromEntries(GRANTS.map((g) => [g.id, true]));
}

interface ConsentLedgerProps {
  className?: string;
}

export function ConsentLedger({ className }: ConsentLedgerProps) {
  const [active, setActive] = useState<Record<string, boolean>>(initialActive);
  const shouldReduceMotion = useReducedMotion();

  const toggle = (id: string) => {
    setActive((prev) => ({ ...prev, [id]: !prev[id] }));
  };

  const reset = () => {
    setActive(initialActive());
  };

  const activeCount = Object.values(active).filter(Boolean).length;

  return (
    <div className={className}>
      <div className="w-full rounded-2xl border border-slate-200/70 bg-white/95 p-5 shadow-sm backdrop-blur-xl dark:border-white/10 dark:bg-neutral-950/80">
        <div className="flex items-center justify-between gap-3">
          <h3 className="flex items-center gap-1.5 text-sm font-semibold text-slate-900 dark:text-white">
            <ShieldIcon />
            Permissions
          </h3>
          <motion.button
            type="button"
            onClick={reset}
            aria-label="Reset all permissions"
            whileTap={shouldReduceMotion ? undefined : { scale: 0.9 }}
            className="flex h-7 w-7 shrink-0 items-center justify-center rounded-lg text-slate-400 transition-colors hover:bg-black/5 hover:text-slate-600 focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-slate-400 dark:hover:bg-white/10 dark:hover:text-slate-300"
          >
            <ResetIcon />
          </motion.button>
        </div>

        <p className="mt-1 flex items-center gap-1 text-xs text-slate-400 dark:text-slate-500">
          <span className="relative inline-block h-[1.4em] w-3 align-middle">
            <AnimatePresence mode="popLayout" initial={false}>
              <motion.span
                key={activeCount}
                initial={shouldReduceMotion ? { opacity: 0 } : { opacity: 0, y: 8 }}
                animate={{ opacity: 1, y: 0 }}
                exit={shouldReduceMotion ? { opacity: 0 } : { opacity: 0, y: -8 }}
                transition={{ duration: 0.2, ease: [0.22, 1, 0.36, 1] }}
                className="absolute inset-0 flex items-center justify-center font-semibold text-slate-600 dark:text-slate-300"
              >
                {activeCount}
              </motion.span>
            </AnimatePresence>
          </span>
          of {GRANTS.length} permissions active, revoke any of them right here
        </p>

        <div className="mt-3 space-y-1.5">
          {GRANTS.map((g) => {
            const on = active[g.id];
            return (
              <div key={g.id} className="rounded-lg p-2 transition-colors">
                <div className="flex items-start gap-2.5">
                  <motion.button
                    type="button"
                    role="switch"
                    aria-checked={on}
                    aria-label={g.label}
                    onClick={() => toggle(g.id)}
                    whileTap={shouldReduceMotion ? undefined : { scale: 0.93 }}
                    className={`relative mt-0.5 h-5 w-9 shrink-0 rounded-full transition-colors duration-300 focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-emerald-600 ${
                      on ? "bg-emerald-600" : "bg-slate-300 dark:bg-slate-600"
                    }`}
                  >
                    <motion.span
                      animate={{ x: on ? 17 : 2 }}
                      transition={shouldReduceMotion ? { duration: 0 } : { type: "spring", stiffness: 700, damping: 32 }}
                      className="absolute top-0.5 block h-4 w-4 rounded-full bg-white shadow-sm"
                    />
                  </motion.button>
                  <span className="min-w-0 flex-1">
                    <span
                      className={`block text-xs font-medium transition-colors ${
                        on ? "text-slate-800 dark:text-slate-100" : "text-slate-400 line-through dark:text-slate-600"
                      }`}
                    >
                      {g.label}
                    </span>
                    <span className="block text-[11px] text-slate-500 dark:text-slate-400">
                      {on ? g.grantedLabel : "Revoked, flip it back to restore."}
                    </span>
                  </span>
                </div>
              </div>
            );
          })}
        </div>

        <div className="mt-4 rounded-xl border border-slate-200/70 bg-slate-50/70 p-3.5 dark:border-white/10 dark:bg-white/[0.03]">
          <p className="text-[11px] font-medium uppercase tracking-wide text-slate-400 dark:text-slate-500">
            What this powers right now
          </p>
          <div className="mt-2 space-y-1.5">
            {FEATURES.map((f) => {
              const unlocked = f.requires.every((id) => active[id]);
              const missing = f.requires.filter((id) => !active[id]);
              return (
                <div key={f.id} className="text-xs">
                  <span className="relative inline-block">
                    <span className={unlocked ? "text-slate-700 dark:text-slate-200" : "text-slate-400 dark:text-slate-500"}>
                      {f.label}
                    </span>
                    <motion.span
                      aria-hidden
                      className="absolute left-0 top-1/2 h-px w-full origin-left bg-slate-400 dark:bg-slate-500"
                      animate={{ scaleX: unlocked ? 0 : 1 }}
                      transition={shouldReduceMotion ? { duration: 0 } : { duration: 0.3, ease: [0.22, 1, 0.36, 1] }}
                    />
                  </span>
                  {!unlocked && (
                    <span className="ml-1.5 text-[11px] text-slate-400 dark:text-slate-500">
                      needs {missing.map(labelFor).join(", ")}
                    </span>
                  )}
                </div>
              );
            })}
          </div>
        </div>
      </div>
      <p className="text-center text-xs text-slate-400 dark:text-slate-500">
        Every grant is revocable in place, and revoking one instantly shows which features actually depended on it, no settings sub-menu required.
      </p>
    </div>
  );
}

"use client";

import { useState } from "react";
import { AnimatePresence, motion, useReducedMotion } from "framer-motion";
import {
  StackIcon as PhStack,
  CheckIcon as PhCheck,
  XCircleIcon as PhXCircle,
  PlusCircleIcon as PhPlusCircle,
} from "@phosphor-icons/react";

const RATE_PER_MONTH = 18;
const BILLING_CYCLE_DAYS = 30;
const DAYS_REMAINING = 16;
const PRORATED_RATE = (RATE_PER_MONTH / BILLING_CYCLE_DAYS) * DAYS_REMAINING;
const MAX_INSTANCES = 8;
const INITIAL_RUNNING = 5;

const INSTANCE_NAMES = Array.from({ length: MAX_INSTANCES }, (_, i) => `web-${i + 1}`);

function StackIcon() {
  return <PhStack size={15} aria-hidden />;
}
function CheckIcon() {
  return <PhCheck size={11} weight="bold" aria-hidden />;
}
function StopIcon() {
  return <PhXCircle size={13} weight="fill" aria-hidden />;
}
function StartIcon() {
  return <PhPlusCircle size={13} weight="fill" aria-hidden />;
}

function money(n: number) {
  const sign = n < 0 ? "-" : "";
  return `${sign}$${Math.abs(n).toFixed(2)}`;
}

interface CostPreviewProps {
  className?: string;
}

export function CostPreview({ className }: CostPreviewProps) {
  const [currentRunning, setCurrentRunning] = useState(INITIAL_RUNNING);
  const [target, setTarget] = useState(INITIAL_RUNNING);
  const shouldReduceMotion = useReducedMotion();

  const delta = target - currentRunning;
  const todayAmount = delta * PRORATED_RATE;
  const newMonthly = target * RATE_PER_MONTH;
  const currentMonthly = currentRunning * RATE_PER_MONTH;

  const visibleCount = Math.max(currentRunning, target);
  const visibleInstances = INSTANCE_NAMES.slice(0, visibleCount);
  const stoppingFrom = delta < 0 ? target : Infinity;
  const startingFrom = delta > 0 ? currentRunning : Infinity;

  const buttonLabel =
    delta === 0
      ? "Up to date"
      : delta > 0
        ? `Scale to ${target} instances (${money(todayAmount)} charged today)`
        : `Scale to ${target} instances (${money(Math.abs(todayAmount))} credited today)`;

  const fillPercent = ((target - 1) / (MAX_INSTANCES - 1)) * 100;
  const trackColor = delta > 0 ? "bg-emerald-500" : delta < 0 ? "bg-rose-500" : "bg-slate-400 dark:bg-slate-500";

  return (
    <div className={className}>
      <div className="w-full rounded-2xl border border-slate-200/70 bg-white/95 p-5 shadow-sm backdrop-blur-xl dark:border-white/10 dark:bg-neutral-950/80">
        <h3 className="flex items-center gap-1.5 text-sm font-semibold text-slate-900 dark:text-white">
          <StackIcon />
          Scale Compute
        </h3>
        <p className="mt-0.5 text-xs text-slate-400 dark:text-slate-500">
          {currentRunning} instances running at {money(RATE_PER_MONTH)}/mo each, {DAYS_REMAINING} days left in this billing cycle.
        </p>

        <div className="relative mt-4 flex h-5 items-center">
          <div className="relative h-1.5 w-full overflow-hidden rounded-full bg-slate-200 dark:bg-slate-700">
            <motion.div
              className={`absolute inset-y-0 left-0 rounded-full ${trackColor}`}
              animate={{ width: `${fillPercent}%` }}
              transition={shouldReduceMotion ? { duration: 0 } : { type: "spring", stiffness: 400, damping: 34 }}
            />
          </div>
          <input
            type="range"
            min={1}
            max={MAX_INSTANCES}
            value={target}
            onChange={(e) => setTarget(Number(e.target.value))}
            aria-label="Target instance count"
            aria-valuetext={`${target} instances`}
            className="peer absolute inset-0 h-5 w-full cursor-pointer opacity-0"
          />
          <motion.div
            className="pointer-events-none absolute top-1/2 h-4 w-4 rounded-full bg-white shadow-sm ring-1 ring-slate-300 dark:ring-slate-600"
            animate={{ left: `${fillPercent}%`, x: "-50%", y: "-50%" }}
            transition={shouldReduceMotion ? { duration: 0 } : { type: "spring", stiffness: 500, damping: 30 }}
          />
        </div>
        <div className="mt-1.5 flex items-center justify-between text-[11px] text-slate-400 dark:text-slate-500">
          <span>1 instance</span>
          <span className="font-medium text-slate-600 dark:text-slate-300">{target} instances</span>
          <span>{MAX_INSTANCES} instances</span>
        </div>

        <div className="mt-4 rounded-xl border border-slate-200/70 bg-slate-50/70 p-3.5 dark:border-white/10 dark:bg-white/[0.03]">
          <p className="text-[11px] font-medium uppercase tracking-wide text-slate-400 dark:text-slate-500">
            What changes if you apply this
          </p>
          <div className="mt-2 flex items-baseline justify-between text-xs">
            <span className="text-slate-500 dark:text-slate-400">Monthly cost</span>
            <span className="font-medium text-slate-800 dark:text-slate-100">
              {delta !== 0 && (
                <span className="mr-1.5 text-slate-400 line-through dark:text-slate-600">{money(currentMonthly)}</span>
              )}
              {money(newMonthly)}
            </span>
          </div>
          <div className="mt-1 flex items-baseline justify-between text-xs">
            <span className="text-slate-500 dark:text-slate-400">Charged today</span>
            <span
              className={`font-medium ${
                delta > 0
                  ? "text-slate-800 dark:text-slate-100"
                  : delta < 0
                    ? "text-emerald-700 dark:text-emerald-400"
                    : "text-slate-400 dark:text-slate-500"
              }`}
            >
              {delta === 0 ? "Nothing, no change" : delta < 0 ? `${money(Math.abs(todayAmount))} credit` : money(todayAmount)}
            </span>
          </div>
        </div>

        <div className="mt-3 space-y-1">
          <AnimatePresence initial={false}>
            {visibleInstances.map((name, i) => {
              const willStop = i >= stoppingFrom;
              const willStart = i >= startingFrom;
              return (
                <motion.div
                  key={name}
                  layout={!shouldReduceMotion}
                  initial={shouldReduceMotion ? { opacity: 0 } : { opacity: 0, height: 0 }}
                  animate={{ opacity: 1, height: "auto" }}
                  exit={shouldReduceMotion ? { opacity: 0 } : { opacity: 0, height: 0 }}
                  transition={{ duration: 0.25, ease: [0.22, 1, 0.36, 1] }}
                  className="overflow-hidden"
                >
                  <div
                    className={`flex items-center justify-between gap-2 rounded-lg px-2.5 py-1.5 text-xs transition-colors ${
                      willStop
                        ? "bg-rose-500/5 text-rose-700 dark:text-rose-300"
                        : willStart
                          ? "bg-emerald-500/5 text-emerald-700 dark:text-emerald-300"
                          : "text-slate-600 dark:text-slate-300"
                    }`}
                  >
                    <span className="font-mono">{name}</span>
                    <span className="flex items-center gap-1 text-[11px]">
                      {willStop ? (
                        <>
                          <StopIcon />
                          Will stop, in-flight requests dropped
                        </>
                      ) : willStart ? (
                        <>
                          <StartIcon />
                          Will start
                        </>
                      ) : (
                        <>
                          <CheckIcon />
                          Running
                        </>
                      )}
                    </span>
                  </div>
                </motion.div>
              );
            })}
          </AnimatePresence>
        </div>

        <button
          type="button"
          disabled={delta === 0}
          onClick={() => setCurrentRunning(target)}
          className="mt-4 w-full rounded-lg bg-slate-900 px-3 py-2 text-xs font-medium text-white transition-colors hover:bg-slate-700 focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-slate-500 disabled:cursor-not-allowed disabled:bg-slate-200 disabled:text-slate-400 dark:bg-white dark:text-slate-900 dark:hover:bg-slate-200 dark:disabled:bg-white/10 dark:disabled:text-slate-600"
        >
          {buttonLabel}
        </button>
      </div>
      <p className="text-center text-xs text-slate-400 dark:text-slate-500">
        The button states the real consequence itself, a prorated charge or credit today, not a hidden line in fine print, while the list below names exactly which instances would stop or start.
      </p>
    </div>
  );
}

"use client";

import { useState } from "react";
import { motion, useReducedMotion } from "framer-motion";
import {
  PulseIcon as PhPulse,
  ArrowClockwiseIcon as PhRetry,
} from "@phosphor-icons/react";

interface JobType {
  id: string;
  name: string;
  cadence: string;
}

const JOB_TYPES: JobType[] = [
  { id: "autosave", name: "Autosave", cadence: "every 30 seconds" },
  { id: "sync", name: "Cloud sync", cadence: "every 5 minutes" },
  { id: "backup", name: "Nightly backup", cadence: "once a day" },
];

const INITIAL_HISTORY: Record<string, boolean[]> = {
  autosave: [true, true, true, false, false, false],
  sync: [true, true, true, true, true, true],
  backup: [true, false, true, true, true, true],
};

function activeFailCount(history: boolean[]) {
  let n = 0;
  for (let i = history.length - 1; i >= 0 && !history[i]; i--) n++;
  return n;
}

function PulseIcon() {
  return <PhPulse size={15} aria-hidden />;
}
function RetryIcon() {
  return <PhRetry size={12} aria-hidden />;
}

function Sparkline({ history }: { history: boolean[] }) {
  return (
    <div className="flex items-center gap-1">
      {history.map((ok, i) => (
        <span
          key={i}
          aria-hidden
          className={`h-1.5 w-1.5 rounded-full ${ok ? "bg-emerald-400 dark:bg-emerald-500" : "bg-amber-400 dark:bg-amber-500"}`}
        />
      ))}
    </div>
  );
}

interface SilentFailureSurfaceProps {
  className?: string;
}

export function SilentFailureSurface({ className }: SilentFailureSurfaceProps) {
  const [histories, setHistories] = useState(INITIAL_HISTORY);
  const [retrying, setRetrying] = useState<Record<string, boolean>>({});
  const shouldReduceMotion = useReducedMotion();

  const retry = (id: string) => {
    setRetrying((prev) => ({ ...prev, [id]: true }));
    setTimeout(
      () => {
        setHistories((prev) => ({ ...prev, [id]: [...prev[id].slice(1), true] }));
        setRetrying((prev) => ({ ...prev, [id]: false }));
      },
      shouldReduceMotion ? 0 : 900,
    );
  };

  const totalActive = JOB_TYPES.reduce((sum, j) => sum + activeFailCount(histories[j.id]), 0);

  return (
    <div className={className}>
      <div className="w-full rounded-2xl border border-slate-200/70 bg-white/95 p-5 shadow-sm backdrop-blur-xl dark:border-white/10 dark:bg-neutral-950/80">
        <div className="flex items-center justify-between gap-3">
          <h3 className="flex items-center gap-1.5 text-sm font-semibold text-slate-900 dark:text-white">
            <PulseIcon />
            Background activity
          </h3>
          <span
            className={`inline-flex shrink-0 items-center rounded-full border px-2 py-0.5 text-[11px] font-medium ${
              totalActive > 0
                ? "border-amber-500/25 bg-amber-500/10 text-amber-600 dark:text-amber-400"
                : "border-slate-200/70 text-slate-400 dark:border-white/10 dark:text-slate-500"
            }`}
          >
            {totalActive > 0 ? `${totalActive} need a retry` : "All quiet"}
          </span>
        </div>

        <div className="mt-3 space-y-1">
          {JOB_TYPES.map((job) => {
            const history = histories[job.id];
            const failCount = activeFailCount(history);
            const isRetrying = retrying[job.id] ?? false;
            const hadEarlierFailure = !failCount && history.some((h) => !h);

            let status: string;
            if (isRetrying) status = "Retrying now";
            else if (failCount > 1) status = `${failCount} failed silently, last one a moment ago`;
            else if (failCount === 1) status = "Failed silently, last one a moment ago";
            else if (hadEarlierFailure) status = "Recovered on its own after 1 failure earlier";
            else status = "All caught up";

            return (
              <div key={job.id} className="flex items-center justify-between gap-3 rounded-lg p-2">
                <div className="min-w-0 flex-1">
                  <div className="flex items-center gap-2">
                    <span className="text-xs font-medium text-slate-800 dark:text-slate-100">{job.name}</span>
                    <span className="text-[11px] text-slate-300 dark:text-slate-600">{job.cadence}</span>
                    <Sparkline history={history} />
                  </div>
                  <p
                    className={`mt-0.5 text-[11px] ${
                      failCount > 0 ? "text-amber-600 dark:text-amber-400" : "text-slate-400 dark:text-slate-500"
                    }`}
                  >
                    {status}
                  </p>
                </div>
                {failCount > 0 && (
                  <motion.button
                    type="button"
                    disabled={isRetrying}
                    onClick={() => retry(job.id)}
                    whileTap={shouldReduceMotion || isRetrying ? undefined : { scale: 0.93 }}
                    aria-label={`Retry ${job.name}`}
                    className="flex shrink-0 items-center gap-1 rounded-md border border-amber-500/25 bg-amber-500/10 px-2 py-1 text-[11px] font-medium text-amber-700 transition-colors hover:bg-amber-500/20 focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-amber-600 disabled:opacity-60 dark:text-amber-400"
                  >
                    <motion.span
                      className="flex"
                      animate={isRetrying && !shouldReduceMotion ? { rotate: 360 } : { rotate: 0 }}
                      transition={isRetrying && !shouldReduceMotion ? { duration: 0.7, repeat: Infinity, ease: "linear" } : { duration: 0 }}
                    >
                      <RetryIcon />
                    </motion.span>
                    Retry
                  </motion.button>
                )}
              </div>
            );
          })}
        </div>
      </div>
      <p className="text-center text-xs text-slate-400 dark:text-slate-500">
        Repeated failures of the same job collapse into one calm amber line instead of separate alerts, and nothing here ever turns red, however many times it fails.
      </p>
    </div>
  );
}

