"use client";

import { useEffect, useRef, useState } from "react";
import { AnimatePresence, motion, useReducedMotion } from "framer-motion";
import {
  TrashIcon as PhTrash,
  ArrowCounterClockwiseIcon as PhUndo,
  ArchiveIcon as PhArchive,
  LockSimpleIcon as PhLock,
  CheckIcon as PhCheck,
} from "@phosphor-icons/react";

type Phase = "idle" | "justDeleted" | "held" | "gone" | "restored";

const DURATIONS: Partial<Record<Phase, number>> = {
  justDeleted: 4000,
  held: 6000,
  restored: 1400,
};

const ANNOUNCE: Record<Phase, string> = {
  idle: "",
  justDeleted: "Deleted. Undo is available for a few seconds.",
  held: "Moved to Recently Deleted. Still restorable, but not for long.",
  gone: "Permanently deleted. This can no longer be recovered.",
  restored: "Restored.",
};

function TrashIcon() {
  return <PhTrash size={15} aria-hidden />;
}

function UndoIcon() {
  return <PhUndo size={13} aria-hidden />;
}

function ArchiveIcon() {
  return <PhArchive size={15} aria-hidden />;
}

function LockIcon() {
  return <PhLock size={15} aria-hidden />;
}

function CheckIcon() {
  return <PhCheck size={13} weight="bold" aria-hidden />;
}

interface UndoableActionProps {
  title?: string;
  subtitle?: string;
  undoWindowMs?: number;
  holdWindowMs?: number;
  onPermanentlyDeleted?: () => void;
  className?: string;
}

export function UndoableAction({
  title = "Q3 roadmap notes",
  subtitle = "Edited 2 hours ago",
  undoWindowMs = DURATIONS.justDeleted!,
  holdWindowMs = DURATIONS.held!,
  onPermanentlyDeleted,
  className,
}: UndoableActionProps) {
  const [phase, setPhase] = useState<Phase>("idle");
  const [remaining, setRemaining] = useState(0);
  const [restoredFrom, setRestoredFrom] = useState<"justDeleted" | "held" | null>(null);
  const shouldReduceMotion = useReducedMotion();
  const rafRef = useRef<number | null>(null);
  const timeoutRef = useRef<ReturnType<typeof setTimeout> | null>(null);
  const onPermanentlyDeletedRef = useRef(onPermanentlyDeleted);
  onPermanentlyDeletedRef.current = onPermanentlyDeleted;

  const windowFor: Partial<Record<Phase, number>> = {
    justDeleted: undoWindowMs,
    held: holdWindowMs,
    restored: DURATIONS.restored!,
  };

  useEffect(() => {
    const duration = windowFor[phase];
    if (!duration) {
      setRemaining(0);
      return;
    }
    const start = performance.now();
    setRemaining(duration);

    const tick = () => {
      const left = Math.max(0, duration - (performance.now() - start));
      setRemaining(left);
      if (left > 0) rafRef.current = requestAnimationFrame(tick);
    };
    rafRef.current = requestAnimationFrame(tick);

    timeoutRef.current = setTimeout(() => {
      setPhase((current) => {
        if (current === "justDeleted") return "held";
        if (current === "held") {
          onPermanentlyDeletedRef.current?.();
          return "gone";
        }
        if (current === "restored") return "idle";
        return current;
      });
    }, duration);

    return () => {
      if (rafRef.current) cancelAnimationFrame(rafRef.current);
      if (timeoutRef.current) clearTimeout(timeoutRef.current);
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [phase]);

  const seconds = (remaining / 1000).toFixed(1);
  const progress = phase === "justDeleted" ? remaining / undoWindowMs : phase === "held" ? remaining / holdWindowMs : 0;

  const fade = shouldReduceMotion
    ? { initial: { opacity: 0 }, animate: { opacity: 1 }, exit: { opacity: 0 } }
    : { initial: { opacity: 0, y: -6 }, animate: { opacity: 1, y: 0 }, exit: { opacity: 0, y: 6 } };

  return (
    <div className={className}>
      <div
        role="group"
        aria-label={title}
        className="relative w-full overflow-hidden rounded-2xl border border-slate-200/70 bg-white/95 shadow-sm backdrop-blur-xl transition-[filter,opacity] duration-500 dark:border-white/10 dark:bg-neutral-950/80"
      >
        <span className="sr-only" role="status" aria-live="polite">
          {ANNOUNCE[phase]}
        </span>

        <AnimatePresence mode="wait" initial={false}>
          {phase === "idle" && (
            <motion.div key="idle" {...fade} transition={{ duration: 0.22, ease: [0.22, 1, 0.36, 1] }} className="flex items-center gap-3 p-4">
              <span className="flex h-9 w-9 shrink-0 items-center justify-center rounded-full bg-slate-500/10 text-slate-500 dark:bg-white/10 dark:text-slate-300">
                <ArchiveIcon />
              </span>
              <div className="min-w-0 flex-1">
                <p className="truncate text-sm font-medium text-slate-900 dark:text-white">{title}</p>
                <p className="text-xs text-slate-400 dark:text-slate-500">{subtitle}</p>
              </div>
              <button
                type="button"
                onClick={() => setPhase("justDeleted")}
                aria-label={`Delete ${title}`}
                className="flex h-8 w-8 shrink-0 items-center justify-center rounded-lg text-slate-400 transition-colors hover:bg-rose-500/10 hover:text-rose-600 focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-rose-500 dark:hover:text-rose-400"
              >
                <TrashIcon />
              </button>
            </motion.div>
          )}

          {phase === "justDeleted" && (
            <motion.div key="justDeleted" {...fade} transition={{ duration: 0.22, ease: [0.22, 1, 0.36, 1] }} className="p-4">
              <div className="flex items-center gap-3">
                <span className="flex h-9 w-9 shrink-0 items-center justify-center rounded-full bg-rose-500/15 text-rose-600 dark:text-rose-400">
                  <TrashIcon />
                </span>
                <div className="min-w-0 flex-1">
                  <p className="truncate text-sm font-medium text-rose-700 dark:text-rose-300">Deleted &ldquo;{title}&rdquo;</p>
                  <p className="text-xs tabular-nums text-rose-500/80 dark:text-rose-400/70">Undo available for {seconds}s</p>
                </div>
                <button
                  type="button"
                  onClick={() => {
                    setRestoredFrom("justDeleted");
                    setPhase("restored");
                  }}
                  className="inline-flex shrink-0 items-center gap-1.5 rounded-lg bg-rose-600 px-3 py-1.5 text-sm font-medium text-white transition-colors hover:bg-rose-500 focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-rose-600"
                >
                  <UndoIcon />
                  Undo
                </button>
              </div>
              <div className="mt-3 h-1 overflow-hidden rounded-full bg-rose-500/15">
                <motion.div
                  className="h-full rounded-full bg-rose-500"
                  style={{ transformOrigin: "left" }}
                  animate={{ scaleX: progress }}
                  transition={{ duration: 0 }}
                />
              </div>
            </motion.div>
          )}

          {phase === "held" && (
            <motion.div key="held" {...fade} transition={{ duration: 0.22, ease: [0.22, 1, 0.36, 1] }} className="border-t border-dashed border-amber-400/40 p-4">
              <div className="flex items-center gap-3">
                <span className="flex h-9 w-9 shrink-0 items-center justify-center rounded-full bg-amber-500/15 text-amber-600 dark:text-amber-400">
                  <ArchiveIcon />
                </span>
                <div className="min-w-0 flex-1">
                  <p className="truncate text-sm font-medium text-amber-700 dark:text-amber-300">In Recently Deleted</p>
                  <p className="text-xs tabular-nums text-amber-600/70 dark:text-amber-400/60">Restorable for {seconds}s more</p>
                </div>
                <button
                  type="button"
                  onClick={() => {
                    setRestoredFrom("held");
                    setPhase("restored");
                  }}
                  className="inline-flex shrink-0 items-center gap-1.5 rounded-lg border border-amber-400/50 px-3 py-1.5 text-sm font-medium text-amber-700 transition-colors hover:bg-amber-500/10 focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-amber-500 dark:text-amber-300"
                >
                  <UndoIcon />
                  Restore
                </button>
              </div>
              <div className="mt-3 h-1 overflow-hidden rounded-full bg-amber-500/15">
                <motion.div
                  className="h-full rounded-full bg-amber-400"
                  style={{ transformOrigin: "left" }}
                  animate={{ scaleX: progress }}
                  transition={{ duration: 0 }}
                />
              </div>
            </motion.div>
          )}

          {phase === "gone" && (
            <motion.div key="gone" {...fade} transition={{ duration: 0.3, ease: [0.22, 1, 0.36, 1] }} className="flex items-center gap-3 p-4 grayscale">
              <span className="flex h-9 w-9 shrink-0 items-center justify-center rounded-full bg-slate-500/10 text-slate-400 dark:bg-white/5 dark:text-slate-500">
                <LockIcon />
              </span>
              <div className="min-w-0 flex-1">
                <p className="truncate text-sm font-medium text-slate-500 dark:text-slate-400">Permanently deleted</p>
                <p className="text-xs text-slate-400 dark:text-slate-500">This can no longer be recovered.</p>
              </div>
            </motion.div>
          )}

          {phase === "restored" && (
            <motion.div key="restored" {...fade} transition={{ duration: 0.25, ease: [0.22, 1, 0.36, 1] }} className="flex items-center gap-3 p-4">
              <span className="relative flex h-9 w-9 shrink-0 items-center justify-center rounded-full bg-emerald-500/15 text-emerald-600 dark:text-emerald-400">
                {!shouldReduceMotion && (
                  <motion.span
                    aria-hidden
                    className="absolute rounded-full border-2 border-emerald-400/60"
                    style={{ inset: -3 }}
                    initial={{ scale: 0.7, opacity: 0.9 }}
                    animate={{ scale: 1.7, opacity: 0 }}
                    transition={{ duration: 0.6, ease: [0.16, 1, 0.3, 1] }}
                  />
                )}
                <CheckIcon />
              </span>
              <div className="min-w-0 flex-1">
                <p className="truncate text-sm font-medium text-emerald-700 dark:text-emerald-300">
                  {restoredFrom === "held" ? "Restored from Recently Deleted" : "Restored"}
                </p>
                <p className="truncate text-xs text-slate-400 dark:text-slate-500">{title} is back.</p>
              </div>
            </motion.div>
          )}
        </AnimatePresence>
      </div>
    </div>
  );
}

"use client";

import { useEffect, useRef, useState } from "react";
import { AnimatePresence, motion, useReducedMotion } from "framer-motion";
import { RocketLaunchIcon as PhRocket, ArrowCounterClockwiseIcon as PhReset } from "@phosphor-icons/react";

interface WaitingStep {
  label: string;
  typicalMs: number;
  actualMs: number;
}

const STEPS: WaitingStep[] = [
  { label: "Uploading files", typicalMs: 1400, actualMs: 1300 },
  { label: "Building assets", typicalMs: 2200, actualMs: 3600 },
  { label: "Running checks", typicalMs: 1100, actualMs: 1000 },
  { label: "Going live", typicalMs: 900, actualMs: 850 },
];

const ACTUAL_DURATIONS = STEPS.map((s) => s.actualMs);
const REDUCED_DURATIONS = STEPS.map(() => 80);
const OVERRUN_BUFFER_MS = 500;

function RocketIcon() {
  return <PhRocket size={13} weight="fill" aria-hidden />;
}

function ResetIcon() {
  return <PhReset size={13} aria-hidden />;
}

function CheckIcon({ size = 11 }: { size?: number }) {
  return (
    <svg viewBox="0 0 24 24" width={size} height={size} fill="none" stroke="currentColor" strokeWidth="3" strokeLinecap="round" strokeLinejoin="round" aria-hidden>
      <motion.path d="M20 6 9 17l-5-5" initial={{ pathLength: 0 }} animate={{ pathLength: 1 }} transition={{ duration: 0.3, ease: [0.22, 1, 0.36, 1] }} />
    </svg>
  );
}

function formatElapsed(ms: number) {
  return `${(ms / 1000).toFixed(1)}s`;
}

function StepIndicator({ status, shouldReduceMotion }: { status: "pending" | "active" | "done"; shouldReduceMotion: boolean | null }) {
  if (status === "done") {
    return (
      <span className="relative flex h-6 w-6 shrink-0 items-center justify-center rounded-full bg-emerald-600 text-white">
        <CheckIcon />
      </span>
    );
  }
  if (status === "active") {
    return (
      <span className="relative flex h-6 w-6 shrink-0 items-center justify-center rounded-full bg-emerald-500/15">
        <motion.span
          aria-hidden
          className="absolute inset-0 rounded-full border-2 border-emerald-400/25 border-t-emerald-500"
          animate={shouldReduceMotion ? { rotate: 0 } : { rotate: 360 }}
          transition={shouldReduceMotion ? { duration: 0 } : { duration: 0.8, repeat: Infinity, ease: "linear" }}
        />
        <span className="h-1.5 w-1.5 rounded-full bg-emerald-500" />
      </span>
    );
  }
  return <span className="h-6 w-6 shrink-0 rounded-full border-2 border-slate-200 dark:border-slate-700" />;
}

function WaitingStateRun({ onReplay }: { onReplay: () => void }) {
  const [currentIndex, setCurrentIndex] = useState(0);
  const [finished, setFinished] = useState(false);
  const [elapsedMs, setElapsedMs] = useState(0);
  const [overrunning, setOverrunning] = useState(false);
  const startRef = useRef(0);
  const shouldReduceMotion = useReducedMotion();

  useEffect(() => {
    startRef.current = performance.now();
    const durations = shouldReduceMotion ? REDUCED_DURATIONS : ACTUAL_DURATIONS;
    let cumulative = 0;
    let cancelled = false;
    const timeouts: ReturnType<typeof setTimeout>[] = [];

    durations.forEach((d, i) => {
      cumulative += d;
      timeouts.push(
        setTimeout(() => {
          if (cancelled) return;
          if (i === durations.length - 1) {
            setFinished(true);
          } else {
            setCurrentIndex(i + 1);
          }
        }, cumulative)
      );
    });

    return () => {
      cancelled = true;
      timeouts.forEach(clearTimeout);
    };
  }, [shouldReduceMotion]);

  useEffect(() => {
    if (finished) return;
    let raf: number;
    const durations = shouldReduceMotion ? REDUCED_DURATIONS : ACTUAL_DURATIONS;
    const stepStart = durations.slice(0, currentIndex).reduce((sum, d) => sum + d, 0);
    const typical = shouldReduceMotion ? REDUCED_DURATIONS[currentIndex] : STEPS[currentIndex].typicalMs;
    const buffer = shouldReduceMotion ? 0 : OVERRUN_BUFFER_MS;

    const tick = () => {
      const elapsed = performance.now() - startRef.current;
      setElapsedMs(elapsed);
      setOverrunning(elapsed - stepStart > typical + buffer);
      raf = requestAnimationFrame(tick);
    };
    raf = requestAnimationFrame(tick);
    return () => cancelAnimationFrame(raf);
  }, [finished, currentIndex, shouldReduceMotion]);

  const statusOf = (i: number): "pending" | "active" | "done" => (i < currentIndex || (i === currentIndex && finished) ? "done" : i === currentIndex ? "active" : "pending");

  return (
    <div className="relative w-full max-w-md">
      <div className="relative rounded-2xl border border-slate-200/70 bg-white/95 p-5 shadow-sm backdrop-blur-xl dark:border-white/10 dark:bg-neutral-950/80">
        <div className="flex items-center gap-2.5">
          <span
            className={`relative flex h-7 w-7 shrink-0 items-center justify-center rounded-full transition-colors duration-300 ${
              finished ? "bg-emerald-600 text-white" : "bg-emerald-500/15 text-emerald-600 dark:text-emerald-400"
            }`}
          >
            {finished && !shouldReduceMotion && (
              <motion.span
                aria-hidden
                className="absolute inset-0 rounded-full border-2 border-emerald-400/60"
                initial={{ scale: 0.7, opacity: 0.9 }}
                animate={{ scale: 1.7, opacity: 0 }}
                transition={{ duration: 0.6, ease: [0.16, 1, 0.3, 1] }}
              />
            )}
            {finished ? (
              <CheckIcon size={13} />
            ) : (
              <motion.span animate={shouldReduceMotion ? { y: 0 } : { y: [0, -1.5, 0] }} transition={{ duration: 1.6, repeat: Infinity, ease: "easeInOut" }}>
                <RocketIcon />
              </motion.span>
            )}
          </span>
          <h3 className="flex-1 text-sm font-semibold text-slate-900 dark:text-white">{finished ? `Live in ${formatElapsed(elapsedMs)}` : "Deploying your site"}</h3>
          {!finished && <span className="shrink-0 tabular-nums text-xs text-slate-400 dark:text-slate-500">{formatElapsed(elapsedMs)}</span>}
          {finished && (
            <motion.button
              type="button"
              onClick={onReplay}
              aria-label="Deploy again"
              whileTap={shouldReduceMotion ? undefined : { scale: 0.9 }}
              className="inline-flex h-8 w-8 shrink-0 items-center justify-center rounded-lg text-slate-400 transition-colors hover:bg-black/5 hover:text-slate-600 focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-emerald-600 dark:hover:bg-white/10 dark:hover:text-slate-300"
            >
              <ResetIcon />
            </motion.button>
          )}
        </div>

        <div className="mt-4">
          {STEPS.map((step, i) => {
            const status = statusOf(i);
            return (
              <div key={step.label} className="flex gap-3">
                <div className="flex flex-col items-center">
                  <StepIndicator status={status} shouldReduceMotion={shouldReduceMotion} />
                  {i < STEPS.length - 1 && (
                    <span className="relative my-1 w-px flex-1 bg-slate-200 dark:bg-slate-700">
                      <motion.span
                        aria-hidden
                        className="absolute inset-0 origin-top bg-emerald-500"
                        initial={{ scaleY: 0 }}
                        animate={{ scaleY: status === "done" ? 1 : 0 }}
                        transition={shouldReduceMotion ? { duration: 0 } : { duration: 0.4, ease: [0.22, 1, 0.36, 1] }}
                      />
                    </span>
                  )}
                </div>
                <div className="flex-1 pb-4 last:pb-0">
                  <div className="flex items-center justify-between gap-2 pt-0.5">
                    <p className={`text-sm font-medium transition-colors ${status === "pending" ? "text-slate-400 dark:text-slate-600" : "text-slate-800 dark:text-slate-100"}`}>
                      {step.label}
                    </p>
                    {status === "done" && <span className="shrink-0 tabular-nums text-xs text-slate-400 dark:text-slate-500">{formatElapsed(step.actualMs)}</span>}
                  </div>
                  <AnimatePresence>
                    {status === "active" && overrunning && (
                      <motion.p
                        initial={shouldReduceMotion ? { opacity: 0 } : { opacity: 0, y: -4 }}
                        animate={{ opacity: 1, y: 0 }}
                        exit={shouldReduceMotion ? { opacity: 0 } : { opacity: 0, y: -4 }}
                        transition={{ duration: 0.3, ease: [0.22, 1, 0.36, 1] }}
                        className="mt-1 flex items-center gap-1.5 text-xs text-amber-600 dark:text-amber-400"
                      >
                        <motion.span
                          aria-hidden
                          className="h-1.5 w-1.5 shrink-0 rounded-full bg-amber-500"
                          animate={shouldReduceMotion ? { opacity: 0.7 } : { opacity: [0.4, 1, 0.4] }}
                          transition={shouldReduceMotion ? { duration: 0.2 } : { duration: 1.4, repeat: Infinity, ease: "easeInOut" }}
                        />
                        Taking a little longer than usual, still going.
                      </motion.p>
                    )}
                  </AnimatePresence>
                </div>
              </div>
            );
          })}
        </div>

        <span className="sr-only" role="status" aria-live="polite">
          {finished
            ? `Deployed. Total time ${formatElapsed(elapsedMs)}.`
            : overrunning
              ? `${STEPS[currentIndex].label} is taking longer than usual, still in progress.`
              : `Step ${currentIndex + 1} of ${STEPS.length}: ${STEPS[currentIndex].label}.`}
        </span>
      </div>
    </div>
  );
}

"use client";

import { useEffect, useRef, useState } from "react";
import { AnimatePresence, motion, useReducedMotion } from "framer-motion";
import {
  MicrophoneIcon as PhMic,
  MicrophoneSlashIcon as PhMicSlash,
  VideoCameraIcon as PhCamera,
  VideoCameraSlashIcon as PhCameraSlash,
  KeyboardIcon as PhKeyboard,
  CheckIcon as PhCheck,
  ArrowCounterClockwiseIcon as PhReset,
} from "@phosphor-icons/react";

type Capability = "microphone" | "camera";
type Status = "idle" | "asking" | "granted" | "fallback";
type FallbackReason = "declined" | "denied" | "unsupported";

interface CapabilityConfig {
  title: string;
  subtitle: string;
  askCopy: string;
  allowLabel: string;
  activeLabel: string;
  pausedLabel: string;
  constraints: MediaStreamConstraints;
  fallback: Record<FallbackReason, string>;
}

const AVATAR_SWATCHES = [
  { id: "slate", label: "Slate", className: "bg-slate-400 dark:bg-slate-500" },
  { id: "emerald", label: "Emerald", className: "bg-emerald-500" },
  { id: "amber", label: "Amber", className: "bg-amber-500" },
  { id: "rose", label: "Rose", className: "bg-rose-500" },
] as const;

const CAPABILITY: Record<Capability, CapabilityConfig> = {
  microphone: {
    title: "Voice notes",
    subtitle: "Speak your notes instead of typing.",
    askCopy: "To transcribe your voice notes, this needs your microphone. You can still type instead, any time.",
    allowLabel: "Allow microphone",
    activeLabel: "Listening for your note.",
    pausedLabel: "Microphone paused.",
    constraints: { audio: true },
    fallback: {
      declined: "You can turn voice notes on anytime.",
      denied: "Microphone access was blocked. Allow it from your browser's site settings, or keep typing.",
      unsupported: "Voice notes aren't supported in this browser. Typing still works great.",
    },
  },
  camera: {
    title: "Video avatar",
    subtitle: "Use a live camera preview instead of a color avatar.",
    askCopy: "To set a live video avatar, this needs your camera. You can still pick a color avatar instead, any time.",
    allowLabel: "Allow camera",
    activeLabel: "Camera is on.",
    pausedLabel: "Camera paused.",
    constraints: { video: true },
    fallback: {
      declined: "You can turn the camera on anytime.",
      denied: "Camera access was blocked. Allow it from your browser's site settings, or keep your color avatar.",
      unsupported: "Camera preview isn't supported in this browser. Your color avatar still works great.",
    },
  },
};

function MicIcon() {
  return <PhMic size={15} aria-hidden />;
}
function MicSlashIcon() {
  return <PhMicSlash size={15} aria-hidden />;
}
function CameraIcon() {
  return <PhCamera size={15} aria-hidden />;
}
function CameraSlashIcon() {
  return <PhCameraSlash size={15} aria-hidden />;
}
function KeyboardIcon() {
  return <PhKeyboard size={14} aria-hidden />;
}
function CheckIcon() {
  return <PhCheck size={11} weight="bold" aria-hidden />;
}
function ResetIcon() {
  return <PhReset size={13} aria-hidden />;
}

interface PermissionNegotiatorProps {
  capability?: Capability;
  className?: string;
}

export function PermissionNegotiator({ capability = "microphone", className }: PermissionNegotiatorProps) {
  const [status, setStatus] = useState<Status>("idle");
  const [mediaOn, setMediaOn] = useState(false);
  const [requesting, setRequesting] = useState(false);
  const [fallbackReason, setFallbackReason] = useState<FallbackReason>("declined");
  const [note, setNote] = useState("");
  const [avatarColor, setAvatarColor] = useState<(typeof AVATAR_SWATCHES)[number]["id"] | null>(null);
  const streamRef = useRef<MediaStream | null>(null);
  const textareaRef = useRef<HTMLTextAreaElement>(null);
  const videoRef = useRef<HTMLVideoElement>(null);
  const shouldReduceMotion = useReducedMotion();
  const config = CAPABILITY[capability];
  const isCamera = capability === "camera";

  useEffect(() => {
    return () => {
      streamRef.current?.getTracks().forEach((t) => t.stop());
    };
  }, []);

  useEffect(() => {
    if (status === "fallback" && !isCamera) textareaRef.current?.focus();
  }, [status, isCamera]);

  useEffect(() => {
    if (isCamera && videoRef.current) {
      videoRef.current.srcObject = status === "granted" && mediaOn ? streamRef.current : null;
    }
  }, [isCamera, status, mediaOn]);

  const requestMedia = async () => {
    if (!navigator.mediaDevices?.getUserMedia) {
      setStatus("fallback");
      setFallbackReason("unsupported");
      return;
    }
    setRequesting(true);
    try {
      const stream = await navigator.mediaDevices.getUserMedia(config.constraints);
      streamRef.current = stream;
      setStatus("granted");
      setMediaOn(true);
    } catch (err) {
      const denied = err instanceof DOMException && err.name === "NotAllowedError";
      setStatus("fallback");
      setFallbackReason(denied ? "denied" : "unsupported");
    } finally {
      setRequesting(false);
    }
  };

  const decline = () => {
    setStatus("fallback");
    setFallbackReason("declined");
  };

  const toggleMedia = async () => {
    if (mediaOn) {
      streamRef.current?.getTracks().forEach((t) => t.stop());
      streamRef.current = null;
      setMediaOn(false);
      return;
    }
    try {
      const stream = await navigator.mediaDevices.getUserMedia(config.constraints);
      streamRef.current = stream;
      setMediaOn(true);
    } catch {
      setStatus("fallback");
      setFallbackReason("denied");
    }
  };

  const iconKey = status === "granted" && !mediaOn ? "off" : "on";
  const OnIcon = isCamera ? CameraIcon : MicIcon;
  const OffIcon = isCamera ? CameraSlashIcon : MicSlashIcon;
  const fade = shouldReduceMotion
    ? { initial: { opacity: 0 }, animate: { opacity: 1 }, exit: { opacity: 0 } }
    : { initial: { height: 0, opacity: 0 }, animate: { height: "auto", opacity: 1 }, exit: { height: 0, opacity: 0 } };

  return (
    <div className={className}>
      <div className="w-full overflow-hidden rounded-2xl border border-slate-200/70 bg-white/95 shadow-sm backdrop-blur-xl dark:border-white/10 dark:bg-neutral-950/80">
        <div className="flex items-center gap-3 p-5">
          <span className="relative flex h-9 w-9 shrink-0 items-center justify-center rounded-full bg-emerald-500/15 text-emerald-600 dark:text-emerald-400">
            {status === "granted" && mediaOn && !isCamera && !shouldReduceMotion && (
              <motion.span
                aria-hidden
                className="absolute inset-[-4px] rounded-full border border-emerald-400/60"
                animate={{ scale: [1, 1.35], opacity: [0.6, 0] }}
                transition={{ duration: 1.1, repeat: Infinity, ease: "easeOut" }}
              />
            )}
            <AnimatePresence mode="wait" initial={false}>
              <motion.span
                key={iconKey}
                initial={shouldReduceMotion ? { opacity: 0 } : { opacity: 0, scale: 0.6 }}
                animate={{ opacity: 1, scale: 1 }}
                exit={shouldReduceMotion ? { opacity: 0 } : { opacity: 0, scale: 0.6 }}
                transition={{ duration: 0.2, ease: [0.22, 1, 0.36, 1] }}
              >
                {iconKey === "off" ? <OffIcon /> : <OnIcon />}
              </motion.span>
            </AnimatePresence>
          </span>
          <div className="min-w-0 flex-1">
            <p className="text-sm font-medium text-slate-900 dark:text-white">{config.title}</p>
            <p className="text-xs text-slate-400 dark:text-slate-500">
              {status === "granted" ? (mediaOn ? config.activeLabel : config.pausedLabel) : config.subtitle}
            </p>
          </div>
          {status === "idle" && (
            <motion.button
              type="button"
              onClick={() => setStatus("asking")}
              whileHover={shouldReduceMotion ? undefined : { y: -1 }}
              whileTap={shouldReduceMotion ? undefined : { scale: 0.95 }}
              className="inline-flex shrink-0 items-center rounded-lg bg-emerald-600 px-3 py-1.5 text-sm font-medium text-white transition-colors hover:bg-emerald-500 focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-emerald-600"
            >
              Try it
            </motion.button>
          )}
          {status === "granted" && (
            <motion.button
              type="button"
              onClick={toggleMedia}
              aria-pressed={mediaOn}
              whileHover={shouldReduceMotion ? undefined : { y: -1 }}
              whileTap={shouldReduceMotion ? undefined : { scale: 0.95 }}
              className={`inline-flex shrink-0 items-center rounded-lg px-3 py-1.5 text-sm font-medium transition-colors focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-emerald-600 ${
                mediaOn
                  ? "bg-amber-500/10 text-amber-700 hover:bg-amber-500/15 dark:text-amber-400"
                  : "border border-slate-200/70 text-slate-600 hover:bg-black/5 dark:border-white/10 dark:text-slate-300 dark:hover:bg-white/10"
              }`}
            >
              {mediaOn ? "Stop" : "Resume"}
            </motion.button>
          )}
        </div>

        <AnimatePresence initial={false}>
          {isCamera && status === "granted" && mediaOn && (
            <motion.div
              {...fade}
              transition={shouldReduceMotion ? { duration: 0.15 } : { height: { duration: 0.35, ease: [0.22, 1, 0.36, 1] }, opacity: { duration: 0.25 } }}
              className="overflow-hidden border-t border-slate-200/70 dark:border-white/10"
            >
              <div className="p-4">
                <video
                  ref={videoRef}
                  autoPlay
                  muted
                  playsInline
                  className="aspect-video w-full scale-x-[-1] rounded-lg bg-slate-900 object-cover"
                />
              </div>
            </motion.div>
          )}
        </AnimatePresence>

        <AnimatePresence initial={false}>
          {status === "asking" && (
            <motion.div
              {...fade}
              transition={shouldReduceMotion ? { duration: 0.15 } : { height: { duration: 0.35, ease: [0.22, 1, 0.36, 1] }, opacity: { duration: 0.25 } }}
              className="overflow-hidden border-t border-slate-200/70 dark:border-white/10"
            >
              <div className="p-4">
                <p className="text-xs leading-relaxed text-slate-500 dark:text-slate-400">{config.askCopy}</p>
                <div className="mt-3 flex items-center justify-end gap-2">
                  <motion.button
                    type="button"
                    onClick={decline}
                    whileTap={shouldReduceMotion ? undefined : { scale: 0.96 }}
                    className="inline-flex items-center rounded-lg px-3 py-1.5 text-sm font-medium text-slate-600 transition-colors hover:bg-black/5 focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-slate-400 dark:text-slate-300 dark:hover:bg-white/10"
                  >
                    {isCamera ? "Not now, I'll pick a color" : "Not now, I'll type"}
                  </motion.button>
                  <motion.button
                    type="button"
                    disabled={requesting}
                    onClick={requestMedia}
                    whileHover={shouldReduceMotion || requesting ? undefined : { y: -1 }}
                    whileTap={shouldReduceMotion || requesting ? undefined : { scale: 0.96 }}
                    className="inline-flex items-center gap-1.5 rounded-lg bg-emerald-600 px-3.5 py-1.5 text-sm font-medium text-white transition-colors hover:bg-emerald-500 focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-emerald-600 disabled:cursor-wait disabled:opacity-70"
                  >
                    {requesting ? "Waiting for permission…" : config.allowLabel}
                  </motion.button>
                </div>
              </div>
            </motion.div>
          )}
        </AnimatePresence>

        <AnimatePresence initial={false}>
          {status === "fallback" && (
            <motion.div
              {...fade}
              transition={shouldReduceMotion ? { duration: 0.15 } : { height: { duration: 0.35, ease: [0.22, 1, 0.36, 1] }, opacity: { duration: 0.25 } }}
              className="overflow-hidden border-t border-slate-200/70 dark:border-white/10"
            >
              <div className="p-4">
                <p className="mb-2 text-xs leading-relaxed text-slate-500 dark:text-slate-400">{config.fallback[fallbackReason]}</p>
                {isCamera ? (
                  <div className="flex items-center gap-2.5">
                    {AVATAR_SWATCHES.map((swatch) => (
                      <motion.button
                        key={swatch.id}
                        type="button"
                        aria-pressed={avatarColor === swatch.id}
                        aria-label={`Use ${swatch.label} avatar`}
                        onClick={() => setAvatarColor(swatch.id)}
                        whileTap={shouldReduceMotion ? undefined : { scale: 0.88 }}
                        className={`relative flex h-9 w-9 shrink-0 items-center justify-center rounded-full ring-2 ring-offset-2 ring-offset-white transition-shadow dark:ring-offset-neutral-950 ${swatch.className} ${
                          avatarColor === swatch.id ? "ring-slate-900 dark:ring-white" : "ring-transparent"
                        }`}
                      >
                        <AnimatePresence>
                          {avatarColor === swatch.id && (
                            <motion.span
                              key="check"
                              initial={shouldReduceMotion ? { opacity: 0 } : { opacity: 0, scale: 0.4 }}
                              animate={{ opacity: 1, scale: 1 }}
                              exit={shouldReduceMotion ? { opacity: 0 } : { opacity: 0, scale: 0.4 }}
                              transition={{ type: "spring", stiffness: 500, damping: 28 }}
                              className="text-white"
                            >
                              <CheckIcon />
                            </motion.span>
                          )}
                        </AnimatePresence>
                      </motion.button>
                    ))}
                  </div>
                ) : (
                  <div className="flex items-start gap-2 rounded-lg border border-slate-200/70 bg-slate-50/60 px-3 py-2 dark:border-white/10 dark:bg-white/5">
                    <span className="mt-0.5 shrink-0 text-slate-400">
                      <KeyboardIcon />
                    </span>
                    <textarea
                      ref={textareaRef}
                      value={note}
                      onChange={(e) => setNote(e.target.value)}
                      rows={2}
                      placeholder="Type your note here"
                      className="flex-1 resize-none bg-transparent text-sm text-slate-800 placeholder:text-slate-400 focus:outline-none dark:text-slate-100"
                    />
                  </div>
                )}
                <button
                  type="button"
                  onClick={() => setStatus("asking")}
                  className="mt-2 text-xs font-medium text-emerald-600 underline-offset-2 transition-colors hover:underline focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-emerald-600 dark:text-emerald-400"
                >
                  {isCamera ? "Enable camera" : "Enable voice"}
                </button>
              </div>
            </motion.div>
          )}
        </AnimatePresence>

        <span className="sr-only" role="status" aria-live="polite">
          {status === "granted" ? (mediaOn ? config.activeLabel : config.pausedLabel) : status === "fallback" ? config.fallback[fallbackReason] : ""}
        </span>
      </div>
    </div>
  );
}

"use client";

import { useEffect, useRef, useState } from "react";
import { AnimatePresence, motion, useReducedMotion } from "framer-motion";
import {
  ClockCountdownIcon as PhClock,
  ArrowsClockwiseIcon as PhRetry,
  CheckIcon as PhCheck,
  ArrowCounterClockwiseIcon as PhReset,
} from "@phosphor-icons/react";

interface RetryAttempt {
  waitMs: number;
  reason: string;
}

const ATTEMPTS: RetryAttempt[] = [
  { waitMs: 9000, reason: "Rate limited by the sync API. 0 of 60 requests left in this window." },
  { waitMs: 16000, reason: "Still over the limit. Waiting longer this time before trying again." },
];

const REDUCED_WAIT_MS = 1200;
const RETRY_PULSE_MS = 700;

type Status = "waiting" | "retrying" | "succeeded";

function ClockIcon() {
  return <PhClock size={14} aria-hidden />;
}
function RetryIcon() {
  return <PhRetry size={13} aria-hidden />;
}
function CheckIcon() {
  return <PhCheck size={13} weight="bold" aria-hidden />;
}
function ResetIcon() {
  return <PhReset size={13} aria-hidden />;
}

function formatCountdown(ms: number) {
  const total = Math.max(0, Math.ceil(ms / 1000));
  const m = Math.floor(total / 60);
  const s = total % 60;
  return `${m}:${s.toString().padStart(2, "0")}`;
}

function HonestRetryRun({ onReplay }: { onReplay: () => void }) {
  const [attemptIndex, setAttemptIndex] = useState(0);
  const [status, setStatus] = useState<Status>("waiting");
  const [remainingMs, setRemainingMs] = useState(ATTEMPTS[0].waitMs);
  const shouldReduceMotion = useReducedMotion();
  const rafRef = useRef<number | null>(null);
  const pulseRef = useRef<ReturnType<typeof setTimeout> | null>(null);

  const waitMs = shouldReduceMotion ? REDUCED_WAIT_MS : ATTEMPTS[attemptIndex].waitMs;

  const advance = () => {
    if (rafRef.current) cancelAnimationFrame(rafRef.current);
    setStatus("retrying");
    pulseRef.current = setTimeout(
      () => {
        setAttemptIndex((i) => {
          if (i >= ATTEMPTS.length - 1) {
            setStatus("succeeded");
            return i;
          }
          setStatus("waiting");
          return i + 1;
        });
      },
      shouldReduceMotion ? 150 : RETRY_PULSE_MS
    );
  };

  useEffect(() => {
    if (status !== "waiting") return;
    const start = performance.now();
    const duration = waitMs;
    setRemainingMs(duration);

    const tick = () => {
      const left = Math.max(0, duration - (performance.now() - start));
      setRemainingMs(left);
      if (left > 0) {
        rafRef.current = requestAnimationFrame(tick);
      } else {
        advance();
      }
    };
    rafRef.current = requestAnimationFrame(tick);

    return () => {
      if (rafRef.current) cancelAnimationFrame(rafRef.current);
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [status, attemptIndex, waitMs]);

  useEffect(() => {
    return () => {
      if (pulseRef.current) clearTimeout(pulseRef.current);
    };
  }, []);

  const progress = 1 - remainingMs / waitMs;
  const attempt = ATTEMPTS[attemptIndex];
  const retryLabel = `Retry ${attemptIndex + 1} of ${ATTEMPTS.length}`;

  return (
    <div className="relative w-full max-w-md">
      <div className="relative overflow-hidden rounded-2xl border border-slate-200/70 bg-white/95 p-5 shadow-sm backdrop-blur-xl dark:border-white/10 dark:bg-neutral-950/80">
        <span className="sr-only" role="status" aria-live="polite">
          {status === "succeeded"
            ? `Synced. Took ${ATTEMPTS.length} retries.`
            : status === "retrying"
              ? "Trying again now."
              : `${attempt.reason} Retrying in ${formatCountdown(remainingMs)}. This is ${retryLabel.toLowerCase()}.`}
        </span>

        <AnimatePresence mode="wait" initial={false}>
          {status === "succeeded" ? (
            <motion.div
              key="succeeded"
              initial={shouldReduceMotion ? { opacity: 0 } : { opacity: 0, y: -6 }}
              animate={{ opacity: 1, y: 0 }}
              transition={{ duration: 0.25, ease: [0.22, 1, 0.36, 1] }}
              className="flex items-center gap-3"
            >
              <span className="relative flex h-9 w-9 shrink-0 items-center justify-center rounded-full bg-emerald-500/15 text-emerald-600 dark:text-emerald-400">
                {!shouldReduceMotion && (
                  <motion.span
                    aria-hidden
                    className="absolute rounded-full border-2 border-emerald-400/60"
                    style={{ inset: -3 }}
                    initial={{ scale: 0.7, opacity: 0.9 }}
                    animate={{ scale: 1.7, opacity: 0 }}
                    transition={{ duration: 0.6, ease: [0.16, 1, 0.3, 1] }}
                  />
                )}
                <CheckIcon />
              </span>
              <div className="min-w-0 flex-1">
                <p className="text-sm font-medium text-slate-900 dark:text-white">Synced</p>
                <p className="text-xs text-slate-400 dark:text-slate-500">Took {ATTEMPTS.length} retries, both explained while you waited.</p>
              </div>
              <button
                type="button"
                onClick={onReplay}
                aria-label="Run again"
                className="inline-flex h-8 w-8 shrink-0 items-center justify-center rounded-lg text-slate-400 transition-colors hover:bg-black/5 hover:text-slate-600 focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-emerald-600 dark:hover:bg-white/10 dark:hover:text-slate-300"
              >
                <ResetIcon />
              </button>
            </motion.div>
          ) : (
            <motion.div
              key="pending"
              initial={shouldReduceMotion ? { opacity: 0 } : { opacity: 0, y: -6 }}
              animate={{ opacity: 1, y: 0 }}
              exit={shouldReduceMotion ? { opacity: 0 } : { opacity: 0, y: 6 }}
              transition={{ duration: 0.25, ease: [0.22, 1, 0.36, 1] }}
            >
              <div className="flex items-start gap-3">
                <span className="relative flex h-9 w-9 shrink-0 items-center justify-center rounded-full bg-amber-500/15 text-amber-600 dark:text-amber-400">
                  <motion.span
                    animate={status === "retrying" && !shouldReduceMotion ? { rotate: 360 } : { rotate: 0 }}
                    transition={status === "retrying" && !shouldReduceMotion ? { duration: 0.7, ease: "linear" } : { duration: 0 }}
                  >
                    {status === "retrying" ? <RetryIcon /> : <ClockIcon />}
                  </motion.span>
                </span>
                <div className="min-w-0 flex-1">
                  <div className="flex flex-wrap items-center gap-2">
                    <p className="text-sm font-medium text-slate-900 dark:text-white">{status === "retrying" ? "Trying again" : "Sync paused"}</p>
                    <span className="shrink-0 rounded-full bg-slate-500/10 px-1.5 py-0.5 text-[10px] font-medium text-slate-500 dark:bg-white/10 dark:text-slate-400">
                      {retryLabel}
                    </span>
                  </div>
                  <p className="mt-0.5 text-xs text-slate-500 dark:text-slate-400">{attempt.reason}</p>
                </div>
              </div>

              <div className="mt-4 flex items-center justify-between gap-3">
                <p className="tabular-nums text-2xl font-semibold text-slate-900 dark:text-white">
                  {status === "retrying" ? "···" : formatCountdown(remainingMs)}
                </p>
                <button
                  type="button"
                  onClick={advance}
                  disabled={status === "retrying"}
                  className="inline-flex shrink-0 items-center gap-1.5 rounded-lg border border-slate-200/70 px-3 py-1.5 text-sm font-medium text-slate-600 transition-colors hover:bg-black/5 disabled:cursor-not-allowed disabled:opacity-50 focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-amber-500 dark:border-white/10 dark:text-slate-300 dark:hover:bg-white/5"
                >
                  <RetryIcon />
                  Retry now
                </button>
              </div>

              <div className="mt-3 h-1 overflow-hidden rounded-full bg-amber-500/15">
                <motion.div
                  className="h-full rounded-full bg-amber-500"
                  style={{ transformOrigin: "left" }}
                  animate={{ scaleX: status === "retrying" ? 1 : progress }}
                  transition={{ duration: 0 }}
                />
              </div>
            </motion.div>
          )}
        </AnimatePresence>
      </div>
    </div>
  );
}

export function HonestRetryPreview() {
