"use client";

import { useEffect, useRef, useState } from "react";
import { AnimatePresence, motion, useReducedMotion } from "framer-motion";
import {
  SparkleIcon as PhSparkle,
  CaretDownIcon as PhCaret,
  CheckIcon as PhCheck,
  WarningCircleIcon as PhWarning,
  ArrowCounterClockwiseIcon as PhReset,
} from "@phosphor-icons/react";

interface SlotOption {
  value: string;
  detail?: string;
}

interface Slot {
  id: string;
  options: SlotOption[];
  reason?: string;
}

type Part = { type: "text"; value: string } | { type: "slot"; id: string };

interface Example {
  id: string;
  prompt: string;
  parts: Part[];
  slots: Slot[];
}

const EXAMPLES: Example[] = [
  {
    id: "meeting",
    prompt: "Schedule a meeting with Sarah tomorrow at 3",
    parts: [
      { type: "text", value: "Schedule a meeting with " },
      { type: "slot", id: "person" },
      { type: "text", value: " " },
      { type: "slot", id: "when" },
      { type: "text", value: "." },
    ],
    slots: [
      {
        id: "person",
        reason: "Two contacts are named Sarah.",
        options: [
          { value: "Sarah Chen", detail: "Messaged most recently" },
          { value: "Sarah Kim", detail: "Also in your contacts" },
        ],
      },
      { id: "when", options: [{ value: "tomorrow at 3:00 PM" }] },
    ],
  },
  {
    id: "reminder",
    prompt: "Remind me to call mom next Tuesday",
    parts: [
      { type: "text", value: "Remind you to call " },
      { type: "slot", id: "person" },
      { type: "text", value: " " },
      { type: "slot", id: "when" },
      { type: "text", value: "." },
    ],
    slots: [
      { id: "person", options: [{ value: "Mom" }] },
      {
        id: "when",
        reason: "\"Next Tuesday\" could mean either week.",
        options: [
          { value: "this coming Tuesday", detail: "3 days away" },
          { value: "Tuesday next week", detail: "10 days away" },
        ],
      },
    ],
  },
];

type Stage = "choose" | "parsing" | "review" | "confirmed";

function SlotPill({
  slot,
  selectedIndex,
  open,
  onToggle,
  onSelect,
  onClose,
}: {
  slot: Slot;
  selectedIndex: number;
  open: boolean;
  onToggle: () => void;
  onSelect: (index: number) => void;
  onClose: () => void;
}) {
  const ambiguous = slot.options.length > 1;
  const selected = slot.options[selectedIndex];

  return (
    <span
      className="relative inline-flex"
      onBlur={(event) => {
        if (!event.currentTarget.contains(event.relatedTarget as Node)) onClose();
      }}
    >
      <button
        type="button"
        onClick={onToggle}
        onKeyDown={(event) => {
          if (event.key === "Escape") onClose();
        }}
        aria-haspopup="listbox"
        aria-expanded={open}
        className={`inline-flex items-center gap-1 rounded-md border px-2 py-0.5 text-[15px] font-medium transition-colors ${
          ambiguous
            ? "border-amber-400/50 bg-amber-50/70 text-amber-800 hover:bg-amber-100/70 dark:border-amber-400/30 dark:bg-amber-500/10 dark:text-amber-200"
            : "border-emerald-400/40 bg-emerald-50/60 text-emerald-800 hover:bg-emerald-100/60 dark:border-emerald-400/25 dark:bg-emerald-500/10 dark:text-emerald-200"
        }`}
      >
        {selected.value}
        <PhCaret size={11} className={`transition-transform ${open ? "rotate-180" : ""}`} aria-hidden />
      </button>

      <AnimatePresence>
        {open && (
          <motion.div
            role="listbox"
            aria-label={ambiguous ? slot.reason : "Interpretation"}
            initial={{ opacity: 0, y: -4, scale: 0.97 }}
            animate={{ opacity: 1, y: 0, scale: 1 }}
            exit={{ opacity: 0, y: -4, scale: 0.97 }}
            transition={{ duration: 0.16, ease: [0.22, 1, 0.36, 1] }}
            className="absolute left-0 top-full z-10 mt-1.5 w-60 overflow-hidden rounded-xl border border-slate-200/70 bg-white p-1 text-left shadow-lg dark:border-white/10 dark:bg-neutral-900"
          >
            {slot.reason ? (
              <p className="px-2 pb-1 pt-1.5 text-[11px] text-slate-400 dark:text-slate-500">{slot.reason}</p>
            ) : (
              <p className="px-2 pb-1 pt-1.5 text-[11px] text-slate-400 dark:text-slate-500">Only one clear match.</p>
            )}
            {slot.options.map((option, index) => (
              <button
                key={option.value}
                type="button"
                role="option"
                aria-selected={index === selectedIndex}
                onClick={() => onSelect(index)}
                className="flex w-full items-start gap-2 rounded-lg px-2 py-1.5 text-left text-sm text-slate-700 transition-colors hover:bg-slate-100 dark:text-slate-200 dark:hover:bg-white/10"
              >
                <span
                  className={`mt-0.5 flex h-3.5 w-3.5 shrink-0 items-center justify-center rounded-full ${
                    index === selectedIndex ? "bg-emerald-500 text-white" : "border border-slate-300 dark:border-slate-600"
                  }`}
                >
                  {index === selectedIndex && <PhCheck size={9} weight="bold" aria-hidden />}
                </span>
                <span className="min-w-0">
                  <span className="block truncate">{option.value}</span>
                  {option.detail && <span className="block text-xs text-slate-400 dark:text-slate-500">{option.detail}</span>}
                </span>
              </button>
            ))}
          </motion.div>
        )}
      </AnimatePresence>
    </span>
  );
}

export function AmbiguousInputResolverPreview() {
  const [stage, setStage] = useState<Stage>("choose");
  const [exampleId, setExampleId] = useState<string | null>(null);
  const [selections, setSelections] = useState<Record<string, number>>({});
  const [openSlot, setOpenSlot] = useState<string | null>(null);
  const shouldReduceMotion = useReducedMotion();
  const parseTimeout = useRef<ReturnType<typeof setTimeout> | null>(null);

  const example = EXAMPLES.find((item) => item.id === exampleId) ?? null;
  const ambiguousSlots = example ? example.slots.filter((s) => s.options.length > 1) : [];

  useEffect(() => {
    return () => {
      if (parseTimeout.current) clearTimeout(parseTimeout.current);
    };
  }, []);

  const chooseExample = (id: string) => {
    setExampleId(id);
    setSelections({});
    setOpenSlot(null);
    setStage("parsing");
    if (parseTimeout.current) clearTimeout(parseTimeout.current);
    parseTimeout.current = setTimeout(() => setStage("review"), shouldReduceMotion ? 150 : 650);
  };

  const reset = () => {
    setStage("choose");
    setExampleId(null);
    setSelections({});
    setOpenSlot(null);
  };

  const fade = shouldReduceMotion
    ? { initial: { opacity: 0 }, animate: { opacity: 1 }, exit: { opacity: 0 } }
    : { initial: { opacity: 0, y: -6 }, animate: { opacity: 1, y: 0 }, exit: { opacity: 0, y: 6 } };
  const fadeT = { duration: 0.22, ease: [0.22, 1, 0.36, 1] as const };

  const finalSentence =
    example &&
    example.parts.map((part) => (part.type === "text" ? part.value : example.slots.find((s) => s.id === part.id)!.options[selections[part.id] ?? 0].value)).join("");

  return (
    <div className="flex w-full max-w-md flex-col items-center gap-4">
      <div className="relative w-full overflow-hidden rounded-2xl border border-slate-200/70 bg-white/95 p-5 shadow-sm backdrop-blur-xl dark:border-white/10 dark:bg-neutral-950/80">
        <span className="sr-only" role="status" aria-live="polite">
          {stage === "parsing"
            ? `Parsing "${example?.prompt}".`
            : stage === "review"
              ? ambiguousSlots.length > 0
                ? `Interpreted. ${ambiguousSlots.length} detail${ambiguousSlots.length > 1 ? "s" : ""} need a check.`
                : "Interpreted with high confidence."
              : stage === "confirmed"
                ? `Confirmed. ${finalSentence}`
                : "Choose a phrase to interpret."}
        </span>

        <AnimatePresence mode="wait" initial={false}>
          {stage === "choose" && (
            <motion.div key="choose" {...fade} transition={fadeT}>
              <div className="flex items-center gap-2 text-sm font-medium text-slate-900 dark:text-white">
                <PhSparkle size={14} aria-hidden />
                Try a phrase
              </div>
              <p className="mt-1 text-xs text-slate-400 dark:text-slate-500">
                Stands in for typed, spoken, or autocompleted input on its way to a parser.
              </p>
              <div className="mt-3 flex flex-wrap gap-2">
                {EXAMPLES.map((ex) => (
                  <button
                    key={ex.id}
                    type="button"
                    onClick={() => chooseExample(ex.id)}
                    className="rounded-full border border-slate-200/70 bg-white px-3 py-1.5 text-left text-sm text-slate-600 transition-colors hover:border-slate-300 hover:bg-slate-50 focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-emerald-600 dark:border-white/10 dark:bg-white/5 dark:text-slate-300 dark:hover:bg-white/10"
                  >
                    &ldquo;{ex.prompt}&rdquo;
                  </button>
                ))}
              </div>
            </motion.div>
          )}

          {stage === "parsing" && example && (
            <motion.div key="parsing" {...fade} transition={fadeT} className="flex items-center gap-3 py-2">
              <span className="relative flex h-9 w-9 shrink-0 items-center justify-center rounded-full bg-slate-500/10 text-slate-500 dark:bg-white/10 dark:text-slate-300">
                <motion.span
                  animate={shouldReduceMotion ? { opacity: 1 } : { opacity: [0.4, 1, 0.4] }}
                  transition={shouldReduceMotion ? { duration: 0 } : { duration: 0.65, repeat: Infinity, ease: "easeInOut" }}
                >
                  <PhSparkle size={14} aria-hidden />
                </motion.span>
              </span>
              <div className="min-w-0 flex-1">
                <p className="text-sm font-medium text-slate-900 dark:text-white">Interpreting…</p>
                <p className="truncate text-xs text-slate-400 dark:text-slate-500">&ldquo;{example.prompt}&rdquo;</p>
              </div>
            </motion.div>
          )}

          {stage === "review" && example && (
            <motion.div key="review" {...fade} transition={fadeT}>
              <div
                className={`flex items-start gap-2 rounded-lg px-3 py-2 text-xs ${
                  ambiguousSlots.length > 0
                    ? "bg-amber-500/10 text-amber-700 dark:text-amber-300"
                    : "bg-emerald-500/10 text-emerald-700 dark:text-emerald-300"
                }`}
              >
                {ambiguousSlots.length > 0 ? <PhWarning size={14} className="mt-px shrink-0" aria-hidden /> : <PhCheck size={14} className="mt-px shrink-0" aria-hidden />}
                <span>
                  {ambiguousSlots.length > 0
                    ? `Not fully sure about ${ambiguousSlots.length} detail${ambiguousSlots.length > 1 ? "s" : ""} below. Tap it to change.`
                    : "Parsed with high confidence."}
                </span>
              </div>

              <div className="mt-3 flex flex-wrap items-center gap-x-1.5 gap-y-2 text-[15px] leading-relaxed text-slate-800 dark:text-slate-100">
                {example.parts.map((part, i) =>
                  part.type === "text" ? (
                    <span key={i}>{part.value}</span>
                  ) : (
                    <SlotPill
                      key={part.id}
                      slot={example.slots.find((s) => s.id === part.id)!}
                      selectedIndex={selections[part.id] ?? 0}
                      open={openSlot === part.id}
                      onToggle={() => setOpenSlot((cur) => (cur === part.id ? null : part.id))}
                      onSelect={(index) => {
                        setSelections((prev) => ({ ...prev, [part.id]: index }));
                        setOpenSlot(null);
                      }}
                      onClose={() => setOpenSlot(null)}
                    />
                  )
                )}
              </div>

              <div className="mt-4 flex flex-wrap items-center gap-2">
                <button
                  type="button"
                  onClick={() => setStage("confirmed")}
                  className="inline-flex items-center gap-1.5 rounded-lg bg-emerald-600 px-3 py-1.5 text-sm font-medium text-white transition-colors hover:bg-emerald-500 focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-emerald-600"
                >
                  <PhCheck size={13} weight="bold" aria-hidden />
                  Looks right
                </button>
                <button
                  type="button"
                  onClick={reset}
                  className="inline-flex items-center gap-1.5 rounded-lg px-3 py-1.5 text-sm font-medium text-slate-500 transition-colors hover:bg-black/5 hover:text-slate-700 focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-slate-400 dark:text-slate-400 dark:hover:bg-white/10 dark:hover:text-slate-200"
                >
                  Not this, try another
                </button>
              </div>
            </motion.div>
          )}

          {stage === "confirmed" && example && (
            <motion.div key="confirmed" {...fade} transition={fadeT} className="flex items-start gap-3">
              <span className="relative flex h-9 w-9 shrink-0 items-center justify-center rounded-full bg-emerald-500/15 text-emerald-600 dark:text-emerald-400">
                {!shouldReduceMotion && (
                  <motion.span
                    aria-hidden
                    className="absolute rounded-full border-2 border-emerald-400/60"
                    style={{ inset: -3 }}
                    initial={{ scale: 0.7, opacity: 0.9 }}
                    animate={{ scale: 1.7, opacity: 0 }}
                    transition={{ duration: 0.6, ease: [0.16, 1, 0.3, 1] }}
                  />
                )}
                <PhCheck size={13} weight="bold" aria-hidden />
              </span>
              <div className="min-w-0 flex-1">
                <p className="text-sm font-medium text-slate-900 dark:text-white">Confirmed</p>
                <p className="mt-0.5 text-sm text-slate-600 dark:text-slate-300">{finalSentence}</p>
                <button
                  type="button"
                  onClick={reset}
                  className="mt-2 inline-flex items-center gap-1.5 rounded-lg px-2 py-1 text-xs font-medium text-slate-400 transition-colors hover:bg-black/5 hover:text-slate-600 focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-slate-400 dark:hover:bg-white/10 dark:hover:text-slate-300"
                >
                  <PhReset size={13} aria-hidden />
                  Start over
                </button>
              </div>
            </motion.div>
          )}
        </AnimatePresence>
      </div>
    </div>
  );
}

"use client";

import { useState } from "react";
import { AnimatePresence, motion, useReducedMotion } from "framer-motion";
import {
