  ArrowRightIcon as PhArrowRight,
  ArrowsMergeIcon as PhMerge,
  CheckIcon as PhCheck,
  ArrowCounterClockwiseIcon as PhReset,
} from "@phosphor-icons/react";

interface BatchItem {
  id: string;
  title: string;
  before: string[];
  after: string[];
  outcome: "renamed" | "merged";
  note: string;
}

const FROM_TAG = "wip";
const TO_TAG = "in-progress";

const ITEMS: BatchItem[] = [
  {
    id: "settings",
    title: "Redesign settings page",
    before: ["wip", "design"],
    after: ["in-progress", "design"],
    outcome: "renamed",
    note: "wip becomes in-progress.",
  },
  {
    id: "auth",
    title: "Fix auth token refresh",
    before: ["wip", "bug"],
    after: ["in-progress", "bug"],
    outcome: "renamed",
    note: "wip becomes in-progress.",
  },
  {
