type Stage = "review" | "applying" | "applied";

function TagChip({ text, changed }: { text: string; changed?: "removed" | "added" }) {
  if (changed === "removed") {
    return (
      <span className="rounded-full border border-rose-300/60 bg-rose-50/80 px-2 py-0.5 text-xs font-medium text-rose-600 line-through dark:border-rose-500/30 dark:bg-rose-500/10 dark:text-rose-300">
        {text}
      </span>
    );
  }
  if (changed === "added") {
    return (
      <span className="rounded-full border border-emerald-400/50 bg-emerald-50/80 px-2 py-0.5 text-xs font-medium text-emerald-700 dark:border-emerald-400/30 dark:bg-emerald-500/10 dark:text-emerald-300">
        {text}
      </span>
    );
  }
  return (
    <span className="rounded-full border border-slate-200/70 bg-slate-50 px-2 py-0.5 text-xs font-medium text-slate-500 dark:border-white/10 dark:bg-white/5 dark:text-slate-400">
      {text}
    </span>
