}

function RowCheckbox({ checked, onChange, label }: { checked: boolean; onChange: () => void; label: string }) {
  const shouldReduceMotion = useReducedMotion();
  return (
    <button
      type="button"
      role="checkbox"
      aria-checked={checked}
      aria-label={label}
      onClick={onChange}
      className={`flex h-[18px] w-[18px] shrink-0 items-center justify-center rounded-md border-2 transition-colors duration-200 focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-emerald-700 ${
        checked ? "border-emerald-700 bg-emerald-700" : "border-slate-300 bg-white dark:border-slate-600 dark:bg-neutral-950"
      }`}
    >
      <svg viewBox="0 0 16 16" width="11" height="11" fill="none" stroke="white" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round" aria-hidden>
        <motion.path
          d="M3 8.5l3 3 7-7.5"
          initial={false}
          animate={checked ? { pathLength: 1, opacity: 1 } : { pathLength: 0, opacity: 0 }}
          transition={shouldReduceMotion ? { duration: 0 } : { duration: 0.25, ease: [0.22, 1, 0.36, 1] }}
        />
      </svg>
    </button>
  );
}

function BatchActionPreviewRun({ onReplay }: { onReplay: () => void }) {
  const [included, setIncluded] = useState<Record<string, boolean>>(() => Object.fromEntries(ITEMS.map((i) => [i.id, true])));
  const [stage, setStage] = useState<Stage>("review");
  const shouldReduceMotion = useReducedMotion();

  const toggle = (id: string) => setIncluded((prev) => ({ ...prev, [id]: !prev[id] }));

  const activeItems = ITEMS.filter((i) => included[i.id]);
  const renamedCount = activeItems.filter((i) => i.outcome === "renamed").length;
  const mergedCount = activeItems.filter((i) => i.outcome === "merged").length;

  const apply = () => {
    if (activeItems.length === 0) return;
    setStage("applying");
    setTimeout(() => setStage("applied"), shouldReduceMotion ? 120 : 550);
  };

  const summary =
    mergedCount > 0
      ? `${renamedCount} renamed, ${mergedCount} merged`
      : `${renamedCount} tag${renamedCount === 1 ? "" : "s"} renamed`;

  return (
