"use client";

import { useEffect, useRef, useState } from "react";
import { motion, useReducedMotion } from "framer-motion";
import { CloudCheckIcon as PhCloudCheck, WarningIcon as PhWarning, ArrowClockwiseIcon as PhRetry } from "@phosphor-icons/react";

type SaveState = "saved" | "editing" | "saving" | "error";

const SAVE_DELAY_MS = 500;
const NETWORK_DELAY_MS = 550;

export function AmbientSaveIndicatorPreview() {
  const [text, setText] = useState("Q3 roadmap notes\n\nShip v2 export by Friday.");
  const [state, setState] = useState<SaveState>("saved");
  const [simulateFailure, setSimulateFailure] = useState(false);
  const [unsavedCount, setUnsavedCount] = useState(0);
  const shouldReduceMotion = useReducedMotion();

  const saveTimer = useRef<ReturnType<typeof setTimeout> | null>(null);
  const networkTimer = useRef<ReturnType<typeof setTimeout> | null>(null);
  const simulateFailureRef = useRef(simulateFailure);

  useEffect(() => {
    simulateFailureRef.current = simulateFailure;
  }, [simulateFailure]);

  useEffect(() => {
    return () => {
      if (saveTimer.current) clearTimeout(saveTimer.current);
      if (networkTimer.current) clearTimeout(networkTimer.current);
    };
  }, []);

  const runSave = () => {
    setState("saving");
    networkTimer.current = setTimeout(() => {
      if (simulateFailureRef.current) {
        setState("error");
        setUnsavedCount((c) => c + 1);
      } else {
        setState("saved");
        setUnsavedCount(0);
      }
    }, NETWORK_DELAY_MS);
  };

  const handleChange = (value: string) => {
    setText(value);
    setState("editing");
    if (saveTimer.current) clearTimeout(saveTimer.current);
    if (networkTimer.current) clearTimeout(networkTimer.current);
    saveTimer.current = setTimeout(runSave, SAVE_DELAY_MS);
  };

  const retry = () => {
    if (networkTimer.current) clearTimeout(networkTimer.current);
    runSave();
  };

  const dotTone =
    state === "error"
      ? "bg-rose-500"
      : state === "saving" || state === "editing"
        ? "bg-amber-500"
        : "bg-emerald-500";

  const label =
    state === "error"
      ? "Couldn't save"
      : state === "editing"
        ? "Editing"
        : state === "saving"
          ? "Saving…"
          : "All changes saved";

  return (
    <div className="flex w-full max-w-md flex-col items-center gap-4">
      <div className="w-full overflow-hidden rounded-2xl border border-slate-200/70 bg-white/95 shadow-sm backdrop-blur-xl dark:border-white/10 dark:bg-neutral-950/80">
        <span className="sr-only" role="status" aria-live="polite">
          {state === "error" ? `Couldn't save. ${unsavedCount} change${unsavedCount === 1 ? "" : "s"} not backed up.` : label}
        </span>

        <div className="p-4">
          <textarea
            value={text}
            onChange={(event) => handleChange(event.target.value)}
            rows={4}
            className="w-full resize-none rounded-lg border border-slate-200/70 bg-white/60 px-3 py-2 text-sm text-slate-800 focus:outline-none focus-visible:border-slate-400 dark:border-white/10 dark:bg-white/5 dark:text-slate-100"
          />
        </div>

        <motion.div layout={!shouldReduceMotion} transition={{ duration: 0.3, ease: [0.22, 1, 0.36, 1] }} className="overflow-hidden">
          {state === "error" ? (
            <div className="flex items-center justify-between gap-3 border-t border-rose-300/50 bg-rose-50 px-4 py-3 dark:border-rose-500/30 dark:bg-rose-500/10">
              <div className="flex items-center gap-2">
                <PhWarning size={16} className="shrink-0 text-rose-600 dark:text-rose-400" aria-hidden />
                <div>
                  <p className="text-sm font-semibold text-rose-700 dark:text-rose-300">Couldn&apos;t save</p>
                  <p className="text-xs text-rose-600/80 dark:text-rose-400/70">
                    {unsavedCount} change{unsavedCount === 1 ? "" : "s"} not backed up yet.
                  </p>
                </div>
              </div>
              <button
                type="button"
                onClick={retry}
                className="inline-flex shrink-0 items-center gap-1.5 rounded-lg bg-rose-600 px-2.5 py-1.5 text-xs font-medium text-white transition-colors hover:bg-rose-500 focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-rose-600"
              >
                <PhRetry size={12} aria-hidden />
                Retry
              </button>
            </div>
          ) : (
            <div className="flex items-center gap-1.5 border-t border-slate-100 px-4 py-2 dark:border-white/10">
              {state === "saved" ? (
                <PhCloudCheck size={12} className="text-emerald-500" aria-hidden />
              ) : (
                <motion.span
                  aria-hidden
                  className={`h-1.5 w-1.5 rounded-full ${dotTone}`}
                  animate={shouldReduceMotion ? { opacity: 1 } : { opacity: [0.4, 1, 0.4] }}
                  transition={shouldReduceMotion ? { duration: 0 } : { duration: 1.1, repeat: Infinity, ease: "easeInOut" }}
                />
              )}
              <span className="text-xs text-slate-400 dark:text-slate-500">{label}</span>
            </div>
          )}
        </motion.div>
      </div>

      <label className="flex items-center gap-2 text-xs text-slate-400 dark:text-slate-500">
        <input
          type="checkbox"
          checked={simulateFailure}
          onChange={(event) => setSimulateFailure(event.target.checked)}
          className="h-3.5 w-3.5 rounded border-slate-300 text-rose-600 focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-rose-500 dark:border-slate-600"
        />
        Simulate save failures
      </label>
      <p className="text-center text-xs text-slate-400 dark:text-slate-500">
        Saved state stays small and quiet. It only grows loud, a full bar with a retry, once saving actually fails.
      </p>
    </div>
  );
}

