"use client";

import { useEffect, useRef, useState } from "react";
import { AnimatePresence, motion, useReducedMotion } from "framer-motion";
import {
  TimerIcon as PhTimer,
  ShieldCheckIcon as PhShield,
  LockSimpleIcon as PhLock,
  CheckIcon as PhCheck,
} from "@phosphor-icons/react";

const SESSION_MS = 18000;
const WARNING_THRESHOLD_MS = 7000;
const REDUCED_SESSION_MS = 4000;
const REDUCED_WARNING_MS = 2000;
const REAUTH_MS = 700;

type Phase = "active" | "warning" | "expired" | "reauthing";

function formatCountdown(ms: number) {
  const total = Math.max(0, Math.ceil(ms / 1000));
  const m = Math.floor(total / 60);
  const s = total % 60;
  return `${m}:${s.toString().padStart(2, "0")}`;
}

export function SessionTimeoutWarningPreview() {
  const [phase, setPhase] = useState<Phase>("active");
  const [remainingMs, setRemainingMs] = useState(SESSION_MS);
  const [draft, setDraft] = useState("Customer says the export button hangs on files over 50MB. Repro steps:\n1. ");
  const shouldReduceMotion = useReducedMotion();

  const rafRef = useRef<number | null>(null);
  const reauthTimer = useRef<ReturnType<typeof setTimeout> | null>(null);
  // Bumped on every real reset (mount, "Stay signed in", finishing sign-back-in).
  // The active -> warning flip happens inside this same effect's own tick loop
  // and deliberately does *not* restart it, so a countdown that's already
  // running keeps its real start time; only an actual reset should re-baseline it.
  const [sessionEpoch, setSessionEpoch] = useState(0);

  const sessionMs = shouldReduceMotion ? REDUCED_SESSION_MS : SESSION_MS;
  const warningMs = shouldReduceMotion ? REDUCED_WARNING_MS : WARNING_THRESHOLD_MS;

  useEffect(() => {
    const start = performance.now();

    const tick = () => {
      const left = Math.max(0, sessionMs - (performance.now() - start));
      setRemainingMs(left);
      if (left <= 0) {
        setPhase("expired");
        return;
      }
      setPhase((current) => (left <= warningMs && current === "active" ? "warning" : current));
      rafRef.current = requestAnimationFrame(tick);
    };
    rafRef.current = requestAnimationFrame(tick);

    return () => {
      if (rafRef.current) cancelAnimationFrame(rafRef.current);
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [sessionEpoch]);

  useEffect(() => {
    return () => {
      if (rafRef.current) cancelAnimationFrame(rafRef.current);
      if (reauthTimer.current) clearTimeout(reauthTimer.current);
    };
  }, []);

  const stayCurrent = () => {
    setRemainingMs(sessionMs);
    setPhase("active");
    setSessionEpoch((e) => e + 1);
  };

  const signBackIn = () => {
    setPhase("reauthing");
    reauthTimer.current = setTimeout(
      () => {
        setRemainingMs(sessionMs);
        setPhase("active");
        setSessionEpoch((e) => e + 1);
      },
      shouldReduceMotion ? 150 : REAUTH_MS
    );
  };

  const disabled = phase === "expired" || phase === "reauthing";

  return (
    <div className="flex w-full max-w-md flex-col items-center gap-4">
      <div className="relative w-full overflow-hidden rounded-2xl border border-slate-200/70 bg-white/95 shadow-sm backdrop-blur-xl dark:border-white/10 dark:bg-neutral-950/80">
        <span className="sr-only" role="status" aria-live="polite">
          {phase === "warning"
            ? `Your session expires in ${formatCountdown(remainingMs)}.`
            : phase === "expired"
              ? "Session expired. Your draft is safe."
              : phase === "reauthing"
                ? "Signing back in."
                : ""}
        </span>

        <AnimatePresence initial={false}>
          {phase === "warning" && (
            <motion.div
              initial={shouldReduceMotion ? { opacity: 0 } : { opacity: 0, height: 0 }}
              animate={{ opacity: 1, height: "auto" }}
              exit={shouldReduceMotion ? { opacity: 0 } : { opacity: 0, height: 0 }}
              transition={{ duration: 0.25, ease: [0.22, 1, 0.36, 1] }}
              className="overflow-hidden"
            >
              <div className="flex items-center justify-between gap-3 border-b border-amber-400/40 bg-amber-50/80 px-4 py-2.5 dark:bg-amber-500/10">
                <p className="flex items-center gap-1.5 text-xs font-medium text-amber-700 dark:text-amber-300">
                  <PhTimer size={13} aria-hidden />
                  Session expires in <span className="tabular-nums">{formatCountdown(remainingMs)}</span>
                </p>
                <button
                  type="button"
                  onClick={stayCurrent}
                  className="inline-flex shrink-0 items-center gap-1.5 rounded-lg bg-amber-600 px-2.5 py-1 text-xs font-medium text-white transition-colors hover:bg-amber-500 focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-amber-600"
                >
                  Stay signed in
                </button>
              </div>
            </motion.div>
          )}
        </AnimatePresence>

        <div className="p-4">
          <p className="text-xs font-medium text-slate-500 dark:text-slate-400">Support ticket #4821</p>
          <textarea
            value={draft}
            onChange={(event) => setDraft(event.target.value)}
            disabled={disabled}
            rows={4}
            className="mt-1.5 w-full resize-none rounded-lg border border-slate-200/70 bg-white/60 px-3 py-2 text-sm text-slate-800 focus:outline-none focus-visible:border-emerald-500 disabled:cursor-not-allowed disabled:opacity-60 dark:border-white/10 dark:bg-white/5 dark:text-slate-100"
          />
        </div>

        <AnimatePresence>
          {(phase === "expired" || phase === "reauthing") && (
            <motion.div
              initial={shouldReduceMotion ? { opacity: 0 } : { opacity: 0, y: 6 }}
              animate={{ opacity: 1, y: 0 }}
              exit={shouldReduceMotion ? { opacity: 0 } : { opacity: 0, y: 6 }}
              transition={{ duration: 0.2, ease: [0.22, 1, 0.36, 1] }}
              className="flex items-center justify-between gap-3 border-t border-slate-200/70 bg-slate-50/80 px-4 py-3 dark:border-white/10 dark:bg-white/[0.03]"
            >
              <div className="flex items-center gap-2">
                <span className="flex h-7 w-7 shrink-0 items-center justify-center rounded-full bg-slate-500/10 text-slate-500 dark:bg-white/10 dark:text-slate-300">
                  <PhLock size={13} aria-hidden />
                </span>
                <div>
                  <p className="text-xs font-medium text-slate-700 dark:text-slate-200">Session expired</p>
                  <p className="text-[11px] text-slate-400 dark:text-slate-500">Your draft above is still here, sign back in to keep going.</p>
                </div>
              </div>
              <button
                type="button"
                onClick={signBackIn}
                disabled={phase === "reauthing"}
                className="inline-flex shrink-0 items-center gap-1.5 rounded-lg bg-slate-900 px-2.5 py-1.5 text-xs font-medium text-white transition-colors hover:bg-slate-700 disabled:cursor-not-allowed disabled:opacity-60 focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-emerald-600 dark:bg-white dark:text-slate-900 dark:hover:bg-slate-200"
              >
                {phase === "reauthing" ? (
                  <motion.span
                    aria-hidden
                    className="h-3 w-3 rounded-full border-2 border-white/30 border-t-white dark:border-slate-900/30 dark:border-t-slate-900"
                    animate={shouldReduceMotion ? { rotate: 0 } : { rotate: 360 }}
                    transition={shouldReduceMotion ? { duration: 0 } : { duration: 0.6, repeat: Infinity, ease: "linear" }}
                  />
                ) : (
                  <PhShield size={12} aria-hidden />
                )}
                {phase === "reauthing" ? "Signing in…" : "Sign back in"}
              </button>
            </motion.div>
          )}
        </AnimatePresence>

        <AnimatePresence>
          {phase === "active" && (
            <motion.p
              initial={{ opacity: 0 }}
              animate={{ opacity: 1 }}
              exit={{ opacity: 0 }}
              className="flex items-center gap-1.5 border-t border-slate-100 px-4 py-2 text-[11px] text-slate-400 dark:border-white/10 dark:text-slate-500"
            >
              <PhCheck size={11} aria-hidden />
              Signed in, session active
            </motion.p>
          )}
        </AnimatePresence>
      </div>
      <p className="text-center text-xs text-slate-400 dark:text-slate-500">
        The warning arrives with real time left to act, and expiring never touches the draft above, sign back in and it&apos;s exactly where you left it.
      </p>
    </div>
  );
}

