                className="inline-flex items-center gap-1.5 rounded-lg border border-slate-200/70 px-2.5 py-1.5 text-xs font-medium text-slate-600 transition-colors hover:bg-black/5 focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-slate-400 dark:border-white/10 dark:text-slate-300 dark:hover:bg-white/10"
              >
                <SignalIcon icon={signalB.icon} />
                Trust {signalB.source.toLowerCase()}
              </button>
              <button
                type="button"
                onClick={() => setResolution("review")}
                className="inline-flex items-center gap-1.5 rounded-lg px-2.5 py-1.5 text-xs font-medium text-slate-400 transition-colors hover:bg-black/5 hover:text-slate-600 focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-slate-400 dark:hover:bg-white/10 dark:hover:text-slate-300"
              >
                <PhMagnify size={12} aria-hidden />
                Send to manual review
              </button>
            </motion.div>
          ) : (
            <motion.div
              key="resolved"
              initial={shouldReduceMotion ? { opacity: 0 } : { opacity: 0, y: -4 }}
              animate={{ opacity: 1, y: 0 }}
              transition={{ duration: 0.2, ease: [0.22, 1, 0.36, 1] }}
              className="mt-3.5 flex items-center justify-between gap-3 border-t border-slate-100 pt-3.5 dark:border-white/10"
            >
              <p className="text-xs text-slate-500 dark:text-slate-400">
                {resolution === "review" ? (
                  <>
                    <span className="font-medium text-slate-700 dark:text-slate-200">Sent for manual review.</span> Both signals stay on record, neither was
                    picked.
                  </>
                ) : (
                  <>
                    <span className="font-medium text-slate-700 dark:text-slate-200">
                      Resolved: went with {resolution === "signal-0" ? signalA.source.toLowerCase() : signalB.source.toLowerCase()}.
                    </span>{" "}
                    The other signal stays visible above, it was overridden, not erased.
                  </>
                )}
              </p>
              <button
                type="button"
                onClick={() => setResolution(null)}
                className="inline-flex shrink-0 items-center gap-1 text-xs font-medium text-slate-400 underline-offset-2 hover:text-slate-600 hover:underline focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-slate-400 dark:text-slate-500 dark:hover:text-slate-300"
              >
                <PhReset size={11} aria-hidden />
                Undo
              </button>
            </motion.div>
          )}
        </AnimatePresence>
      </div>
      <p className="text-center text-xs text-slate-400 dark:text-slate-500">
        Neither signal is hidden once resolved, only which one wins is recorded, and that decision can still be undone.
      </p>
    </div>
  );
}

