    answer: "text-slate-600",
    chip: "border-slate-200/70 bg-black/[0.02] hover:border-slate-300",
    chipLabel: "text-slate-500",
    rowHover: "hover:border-slate-200 hover:bg-black/[0.02]",
    rowActive: "border-emerald-400/50 bg-emerald-500/5",
    rowTitle: "text-slate-800",
    rowDomain: "text-slate-400",
    badgeIdle: "bg-black/5 text-slate-500",
  },
  dark: {
    card: "border-white/10 bg-neutral-900/90",
    answer: "text-slate-300",
    chip: "border-white/10 bg-white/[0.03] hover:border-white/20",
    chipLabel: "text-slate-400",
    rowHover: "hover:border-white/10 hover:bg-white/[0.03]",
    rowActive: "border-emerald-400/30 bg-emerald-400/5",
    rowTitle: "text-slate-100",
    rowDomain: "text-slate-500",
    badgeIdle: "bg-white/10 text-slate-400",
