export function Suggestion({
  suggestionSets,
  onSelect,
}: {
  /** One or more batches of suggestion strings; the shuffle icon cycles between batches. */
  suggestionSets: string[][];
  onSelect?: (text: string) => void;
}) {
  const [setIndex, setSetIndex] = useState(0);
  const [selected, setSelected] = useState<string | null>(null);
  const shouldReduceMotion = useReducedMotion();
  const suggestions = suggestionSets[setIndex] ?? [];

  const handleSelect = (text: string) => {
    setSelected(text);
    onSelect?.(text);
  };

  return (
    <div className="w-full max-w-md">
      <div className="mb-2.5 flex items-center justify-between">
        <p className="text-xs font-semibold uppercase tracking-wide text-slate-400 dark:text-slate-500">Suggested replies</p>
        {!selected && suggestionSets.length > 1 && (
          <button
            type="button"
            onClick={() => setSetIndex((i) => (i + 1) % suggestionSets.length)}
            aria-label="Show different suggestions"
            title="Show different suggestions"
            className="inline-flex h-7 w-7 items-center justify-center rounded-full text-slate-400 transition-colors hover:bg-black/5 hover:text-slate-600 focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-emerald-600 dark:hover:bg-white/10 dark:hover:text-slate-300"
          >
            <ShuffleIcon />
          </button>
        )}
      </div>

      <AnimatePresence mode="wait" initial={false}>
        {selected ? (
          <motion.div
            key="composer"
            initial={shouldReduceMotion ? { opacity: 0 } : { opacity: 0, y: -6, scale: 0.98 }}
            animate={{ opacity: 1, y: 0, scale: 1 }}
            transition={{ duration: 0.28, ease: [0.16, 1, 0.3, 1] }}
            className="flex items-center gap-2.5 rounded-2xl border border-emerald-500/30 bg-emerald-500/5 px-4 py-3 dark:border-emerald-400/25 dark:bg-emerald-400/5"
          >
            <span className="flex h-7 w-7 shrink-0 items-center justify-center rounded-full bg-emerald-600 text-white">
              <SendIcon />
            </span>
            <p className="flex-1 truncate text-sm font-medium text-slate-800 dark:text-slate-100">{selected}</p>
            <button
              type="button"
              onClick={() => setSelected(null)}
              className="inline-flex shrink-0 items-center gap-1.5 rounded-full px-2.5 py-1 text-xs font-medium text-slate-500 transition-colors hover:bg-black/5 hover:text-slate-700 focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-emerald-600 dark:text-slate-400 dark:hover:bg-white/10 dark:hover:text-slate-200"
            >
              <UndoIcon />
              Start over
            </button>
          </motion.div>
        ) : (
          <motion.div
            key={`row-${setIndex}`}
            initial={shouldReduceMotion ? { opacity: 0 } : { opacity: 0 }}
            animate={{ opacity: 1 }}
            exit={shouldReduceMotion ? { opacity: 0 } : { opacity: 0 }}
            transition={{ duration: 0.15 }}
            className="relative"
          >
            <div
              className="flex gap-2 overflow-x-auto pb-1 pl-0.5 pr-6 pt-0.5 scrollbar-hide"
              style={{
                WebkitMaskImage: "linear-gradient(to right, black 0, black calc(100% - 28px), transparent 100%)",
                maskImage: "linear-gradient(to right, black 0, black calc(100% - 28px), transparent 100%)",
              }}
            >
              {suggestions.map((s, i) => (
                <motion.button
                  key={s}
                  type="button"
                  onClick={() => handleSelect(s)}
                  initial={shouldReduceMotion ? { opacity: 0 } : { opacity: 0, y: 8, scale: 0.94 }}
                  animate={{ opacity: 1, y: 0, scale: 1 }}
                  transition={{ duration: 0.3, delay: i * 0.06, ease: [0.16, 1, 0.3, 1] }}
                  whileHover={shouldReduceMotion ? undefined : { y: -2 }}
                  whileTap={{ scale: 0.96 }}
                  className="group inline-flex shrink-0 items-center gap-1.5 whitespace-nowrap rounded-full border border-slate-200/70 bg-white px-3.5 py-2 text-sm font-medium text-slate-700 shadow-sm transition-colors hover:border-emerald-500/40 hover:bg-emerald-500/5 hover:text-emerald-700 focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-emerald-600 dark:border-white/10 dark:bg-neutral-950 dark:text-slate-300 dark:hover:border-emerald-400/30 dark:hover:bg-emerald-400/5 dark:hover:text-emerald-400"
                >
                  <span className="text-emerald-500 dark:text-emerald-400">
                    <SparkleIcon />
                  </span>
                  {s}
                  <span className="text-slate-300 opacity-0 transition-opacity group-hover:opacity-100 dark:text-slate-600">
                    <ArrowIcon />
                  </span>
                </motion.button>
              ))}
            </div>
          </motion.div>
        )}
      </AnimatePresence>
    </div>
  );
}

"use client";

import { Fragment, useEffect, useRef, useState } from "react";
import { AnimatePresence, motion, useReducedMotion } from "framer-motion";
import { WrenchIcon as PhWrench, ArrowClockwiseIcon as PhArrowClockwise, CheckIcon as PhCheck } from "@phosphor-icons/react";

type Status = "pending" | "running" | "success";
type ToolVariant = "ambient" | "light" | "dark";

function ReplayIcon() {
  return <PhArrowClockwise size={14} aria-hidden />;
}

function CheckIcon() {
  return <PhCheck size={11} weight="bold" aria-hidden />;
}

function formatElapsed(ms: number) {
  return `${(ms / 1000).toFixed(1)}s`;
}

const SURFACE: Record<ToolVariant, {
  card: string;
  border: string;
  iconBg: string;
  title: string;
  label: string;
  headerHover: string;
  replayHover: string;
  pendingTone: string;
}> = {
  ambient: {
    card: "border-slate-200/70 bg-white/95 dark:border-white/10 dark:bg-neutral-950/80",
    border: "border-slate-100 dark:border-white/5",
    iconBg: "bg-slate-900/5 text-slate-500 dark:bg-white/10 dark:text-slate-400",
    title: "text-slate-800 dark:text-slate-100",
    label: "text-slate-400 dark:text-slate-500",
    headerHover: "hover:bg-black/[0.03] dark:hover:bg-white/5",
    replayHover: "text-slate-400 hover:bg-black/5 hover:text-slate-600 dark:hover:bg-white/10 dark:hover:text-slate-300",
    pendingTone: "bg-slate-100 text-slate-500 dark:bg-white/5 dark:text-slate-400",
  },
  light: {
    card: "border-slate-200/70 bg-white/95",
    border: "border-slate-100",
    iconBg: "bg-slate-900/5 text-slate-500",
    title: "text-slate-800",
    label: "text-slate-400",
    headerHover: "hover:bg-black/[0.03]",
    replayHover: "text-slate-400 hover:bg-black/5 hover:text-slate-600",
    pendingTone: "bg-slate-100 text-slate-500",
  },
  dark: {
    card: "border-white/10 bg-neutral-900/90",
    border: "border-white/5",
    iconBg: "bg-white/10 text-slate-400",
    title: "text-slate-100",
    label: "text-slate-500",
    headerHover: "hover:bg-white/5",
    replayHover: "text-slate-400 hover:bg-white/10 hover:text-slate-300",
    pendingTone: "bg-white/5 text-slate-400",
  },
};

const KV_TONE: Record<ToolVariant, { key: string; value: string }> = {
  ambient: { key: "text-slate-400 dark:text-slate-500", value: "text-slate-700 dark:text-slate-200" },
  light: { key: "text-slate-400", value: "text-slate-700" },
  dark: { key: "text-slate-500", value: "text-slate-200" },
};

function KeyValueRows({ data, keyColor, valueColor }: { data: Record<string, string>; keyColor: string; valueColor: string }) {
  return (
    <div className="grid grid-cols-[auto_1fr] gap-x-3 gap-y-1.5">
      {Object.entries(data).map(([key, value]) => (
        <Fragment key={key}>
          <span className={`font-mono text-xs ${keyColor}`}>{key}</span>
          <span className={`truncate font-mono text-xs ${valueColor}`}>{value}</span>
        </Fragment>
      ))}
    </div>
  );
}

// A single, auto-playing tool call: pending -> running -> success, with a
// replay button once done.
export function Tool({
  name,
  input,
  output,
  variant = "ambient",
}: {
  name: string;
  input: Record<string, string>;
  output: Record<string, string>;
  variant?: ToolVariant;
}) {
  const [playId, setPlayId] = useState(0);
  return (
    <ToolCallRun
      key={`${name}-${playId}`}
      name={name}
      input={input}
      output={output}
      variant={variant}
      onReplay={() => setPlayId((id) => id + 1)}
    />
  );
}

function ToolCallRun({
  name,
  input,
  output,
  variant,
  onReplay,
}: {
  name: string;
  input: Record<string, string>;
  output: Record<string, string>;
  variant: ToolVariant;
  onReplay: () => void;
}) {
  const [status, setStatus] = useState<Status>("pending");
  const [elapsedMs, setElapsedMs] = useState(0);
  const startRef = useRef(0);
  const shouldReduceMotion = useReducedMotion();
  const done = status === "success";
  const tone = SURFACE[variant];
  const kv = KV_TONE[variant];

  useEffect(() => {
    const t1 = setTimeout(() => setStatus("running"), shouldReduceMotion ? 20 : 350);
    const t2 = setTimeout(() => setStatus("success"), shouldReduceMotion ? 40 : 1450);
    return () => {
      clearTimeout(t1);
      clearTimeout(t2);
    };
  }, [shouldReduceMotion]);

  useEffect(() => {
    if (status !== "running") return;
    startRef.current = performance.now();
    let raf: number;
    const tick = () => {
      setElapsedMs(performance.now() - startRef.current);
      raf = requestAnimationFrame(tick);
    };
    raf = requestAnimationFrame(tick);
    return () => cancelAnimationFrame(raf);
  }, [status]);

  return (
    <div className={`w-full max-w-md rounded-2xl border shadow-sm backdrop-blur-xl ${tone.card}`}>
      <div className="flex items-center gap-1 p-2">
        <div className={`flex flex-1 items-center gap-2.5 rounded-lg px-2 py-1.5 transition-colors ${tone.headerHover}`}>
          <span className={`flex h-7 w-7 shrink-0 items-center justify-center rounded-full ${tone.iconBg}`}>
            <PhWrench size={13} aria-hidden />
          </span>
          <span className={`flex-1 truncate font-mono text-sm font-medium ${tone.title}`}>{name}</span>
          <motion.span
            layout
            transition={{ duration: 0.2, ease: [0.16, 1, 0.3, 1] }}
            className={`inline-flex shrink-0 items-center gap-1.5 rounded-full px-2.5 py-1 text-xs font-medium ${
              done ? "bg-emerald-500/10 text-emerald-700 dark:text-emerald-400" : tone.pendingTone
            }`}
          >
            {status === "running" ? (
              <motion.span
                aria-hidden
                className="h-2.5 w-2.5 rounded-full border-2 border-current/30 border-t-current"
                animate={shouldReduceMotion ? undefined : { rotate: 360 }}
                transition={{ duration: 0.7, repeat: Infinity, ease: "linear" }}
              />
            ) : done ? (
              <CheckIcon />
            ) : (
              <span className="h-1.5 w-1.5 rounded-full bg-current" />
            )}
            <AnimatePresence mode="popLayout" initial={false}>
              <motion.span
                key={status}
                initial={shouldReduceMotion ? { opacity: 0 } : { opacity: 0, y: -4 }}
                animate={{ opacity: 1, y: 0 }}
                exit={shouldReduceMotion ? { opacity: 0 } : { opacity: 0, y: 4 }}
                transition={{ duration: 0.15 }}
              >
                {status === "pending" ? "Pending" : status === "running" ? "Running" : "Success"}
                {(status === "running" || done) && ` · ${formatElapsed(elapsedMs)}`}
              </motion.span>
            </AnimatePresence>
          </motion.span>
        </div>
        {done && (
          <button
            type="button"
            onClick={onReplay}
            aria-label="Run again"
            className={`inline-flex h-8 w-8 shrink-0 items-center justify-center rounded-lg transition-colors focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-emerald-600 ${tone.replayHover}`}
          >
            <ReplayIcon />
          </button>
        )}
      </div>

      <div className={`flex flex-col gap-3 border-t px-4 py-3 ${tone.border}`}>
        <div>
          <p className={`mb-1.5 text-[11px] font-semibold uppercase tracking-wide ${tone.label}`}>Input</p>
          <KeyValueRows data={input} keyColor={kv.key} valueColor={kv.value} />
        </div>
        <AnimatePresence>
          {done && (
            <motion.div
              initial={shouldReduceMotion ? { opacity: 0 } : { opacity: 0, y: -4 }}
              animate={{ opacity: 1, y: 0 }}
              transition={{ duration: 0.25, ease: [0.22, 1, 0.36, 1] }}
            >
              <p className={`mb-1.5 text-[11px] font-semibold uppercase tracking-wide ${tone.label}`}>Output</p>
              <KeyValueRows data={output} keyColor={kv.key} valueColor={kv.value} />
            </motion.div>
          )}
        </AnimatePresence>
      </div>
    </div>
  );
}

