];

const PREVIEW_MS = 1800;

function CheckIcon() {
  return <PhCheck size={9} weight="bold" aria-hidden />;
}

function PlayIcon() {
  return <PhPlay size={11} weight="fill" aria-hidden />;
}

function StopIcon() {
