}

function SparkleIcon() {
  return <PhSparkle size={10} weight="fill" aria-hidden />;
}

// Shared idle-bob / preview-wiggle motion so every avatar kind reads as the
// same "alive" family of cards, whether it's a gradient orb or a dropped-in
// illustration.
function useAvatarMotion(playing: boolean, blinkDelay: number): { animate?: TargetAndTransition; transition?: Transition } {
  const shouldReduceMotion = useReducedMotion();
  if (shouldReduceMotion) return {};
  return playing
    ? { animate: { scale: [1, 1.07, 1], rotate: [0, -2, 2, 0] }, transition: { duration: 0.55, repeat: Infinity, ease: "easeInOut" } }
    : { animate: { y: [0, -0.35, 0] }, transition: { duration: 3.6, repeat: Infinity, ease: "easeInOut", delay: blinkDelay * 0.3 } };
}

function OrbAvatar({
  gradient,
  glow,
  size = 52,
  playing,
  blinkDelay = 0,
}: {
  gradient: string;
  glow: string;
  size?: number;
  playing: boolean;
  blinkDelay?: number;
}) {
  const shouldReduceMotion = useReducedMotion();
  const motionProps = useAvatarMotion(playing, blinkDelay);
  return (
    <motion.div className="relative" style={{ width: size, height: size }} {...motionProps}>
      <motion.span
        aria-hidden
        className="absolute rounded-full blur-md"
        style={{ inset: -4, background: glow }}
        animate={shouldReduceMotion ? { opacity: 0.5 } : { opacity: playing ? [0.4, 0.85, 0.4] : [0.35, 0.55, 0.35] }}
        transition={{ duration: playing ? 0.8 : 3, repeat: Infinity, ease: "easeInOut" }}
      />
      <span className="relative block h-full w-full overflow-hidden rounded-full ring-1 ring-white/25" style={{ background: gradient }}>
        <span aria-hidden className="pointer-events-none absolute left-[20%] top-[14%] h-[30%] w-[30%] rounded-full bg-white/50 blur-[2px]" />
      </span>
    </motion.div>
  );
}

function GifAvatar({
  src,
  alt,
  size = 56,
  playing,
  blinkDelay = 0,
}: {
  src: string;
  alt: string;
  size?: number;
  playing: boolean;
  blinkDelay?: number;
}) {
  const motionProps = useAvatarMotion(playing, blinkDelay);
  return (
    <motion.div className="flex items-center justify-center" style={{ width: size, height: size }} {...motionProps}>
      {/* eslint-disable-next-line @next/next/no-img-element -- animated GIF; next/image re-encodes and drops animation frames */}
      <img src={src} alt={alt} className="h-full w-full object-contain" draggable={false} />
    </motion.div>
  );
}

function ThemeToggle({ checked, onChange }: { checked: boolean; onChange: () => void }) {
  const shouldReduceMotion = useReducedMotion();
  return (
    <label className="flex cursor-pointer select-none items-center gap-1.5">
      <span className="flex items-center gap-1 text-[10px] font-medium text-slate-400 dark:text-slate-500">
        <SparkleIcon />
        Fun avatars
      </span>
      <motion.button
        type="button"
        role="switch"
        aria-checked={checked}
        aria-label="Toggle illustrated animal avatars"
        onClick={onChange}
        whileTap={{ scale: 0.93 }}
        className={`relative h-5 w-9 shrink-0 rounded-full transition-colors duration-300 focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-emerald-600 ${
          checked ? "bg-emerald-600" : "bg-slate-300 dark:bg-slate-600"
        }`}
      >
        <motion.span
          animate={{ x: checked ? 16 : 2 }}
          transition={shouldReduceMotion ? { duration: 0 } : { type: "spring", stiffness: 700, damping: 32 }}
          className="absolute top-0.5 block h-4 w-4 rounded-full bg-white shadow-sm"
        />
      </motion.button>
    </label>
  );
}

export function VoiceSelector({
  defaultSelectedId,
  onSelect,
}: {
  defaultSelectedId?: string;
  onSelect?: (id: string) => void;
}) {
  const [theme, setTheme] = useState<"pro" | "fun">("pro");
  const voices = theme === "pro" ? PRO_VOICES : FUN_VOICES;
  const [selectedId, setSelectedId] = useState(defaultSelectedId ?? PRO_VOICES[0].id);
  const [previewingId, setPreviewingId] = useState<string | null>(null);
  const timeoutRef = useRef<ReturnType<typeof setTimeout> | null>(null);
  const shouldReduceMotion = useReducedMotion();

  useEffect(() => {
    return () => {
      if (timeoutRef.current) clearTimeout(timeoutRef.current);
    };
  }, []);

  const togglePreview = (id: string) => {
    if (timeoutRef.current) clearTimeout(timeoutRef.current);
    if (previewingId === id) {
      setPreviewingId(null);
      return;
    }
    setPreviewingId(id);
    timeoutRef.current = setTimeout(() => setPreviewingId(null), PREVIEW_MS);
  };

  const toggleTheme = () => {
    const nextTheme = theme === "pro" ? "fun" : "pro";
    const nextVoices = nextTheme === "pro" ? PRO_VOICES : FUN_VOICES;
    if (timeoutRef.current) clearTimeout(timeoutRef.current);
    setPreviewingId(null);
    setTheme(nextTheme);
    setSelectedId(nextVoices[0].id);
  };

  const selected = voices.find((v) => v.id === selectedId) ?? voices[0];

  return (
    <div className="w-full max-w-sm rounded-2xl border border-slate-200/70 bg-white/95 p-3 shadow-sm backdrop-blur-xl dark:border-white/10 dark:bg-neutral-950/80">
      <div className="flex items-center justify-between gap-2 px-1 pb-2 pt-1">
        <p className="text-xs font-semibold uppercase tracking-wide text-slate-400 dark:text-slate-500">Voice</p>
        <div className="flex items-center gap-3">
          <ThemeToggle checked={theme === "fun"} onChange={toggleTheme} />
          <p className="text-xs font-medium text-emerald-600 dark:text-emerald-400">{selected.name}</p>
        </div>
      </div>
      <AnimatePresence mode="wait">
        <motion.div
          key={theme}
          role="radiogroup"
          aria-label="Select a voice"
          initial={shouldReduceMotion ? { opacity: 0 } : { opacity: 0, scale: 0.97 }}
          animate={{ opacity: 1, scale: 1 }}
          exit={shouldReduceMotion ? { opacity: 0 } : { opacity: 0, scale: 0.97 }}
          transition={{ duration: 0.22, ease: [0.16, 1, 0.3, 1] }}
          className="grid grid-cols-2 gap-2"
        >
          {voices.map((v, i) => {
            const isSelected = v.id === selectedId;
            const isPlaying = previewingId === v.id;
            return (
              <div
                key={v.id}
                className={`relative rounded-xl border transition-colors ${
                  isSelected
                    ? "border-emerald-500/40 bg-emerald-500/8 dark:bg-emerald-400/10"
                    : "border-transparent hover:bg-black/[0.03] dark:hover:bg-white/5"
                }`}
              >
                <button
                  type="button"
                  role="radio"
                  aria-checked={isSelected}
                  onClick={() => {
                    setSelectedId(v.id);
                    onSelect?.(v.id);
                  }}
                  className="flex w-full flex-col items-center gap-1 rounded-xl px-2 pb-2.5 pt-3 text-center focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-emerald-600"
                >
                  <div className="relative">
                    <motion.div
                      animate={isSelected && !shouldReduceMotion ? { y: [0, -3, 0] } : undefined}
                      transition={{ duration: 0.4, ease: [0.16, 1, 0.3, 1] }}
                    >
                      {v.avatar.kind === "orb" ? (
                        <OrbAvatar gradient={v.avatar.gradient} glow={v.avatar.glow} playing={isPlaying} blinkDelay={i * 0.9} size={52} />
                      ) : (
                        <GifAvatar src={v.avatar.src} alt={v.avatar.alt} playing={isPlaying} blinkDelay={i * 0.9} size={60} />
                      )}
                    </motion.div>
                    <AnimatePresence>
                      {isSelected && (
                        <motion.span
                          aria-hidden
                          initial={{ scale: 0, opacity: 0 }}
                          animate={{ scale: 1, opacity: 1 }}
                          exit={{ scale: 0, opacity: 0 }}
                          transition={{ type: "spring", stiffness: 500, damping: 24 }}
                          className="absolute -bottom-0.5 -right-0.5 flex h-4 w-4 items-center justify-center rounded-full bg-emerald-500 text-white ring-2 ring-white dark:ring-neutral-950"
                        >
                          <CheckIcon />
                        </motion.span>
                      )}
                    </AnimatePresence>
                  </div>
                  <span className="mt-0.5 block text-xs font-medium text-slate-800 dark:text-slate-100">{v.name}</span>
                  <span className="block text-[10px] text-slate-400 dark:text-slate-500">{v.descriptor}</span>
                </button>

                <button
                  type="button"
                  onClick={() => togglePreview(v.id)}
                  aria-label={isPlaying ? `Stop preview of ${v.name}` : `Preview ${v.name}`}
                  title={isPlaying ? "Stop preview" : "Preview voice"}
                  className={`absolute right-1.5 top-1.5 inline-flex h-6 w-6 items-center justify-center rounded-full transition-colors focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-emerald-600 ${
                    isPlaying
                      ? "bg-emerald-600 text-white"
                      : "bg-black/5 text-slate-500 hover:bg-black/10 hover:text-slate-700 dark:bg-white/10 dark:text-slate-400 dark:hover:bg-white/15 dark:hover:text-slate-200"
                  }`}
                >
                  {isPlaying && (
                    <motion.span
                      aria-hidden
                      className="absolute inset-[-3px] rounded-full border border-emerald-400/50"
                      animate={shouldReduceMotion ? undefined : { scale: [1, 1.3], opacity: [0.6, 0] }}
                      transition={{ duration: 1, repeat: Infinity, ease: "easeOut" }}
                    />
                  )}
                  {isPlaying ? <StopIcon /> : <PlayIcon />}
                </button>
              </div>
            );
          })}
        </motion.div>
      </AnimatePresence>
    </div>
  );
}

"use client";

import { useEffect, useRef, useState } from "react";
import { AnimatePresence, motion } from "framer-motion";
import {
  ImageIcon as PhImage,
  FileIcon as PhFile,
  CheckIcon as PhCheck,
  XIcon as PhX,
  ArrowClockwiseIcon as PhArrowClockwise,
  PlusIcon as PhPlus,
} from "@phosphor-icons/react";

type Status = "uploading" | "done" | "error";

interface Attachment {
  id: string;
  name: string;
  size: number;
  status: Status;
  progress: number;
  speed: number;
  failAt?: number;
}

let nextId = 1;

const RADIUS = 9;
const CIRC = 2 * Math.PI * RADIUS;

function formatBytes(bytes: number) {
  if (bytes < 1024) return `${bytes} B`;
  const kb = bytes / 1024;
  if (kb < 1024) return `${kb.toFixed(kb < 10 ? 1 : 0)} KB`;
  const mb = kb / 1024;
  return `${mb.toFixed(mb < 10 ? 1 : 0)} MB`;
}

function isImage(name: string) {
  return /\.(png|jpe?g|gif|webp|svg)$/i.test(name);
}

function ImageIcon() {
  return <PhImage size={14} aria-hidden />;
}

function DocumentIcon() {
  return <PhFile size={14} aria-hidden />;
}

function CheckIcon() {
  return <PhCheck size={10} weight="bold" aria-hidden />;
}

function XIcon() {
  return <PhX size={13} aria-hidden />;
}

// A bare exclamation mark, deliberately with no outer triangle/circle of its own
// since it's always shown inside this file's own colored circular status badge.
function AlertIcon() {
  return (
    <svg viewBox="0 0 24 24" width="9" height="9" fill="none" stroke="currentColor" strokeWidth="3" strokeLinecap="round" strokeLinejoin="round" aria-hidden>
      <path d="M12 8v4" />
      <path d="M12 16h.01" />
    </svg>
  );
}

function RetryIcon() {
  return <PhArrowClockwise size={13} aria-hidden />;
}

function PlusIcon() {
  return <PhPlus size={14} aria-hidden />;
}

function FileTone({ name }: { name: string }) {
  const image = isImage(name);
  return (
    <span
      className={`flex h-8 w-8 shrink-0 items-center justify-center rounded-full ${
        image ? "bg-emerald-500/12 text-emerald-600 dark:text-emerald-400" : "bg-amber-500/12 text-amber-600 dark:text-amber-400"
      }`}
    >
      {image ? <ImageIcon /> : <DocumentIcon />}
    </span>
  );
}

function ProgressRing({ progress, status }: { progress: number; status: Status }) {
  const offset = CIRC * (1 - progress / 100);
  const color = status === "error" ? "#e11d48" : "#059669";
  return (
    <svg viewBox="0 0 24 24" width="32" height="32" className="absolute inset-0 -rotate-90" aria-hidden>
      <circle cx="12" cy="12" r={RADIUS} fill="none" stroke="currentColor" strokeWidth="2" className="text-black/5 dark:text-white/10" />
      <motion.circle
        cx="12"
        cy="12"
        r={RADIUS}
        fill="none"
        stroke={color}
        strokeWidth="2"
        strokeLinecap="round"
        strokeDasharray={CIRC}
        animate={{ strokeDashoffset: offset }}
        transition={{ duration: 0.15, ease: "linear" }}
      />
    </svg>
  );
}

export function Attachments({ initialFiles = [] }: { initialFiles?: { name: string; size: number }[] }) {
  const [attachments, setAttachments] = useState<Attachment[]>(() =>
    initialFiles.map((f) => ({ id: `i${nextId++}`, name: f.name, size: f.size, status: "uploading", progress: 0, speed: 3.5 }))
  );
  const inputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    const id = setInterval(() => {
      setAttachments((prev) =>
        prev.map((a) => {
          if (a.status !== "uploading") return a;
          const next = a.progress + a.speed;
          if (a.failAt !== undefined && next >= a.failAt) {
            return { ...a, progress: a.failAt, status: "error" };
          }
          if (next >= 100) {
            return { ...a, progress: 100, status: "done" };
          }
          return { ...a, progress: next };
        })
      );
    }, 80);
    return () => clearInterval(id);
  }, []);

  const remove = (id: string) => setAttachments((prev) => prev.filter((a) => a.id !== id));

  const retry = (id: string) =>
    setAttachments((prev) => prev.map((a) => (a.id === id ? { ...a, status: "uploading", progress: 0, failAt: undefined } : a)));

  const handleFiles = (files: FileList | null) => {
    if (!files) return;
    const added: Attachment[] = Array.from(files).map((f) => ({
      id: `f${nextId++}`,
      name: f.name,
      size: f.size,
      status: "uploading",
      progress: 0,
      speed: 3.5,
    }));
    setAttachments((prev) => [...prev, ...added]);
  };

  return (
    <div className="w-full max-w-md rounded-2xl border border-slate-200/70 bg-white/95 p-3 shadow-sm backdrop-blur-xl dark:border-white/10 dark:bg-neutral-950/80">
      <p className="px-1 pb-2 text-xs font-semibold uppercase tracking-wide text-slate-400 dark:text-slate-500">
        Attachments · {attachments.length}
      </p>
      <ul className="flex flex-col gap-1.5" role="list">
        <AnimatePresence initial={false}>
          {attachments.map((a) => (
            <motion.li
              key={a.id}
              layout
              initial={{ opacity: 0, scale: 0.96 }}
              animate={{ opacity: 1, scale: 1 }}
              exit={{ opacity: 0, scale: 0.94 }}
              transition={{ duration: 0.2, ease: [0.22, 1, 0.36, 1] }}
              className="flex items-center gap-3 rounded-xl border border-transparent bg-black/[0.02] px-2.5 py-2 dark:bg-white/[0.03]"
            >
              <div className="relative h-8 w-8 shrink-0">
                <FileTone name={a.name} />
                {a.status === "uploading" && <ProgressRing progress={a.progress} status={a.status} />}
                {a.status === "done" && (
                  <span className="absolute -bottom-0.5 -right-0.5 flex h-3.5 w-3.5 items-center justify-center rounded-full bg-emerald-600 text-white ring-2 ring-white dark:ring-neutral-950">
                    <CheckIcon />
                  </span>
                )}
                {a.status === "error" && (
                  <span className="absolute -bottom-0.5 -right-0.5 flex h-3.5 w-3.5 items-center justify-center rounded-full bg-rose-600 text-white ring-2 ring-white dark:ring-neutral-950">
                    <AlertIcon />
                  </span>
                )}
              </div>
              <div className="min-w-0 flex-1">
                <p className="truncate text-sm font-medium text-slate-800 dark:text-slate-100">{a.name}</p>
                <p className={`text-xs ${a.status === "error" ? "text-rose-600 dark:text-rose-400" : "text-slate-400 dark:text-slate-500"}`}>
                  {a.status === "uploading" ? `${Math.round(a.progress)}% · ${formatBytes(a.size)}` : a.status === "error" ? "Upload failed" : formatBytes(a.size)}
                </p>
              </div>
              <div className="flex shrink-0 items-center gap-1">
                {a.status === "error" && (
                  <button
                    type="button"
                    onClick={() => retry(a.id)}
                    aria-label={`Retry uploading ${a.name}`}
                    className="inline-flex h-7 w-7 items-center justify-center rounded-md text-slate-400 transition-colors hover:bg-black/5 hover:text-slate-600 focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-emerald-600 dark:hover:bg-white/10 dark:hover:text-slate-300"
                  >
                    <RetryIcon />
                  </button>
                )}
                <button
                  type="button"
                  onClick={() => remove(a.id)}
                  aria-label={`Remove ${a.name}`}
                  className="inline-flex h-7 w-7 items-center justify-center rounded-md text-slate-400 transition-colors hover:bg-black/5 hover:text-slate-600 focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-emerald-600 dark:hover:bg-white/10 dark:hover:text-slate-300"
                >
                  <XIcon />
                </button>
              </div>
            </motion.li>
          ))}
        </AnimatePresence>
      </ul>

      <input
        ref={inputRef}
        type="file"
        multiple
        className="sr-only"
        onChange={(e) => {
          handleFiles(e.target.files);
          e.target.value = "";
        }}
      />
      <button
        type="button"
        onClick={() => inputRef.current?.click()}
        className="mt-1.5 flex w-full items-center justify-center gap-1.5 rounded-xl border border-dashed border-slate-300 py-2 text-xs font-medium text-slate-500 transition-colors hover:border-emerald-400 hover:text-emerald-600 focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-emerald-600 dark:border-slate-700 dark:text-slate-400 dark:hover:border-emerald-500/60 dark:hover:text-emerald-400"
      >
        <PlusIcon />
        Add file
      </button>
    </div>
  );
}

"use client";

import { createContext, useContext, useEffect, useId, useMemo, useRef, useState, type ReactNode } from "react";
