  CheckIcon as PhCheck,
  XIcon as PhX,
} from "@phosphor-icons/react";

type SectionId = "general" | "notifications" | "personalization" | "profile" | "privacy" | "security";
type AccentValue = "emerald" | "amber" | "rose";

interface NavItem {
  id: SectionId;
  label: string;
  icon: (props: { className?: string }) => ReactNode;
